begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":673187,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["33400000 J.","33,4 J.","33400 J.","334000 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở áp suất tiêu chuẩn là 3,34.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở 0 C bằng","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở 0 C là<br>$Q=.m=3,34.{10}^5.100.{10}^{-3}=33400$  J.","difficultySource":"ai"},"ex":[{"exam":434,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["33400000 J.","33,4 J.","33400 J.","334000 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở áp suất tiêu chuẩn là 3,34.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở 0 C bằng","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở 0 C là<br>$Q=.m=3,34.{10}^5.100.{10}^{-3}=33400$  J.","difficultySource":"ai"}}]},{"id":673195,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":2,"options":["3S (Wb).","3.10<sup>3</sup>S (Wb).","0 (Wb).","0,9S (Wb)."],"question":"Từ thông xuyên qua diện tích S (m2) của khung dây dẫn có độ lớn bằng","difficulty":"de","explanation":"Từ thông xuyên qua diện tích S (m2) của khung dây dẫn có độ lớn bằng:<br>$\\Phi =NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)=1.3.{10}^{-3}.S.\\cos\\left(90^{\\circ}\\right)=0$  Wb.","difficultySource":"ai"},"ex":[{"exam":434,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":2,"options":["3S (Wb).","3.10<sup>3</sup>S (Wb).","0 (Wb).","0,9S (Wb)."],"question":"Từ thông xuyên qua diện tích S (m2) của khung dây dẫn có độ lớn bằng","difficulty":"de","explanation":"Từ thông xuyên qua diện tích S (m2) của khung dây dẫn có độ lớn bằng:<br>$\\Phi =NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)=1.3.{10}^{-3}.S.\\cos\\left(90^{\\circ}\\right)=0$  Wb.","difficultySource":"ai"}}]},{"id":673203,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lượng khí helium (xem là khí lí tưởng) có số mol là 0,1 mol được chứa trong một xi lanh kín, phía trên là pit-tông có thể chuyển động thẳng đứng không ma sát. Ban đầu, khi pit-tông cân bằng, nhiệt độ của khối khí là 27 C. Người ta đặt thêm lên pit-tông một quả nặng có khối lượng 15 kg, làm pit-tông dịch chuyển đi xuống một đoạn d như hình vẽ bên dưới. Quá trình nén khí diễn ra đẳng nhiệt. Biết áp suất khí quyển là 105 Pa, tiết diện ngang của pit tông bằng 1,25 dm2, gia tốc trọng trường g = 10 $m/s^2$. Bỏ qua khối lượng của pit-tông.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047062752-hinh-10.webp\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thể tích ban đầu của khối khí helium là 2,493 lít.","answer":true},{"text":"Áp suất của khối khí helium sau khi đặt quả nặng lên pit-tông là 1,12.10<sup>5</sup> Pa.","answer":true},{"text":"Độ dịch chuyển của pit-tông d xấp xỉ bằng 2 cm.","answer":true},{"text":"Trong quá trình nén đẳng nhiệt trên, nội năng của khối khí helium giảm.","answer":false}],"explanation":"a) đúng<br>Thể tích ban đầu của khối khí helium là:<br>$p_1.V_1=nRT_1$    $V_1=\\frac{nRT_1}{p_1}=\\frac{nRT_1}{p_0}=\\frac{0,1.8,31.\\left(27+273\\right)}{{10}^5}=2,493.{10}^{-3}$  m3 = 2,493 lít.<br>b) đúng<br>Áp suất của khối khí helium sau khi đặt quả nặng lên pit-tông là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p_2=p_0+\\frac{P}{S}=p_0+\\frac{mg}{S}={10}^5+\\frac{15.10}{1,25.{10}^{-2}}=1,12.{10}^5$  Pa.<br>c) đúng<br>Do nhiệt độ khối khí helium không đổi nên ta có:<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{{10}^5.2,493}{1,12.{10}^5}\\approx 2,226$  lít.<br>Độ dịch chuyển của pit-tông d bằng:<br>$d=\\frac{\\Delta V}{S}=\\frac{V_1-V_2}{S}=\\frac{2,493-2,226}{1,25}=0,2136$  dm  2 cm.<br>d) sai<br>Trong quá trình nén đẳng nhiệt trên, nội năng của khối khí helium không đổi. Vì nội năng của khí lí tưởng chỉ phụ thuộc vào nhiệt độ.","difficultySource":"ai"},"ex":[{"exam":434,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một lượng khí helium (xem là khí lí tưởng) có số mol là 0,1 mol được chứa trong một xi lanh kín, phía trên là pit-tông có thể chuyển động thẳng đứng không ma sát. Ban đầu, khi pit-tông cân bằng, nhiệt độ của khối khí là 27 C. Người ta đặt thêm lên pit-tông một quả nặng có khối lượng 15 kg, làm pit-tông dịch chuyển đi xuống một đoạn d như hình vẽ bên dưới. Quá trình nén khí diễn ra đẳng nhiệt. Biết áp suất khí quyển là 105 Pa, tiết diện ngang của pit tông bằng 1,25 dm2, gia tốc trọng trường g = 10 m/s2. Bỏ qua khối lượng của pit-tông.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047062752-hinh-10.webp\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thể tích ban đầu của khối khí helium là 2,493 lít.","answer":true},{"text":"Áp suất của khối khí helium sau khi đặt quả nặng lên pit-tông là 1,12.10<sup>5</sup> Pa.","answer":true},{"text":"Độ dịch chuyển của pit-tông d xấp xỉ bằng 2 cm.","answer":true},{"text":"Trong quá trình nén đẳng nhiệt trên, nội năng của khối khí helium giảm.","answer":false}],"explanation":"a) đúng<br>Thể tích ban đầu của khối khí helium là:<br>$p_1.V_1=nRT_1$    $V_1=\\frac{nRT_1}{p_1}=\\frac{nRT_1}{p_0}=\\frac{0,1.8,31.\\left(27+273\\right)}{{10}^5}=2,493.{10}^{-3}$  m3 = 2,493 lít.<br>b) đúng<br>Áp suất của khối khí helium sau khi đặt quả nặng lên pit-tông là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p_2=p_0+\\frac{P}{S}=p_0+\\frac{mg}{S}={10}^5+\\frac{15.10}{1,25.{10}^{-2}}=1,12.{10}^5$  Pa.<br>c) đúng<br>Do nhiệt độ khối khí helium không đổi nên ta có:<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{{10}^5.2,493}{1,12.{10}^5}\\approx 2,226$  lít.<br>Độ dịch chuyển của pit-tông d bằng:<br>$d=\\frac{\\Delta V}{S}=\\frac{V_1-V_2}{S}=\\frac{2,493-2,226}{1,25}=0,2136$  dm  2 cm.<br>d) sai<br>Trong quá trình nén đẳng nhiệt trên, nội năng của khối khí helium không đổi. Vì nội năng của khí lí tưởng chỉ phụ thuộc vào nhiệt độ.","difficultySource":"ai"}}]},{"id":673204,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một sợi dây dẫn có tiết diện ngang 1 mm2, điện trở suất 2.10<sup>8</sup> m, được uốn thành một vòng dây dẫn kín hình tròn có bán kính 25 cm. Đặt vòng dây này trong một từ trường đều, sao cho các đường sức từ vuông góc với mặt phẳng vòng dây. Độ lớn cảm ứng từ của từ trường biến thiên theo thời gian theo quy luật  $B=kt$ (t tính bằng giây) với k = 0,1 T/s.","difficulty":"kho","statements":[{"text":"Điện trở của vòng dây dẫn bằng 31,4 m.","answer":true},{"text":"Suất điện động cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng 19,625 mV.","answer":true},{"text":"Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng 0,625 mA.","answer":false},{"text":"Công suất tỏa nhiệt trên vòng dây dẫn kín đó bằng 15 W.","answer":true}],"explanation":"a) đúng<br>Điện trở của vòng dây dẫn bằng:<br>$R=\\rho \\frac{l}{S}=\\rho \\frac{2\\pi R}{S}=2.{10}^{-8}.\\frac{2.3,14.0,25}{1.{10}^{-6}}=31,4$  m.<br>b) đúng<br>Suất điện động cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{N.k.\\Delta t.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-N.k.\\pi R^2.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)\\right|$<br>Thay số, ta được:  $\\left|e_c\\right|=\\left|-1.0,1.3,14.{0,25}^2.\\cos\\left(0^{\\circ}\\right)\\right|=19,625$  mV.<br>c) sai<br>Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|i_c\\right|=\\frac{\\left|e_c\\right|}{R}=\\frac{19,625}{31,4}=0,625$  A.<br>d) sai<br>Công suất tỏa nhiệt trên vòng dây dẫn kín đó bằng:<br>$P=i_c^2.R={0,625}^2.31,4.{10}^{-3}\\approx 0,012$  W.","difficultySource":"ai"},"ex":[{"exam":434,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một sợi dây dẫn có tiết diện ngang 1 mm2, điện trở suất 2.10<sup>8</sup> m, được uốn thành một vòng dây dẫn kín hình tròn có bán kính 25 cm. Đặt vòng dây này trong một từ trường đều, sao cho các đường sức từ vuông góc với mặt phẳng vòng dây. Độ lớn cảm ứng từ của từ trường biến thiên theo thời gian theo quy luật  $B=kt$ (t tính bằng giây) với k = 0,1 T/s.","difficulty":"kho","statements":[{"text":"Điện trở của vòng dây dẫn bằng 31,4 m.","answer":true},{"text":"Suất điện động cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng 19,625 mV.","answer":true},{"text":"Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng 0,625 mA.","answer":false},{"text":"Công suất tỏa nhiệt trên vòng dây dẫn kín đó bằng 15 W.","answer":true}],"explanation":"a) đúng<br>Điện trở của vòng dây dẫn bằng:<br>$R=\\rho \\frac{l}{S}=\\rho \\frac{2\\pi R}{S}=2.{10}^{-8}.\\frac{2.3,14.0,25}{1.{10}^{-6}}=31,4$  m.<br>b) đúng<br>Suất điện động cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{N.k.\\Delta t.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-N.k.\\pi R^2.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)\\right|$<br>Thay số, ta được:  $\\left|e_c\\right|=\\left|-1.0,1.3,14.{0,25}^2.\\cos\\left(0^{\\circ}\\right)\\right|=19,625$  mV.<br>c) sai<br>Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn kín có độ lớn bằng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|i_c\\right|=\\frac{\\left|e_c\\right|}{R}=\\frac{19,625}{31,4}=0,625$  A.<br>d) sai<br>Công suất tỏa nhiệt trên vòng dây dẫn kín đó bằng:<br>$P=i_c^2.R={0,625}^2.31,4.{10}^{-3}\\approx 0,012$  W.","difficultySource":"ai"}}]},{"id":673205,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất bán rã của phóng xạ được ứng dụng để chế tạo pin hạt nhân. Gần đây, các nhà khoa học Trung Quốc phát triển pin hạt nhân đầu tiên trên thế giới sử dụng đồng vị carbon  ${}_6^{14}C$ , pin có thể hoạt động trong thời gian rất dài mà không cần sạc. Loại pin này thường được sử dụng trong các nhiệm vụ có yêu cầu đặc biệt như thiết bị y tế (máy tạo nhịp tim), tàu vũ trụ hoặc các thiết bị hoạt động trong môi trường khắc nghiệt như biển sâu hay vùng cực. Biết rằng hạt nhân  ${}_6^{14}C$  là đồng vị phóng xạ  với chu kì bán rã là 5730 năm. Độ phóng xạ ban đầu của lượng  ${}_6^{14}C$  đưa vào pin là 10 mCi. Lấy 1 năm = 365 ngày, 1 Ci = 3,7.10<sup>10</sup> Bq và khối lượng hạt nhân tính theo đơn vị u xấp xỉ bằng số khối.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047062930-hinh-11.webp\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_6^{14}C$  phóng xạ  và biến đổi thành hạt nhân  ${}_7^{14}N$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_6^{14}C$  có giá trị xấp xỉ bằng 1,2.104 s1.","answer":false},{"text":"Khối lượng ban đầu của  ${}_6^{14}C$  được đưa vào pin hạt nhân là 2,24 mg.","answer":true},{"text":"Sau 2026 năm kể từ thời điểm ban đầu, độ phóng xạ của  ${}_6^{14}C$  trong pin giảm đi khoảng 25%.","answer":false}],"explanation":"a) đúng<br>Phương trình phóng xạ:  ${}_6^{14}C\\rightarrow {}_{-1}^0e+{}_7^{14}N$<br>b) sai<br>Hằng số phóng xạ của  ${}_6^{14}C$  bằng:<br>$=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{5730.365.24.3600}\\approx 3,8.{10}^{-12}$  s1.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Khối lượng ban đầu của  ${}_6^{14}C$  được đưa vào pin hạt nhân là:<br>$m_0=n_0.M=\\frac{N_0}{N_A}.M=\\frac{H_0}{}.\\frac{M}{N_A}=\\frac{T.H_0}{\\ln\\left(2\\right)}.\\frac{M}{N_A}=\\frac{5730.365.24.3600.10.{10}^{-3}.3,7.{10}^{10}.14}{\\ln\\left(2\\right).6,02.{10}^{23}}\\approx 2,24$  mg.<br>d) sai<br>Sau 2026 năm kể từ thời điểm ban đầu, độ phóng xạ của  ${}_6^{14}C$  trong pin giảm đi:<br>$\\frac{\\Delta H}{H_0}=1-\\frac{H_t}{H_0}=1-2^{-\\frac{t}{T}}=1-2^{-\\frac{2026}{5730}}\\approx 22%$ .","difficultySource":"ai"},"ex":[{"exam":434,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất bán rã của phóng xạ được ứng dụng để chế tạo pin hạt nhân. Gần đây, các nhà khoa học Trung Quốc phát triển pin hạt nhân đầu tiên trên thế giới sử dụng đồng vị carbon  ${}_6^{14}C$ , pin có thể hoạt động trong thời gian rất dài mà không cần sạc. Loại pin này thường được sử dụng trong các nhiệm vụ có yêu cầu đặc biệt như thiết bị y tế (máy tạo nhịp tim), tàu vũ trụ hoặc các thiết bị hoạt động trong môi trường khắc nghiệt như biển sâu hay vùng cực. Biết rằng hạt nhân  ${}_6^{14}C$  là đồng vị phóng xạ  với chu kì bán rã là 5730 năm. Độ phóng xạ ban đầu của lượng  ${}_6^{14}C$  đưa vào pin là 10 mCi. Lấy 1 năm = 365 ngày, 1 Ci = 3,7.10<sup>10</sup> Bq và khối lượng hạt nhân tính theo đơn vị u xấp xỉ bằng số khối.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047062930-hinh-11.webp\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_6^{14}C$  phóng xạ  và biến đổi thành hạt nhân  ${}_7^{14}N$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_6^{14}C$  có giá trị xấp xỉ bằng 1,2.104 s1.","answer":false},{"text":"Khối lượng ban đầu của  ${}_6^{14}C$  được đưa vào pin hạt nhân là 2,24 mg.","answer":true},{"text":"Sau 2026 năm kể từ thời điểm ban đầu, độ phóng xạ của  ${}_6^{14}C$  trong pin giảm đi khoảng 25%.","answer":false}],"explanation":"a) đúng<br>Phương trình phóng xạ:  ${}_6^{14}C\\rightarrow {}_{-1}^0e+{}_7^{14}N$<br>b) sai<br>Hằng số phóng xạ của  ${}_6^{14}C$  bằng:<br>$=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{5730.365.24.3600}\\approx 3,8.{10}^{-12}$  s1.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Khối lượng ban đầu của  ${}_6^{14}C$  được đưa vào pin hạt nhân là:<br>$m_0=n_0.M=\\frac{N_0}{N_A}.M=\\frac{H_0}{}.\\frac{M}{N_A}=\\frac{T.H_0}{\\ln\\left(2\\right)}.\\frac{M}{N_A}=\\frac{5730.365.24.3600.10.{10}^{-3}.3,7.{10}^{10}.14}{\\ln\\left(2\\right).6,02.{10}^{23}}\\approx 2,24$  mg.<br>d) sai<br>Sau 2026 năm kể từ thời điểm ban đầu, độ phóng xạ của  ${}_6^{14}C$  trong pin giảm đi:<br>$\\frac{\\Delta H}{H_0}=1-\\frac{H_t}{H_0}=1-2^{-\\frac{t}{T}}=1-2^{-\\frac{2026}{5730}}\\approx 22%$ .","difficultySource":"ai"}}]},{"id":673388,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":0,"options":["9800 năm.","4900 năm.","6270 năm.","8190 năm."],"question":"Bằng phương pháp carbon 14 (chu kì bán rã của  ${}_6^{14}C$  là 5730 năm), người ta đo được độ phóng xạ của một cái đĩa bằng gỗ cổ là 5,195.10<sup>13</sup> Bq và một mẫu gỗ tươi cùng loại, cùng khối lượng là 1,7.10<sup>14</sup> Bq. Tuổi của đĩa gỗ cổ khoảng","difficulty":"trung-binh","explanation":"$H=H_0.2^{−\\frac{t}{T}}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow 5,195.10^{13}=1,7.10^{14}.2^{\\frac{−t}{5730}}$<br>$\\Rightarrow t=9800$  (năm)","difficultySource":"ai"},"ex":[{"exam":441,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":0,"options":["9800 năm.","4900 năm.","6270 năm.","8190 năm."],"question":"Bằng phương pháp carbon 14 (chu kì bán rã của  ${}_6^{14}C$  là 5730 năm), người ta đo được độ phóng xạ của một cái đĩa bằng gỗ cổ là 5,195.10<sup>13</sup> Bq và một mẫu gỗ tươi cùng loại, cùng khối lượng là 1,7.10<sup>14</sup> Bq. Tuổi của đĩa gỗ cổ khoảng","difficulty":"trung-binh","explanation":"$H=H_0.2^{−\\frac{t}{T}}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow 5,195.10^{13}=1,7.10^{14}.2^{\\frac{−t}{5730}}$<br>$\\Rightarrow t=9800$  (năm)","difficultySource":"ai"}}]},{"id":673391,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,22.10<sup>6</sup> J/kg.","2,28.10<sup>6</sup> J/kg.","2,25.10<sup>6</sup> J/kg.","2,30.10<sup>6</sup> J/kg."],"question":"Nhiệt hóa hơi riêng của nước mà học sinh này xác định được là","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}Q_{toa}=\\frac{20}{1000}.L+\\frac{20}{1000}.4180.55=50,256J Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{thu}=0,47.4180.25+25.46=50265\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q_{toa}=Q_{thu}\\Rightarrow L=2,28336.10^6\\left(J/kg\\right) Website: thukhoadaihoc.vn$<br>Từ  $20^0C$  lên 450C: thay đổi 250C","difficultySource":"ai"},"ex":[{"exam":441,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,22.10<sup>6</sup> J/kg.","2,28.10<sup>6</sup> J/kg.","2,25.10<sup>6</sup> J/kg.","2,30.10<sup>6</sup> J/kg."],"question":"Nhiệt hóa hơi riêng của nước mà học sinh này xác định được là","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}Q_{toa}=\\frac{20}{1000}.L+\\frac{20}{1000}.4180.55=50,256J Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{thu}=0,47.4180.25+25.46=50265\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q_{toa}=Q_{thu}\\Rightarrow L=2,28336.10^6\\left(J/kg\\right) Website: thukhoadaihoc.vn$<br>Từ  $20^0C$  lên 450C: thay đổi 250C","difficultySource":"ai"}}]},{"id":673418,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["512 s.","480 s.","900 s.","601 s."],"question":"Một viên nước đá khối lượng 50g đang bắt đầu tan chảy rơi ra khỏi li nước và nằm trên mặt bàn trong không khí ở nhiệt độ phòng. Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Biết công suất hấp thụ nhiệt trung bình từ môi trường (mặt bàn và không khí) của nước đá ở điều kiện bài toán là 28,3 J/s. Thời gian để viên đá tan hoàn toàn xấp xỉ là","difficulty":"trung-binh","explanation":"Đổi khối lượng nước đá:  $m=50g=0,05kg$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng cần thiết để viên nước đá tan chảy hoàn toàn là:<br>$Q=\\lambda m=3,4.10^5.0,05=17000J$<br>Thời gian để viên đá tan hoàn toàn là:  $t=\\frac{Q}{P}=\\frac{17000}{28,3}\\approx 601s$","difficultySource":"ai"},"ex":[{"exam":442,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["512 s.","480 s.","900 s.","601 s."],"question":"Một viên nước đá khối lượng 50g đang bắt đầu tan chảy rơi ra khỏi li nước và nằm trên mặt bàn trong không khí ở nhiệt độ phòng. Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Biết công suất hấp thụ nhiệt trung bình từ môi trường (mặt bàn và không khí) của nước đá ở điều kiện bài toán là 28,3 J/s. Thời gian để viên đá tan hoàn toàn xấp xỉ là","difficulty":"trung-binh","explanation":"Đổi khối lượng nước đá:  $m=50g=0,05kg$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng cần thiết để viên nước đá tan chảy hoàn toàn là:<br>$Q=\\lambda m=3,4.10^5.0,05=17000J$<br>Thời gian để viên đá tan hoàn toàn là:  $t=\\frac{Q}{P}=\\frac{17000}{28,3}\\approx 601s$","difficultySource":"ai"}}]},{"id":673422,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 00C đến khi tan chảy hết thành nước và hóa hơi ở 100°C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lấy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup>J/kg và nhiệt dung riêng của nước là4200 J/kg.K, nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup>J/kg, bỏ qua nhiệt dung của nhiệt lượng kế và sự trao đổi nhiệt với môi trường.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047131885-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi.","answer":true},{"text":"Giai đoạn OA nhiệt độ không đổi nên nội năng của nước đá không đổi.","answer":false},{"text":"Tại điểm A trên đồ thị khối nước đá vừa nóng chảy hết.","answer":true},{"text":"Tại điểm C lượng nước còn lại là 60 g.","answer":false}],"explanation":"a) đúng<br>Tại nhiệt độ 1000C, nước bắt đầu sôi và chuyển từ thể lỏng sang thể khí. Đoạn BC trên đồ thị là đường nằm ngang, cho thấy nhiệt độ không đổi trong khi khối nước vẫn nhận nhiệt lượng. Nhiệt lượng này được dùng hoàn toàn cho quá trình hóa hơi.<br>b) sai<br>Giai đoạn OA tương ứng với quá trình nước đá nóng chảy ở 00C.<br>Dù nhiệt độ không đổi nhưng hệ vẫn đang nhận nhiệt lượng từ bên ngoài. Nhiệt lượng này làm tăng thế năng tương tác giữa các phân tử, qua đó làm nội năng của khối nước đá tăng lên.<br>c) đúng<br>Đoạn OA là quá trình nóng chảy. Tại điểm O, nước đá bắt đầu nóng chảy. Khi đến điểm A, quá trình nóng chảy kết thúc, toàn bộ khối lượng nước đá đã chuyển thành nước ở 00C<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>⇒ Tại điểm A trên đồ thị khối nước đá vừa nóng chảy hết.<br>d) sai<br>Gọi m là tổng khối lượng của khối nước đá ban đầu.<br>Nhiệt lượng cần cung cấp để nước đá tan hoàn toàn (đoạn OA) là:  $Q_{OA}=m\\lambda$<br>Nhiệt lượng cần cung cấp để nước tăng nhiệt độ từ 00C đến 1000C (đoạn AB) là:<br>$Q_{AB}=m.c.\\Delta t=m.c.\\left(100−0\\right)=100.m.c$<br>Tổng nhiệt lượng hệ nhận được tính đến điểm B là:<br>$Q_B=Q_{OA}+Q_{AB}=m.\\lambda +100.m.c$<br>Dựa vào đồ thị, tại điểm B:  $Q_B=120kJ=120000J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m.3,3.10^5+100.m.4200=120000$<br>$\\Rightarrow m=0,16kg=160g$<br>Nhiệt lượng nước nhận vào để hóa hơi trong đoạn BC là:<br>$Q_{BC}=Q_C−Q_B=258−120=138kJ=138000J$<br>Gọi m/ là khối lượng nước đã hóa hơi thành hơi nước.<br>Ta có:  $Q_{BC}=m^/L\\Rightarrow 138000=m^/.2,3.10^6$<br>$\\Rightarrow m^/=0,06kg=60g$<br>Lượng nước còn lại ở thể lỏng tại điểm C là:<br>$m_{cℓ}=m−m^/=160−60=100(g)$","difficultySource":"ai"},"ex":[{"exam":442,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 00C đến khi tan chảy hết thành nước và hóa hơi ở 100°C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lấy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup>J/kg và nhiệt dung riêng của nước là4200 J/kg.K, nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup>J/kg, bỏ qua nhiệt dung của nhiệt lượng kế và sự trao đổi nhiệt với môi trường.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047131885-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi.","answer":true},{"text":"Giai đoạn OA nhiệt độ không đổi nên nội năng của nước đá không đổi.","answer":false},{"text":"Tại điểm A trên đồ thị khối nước đá vừa nóng chảy hết.","answer":true},{"text":"Tại điểm C lượng nước còn lại là 60 g.","answer":false}],"explanation":"a) đúng<br>Tại nhiệt độ 1000C, nước bắt đầu sôi và chuyển từ thể lỏng sang thể khí. Đoạn BC trên đồ thị là đường nằm ngang, cho thấy nhiệt độ không đổi trong khi khối nước vẫn nhận nhiệt lượng. Nhiệt lượng này được dùng hoàn toàn cho quá trình hóa hơi.<br>b) sai<br>Giai đoạn OA tương ứng với quá trình nước đá nóng chảy ở 00C.<br>Dù nhiệt độ không đổi nhưng hệ vẫn đang nhận nhiệt lượng từ bên ngoài. Nhiệt lượng này làm tăng thế năng tương tác giữa các phân tử, qua đó làm nội năng của khối nước đá tăng lên.<br>c) đúng<br>Đoạn OA là quá trình nóng chảy. Tại điểm O, nước đá bắt đầu nóng chảy. Khi đến điểm A, quá trình nóng chảy kết thúc, toàn bộ khối lượng nước đá đã chuyển thành nước ở 00C<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>⇒ Tại điểm A trên đồ thị khối nước đá vừa nóng chảy hết.<br>d) sai<br>Gọi m là tổng khối lượng của khối nước đá ban đầu.<br>Nhiệt lượng cần cung cấp để nước đá tan hoàn toàn (đoạn OA) là:  $Q_{OA}=m\\lambda$<br>Nhiệt lượng cần cung cấp để nước tăng nhiệt độ từ 00C đến 1000C (đoạn AB) là:<br>$Q_{AB}=m.c.\\Delta t=m.c.\\left(100−0\\right)=100.m.c$<br>Tổng nhiệt lượng hệ nhận được tính đến điểm B là:<br>$Q_B=Q_{OA}+Q_{AB}=m.\\lambda +100.m.c$<br>Dựa vào đồ thị, tại điểm B:  $Q_B=120kJ=120000J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m.3,3.10^5+100.m.4200=120000$<br>$\\Rightarrow m=0,16kg=160g$<br>Nhiệt lượng nước nhận vào để hóa hơi trong đoạn BC là:<br>$Q_{BC}=Q_C−Q_B=258−120=138kJ=138000J$<br>Gọi m/ là khối lượng nước đã hóa hơi thành hơi nước.<br>Ta có:  $Q_{BC}=m^/L\\Rightarrow 138000=m^/.2,3.10^6$<br>$\\Rightarrow m^/=0,06kg=60g$<br>Lượng nước còn lại ở thể lỏng tại điểm C là:<br>$m_{cℓ}=m−m^/=160−60=100(g)$","difficultySource":"ai"}}]},{"id":673423,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"2,4","question":"Ở gần xích đạo, cảm ứng từ của từ trường Trái Đất có thành phần nằm ngang có độ lớn bằng 3.10<sup>−5</sup>T , còn thành phần thẳng đứng rất nhỏ. Một đường dây điện nằm ngang theo hướng Đông - Tây với cường độ dòng điện không đổi 800 A . Lực từ của Trái Đất tác dụng lên đoạn dây điện dài 100 m bằng bao nhiêu N? (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Thành phần nằm ngang của từ trường Trái Đất có hướng Nam - Bắc. Đường dây điện nằm ngang có hướng Đông - Tây. Do đó, phương của dòng điện vuông góc với phương của cảm ứng từ thành phần nằm ngang $\\Rightarrow \\alpha =90^0$  .  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lực từ tác dụng lên đoạn dây là:<br>$F=IℓB_hsin\\alpha =800.100.3.10^{−5}.sin(90^0)=2,4N$<br>Tần số của dòng điện xoay chiều là:","difficultySource":"ai"},"ex":[{"exam":442,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"2,4","question":"Ở gần xích đạo, cảm ứng từ của từ trường Trái Đất có thành phần nằm ngang có độ lớn bằng 3.10<sup>−5</sup>T , còn thành phần thẳng đứng rất nhỏ. Một đường dây điện nằm ngang theo hướng Đông - Tây với cường độ dòng điện không đổi 800 A . Lực từ của Trái Đất tác dụng lên đoạn dây điện dài 100 m bằng bao nhiêu N? (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Thành phần nằm ngang của từ trường Trái Đất có hướng Nam - Bắc. Đường dây điện nằm ngang có hướng Đông - Tây. Do đó, phương của dòng điện vuông góc với phương của cảm ứng từ thành phần nằm ngang $\\Rightarrow \\alpha =90^0$  .  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lực từ tác dụng lên đoạn dây là:<br>$F=IℓB_hsin\\alpha =800.100.3.10^{−5}.sin(90^0)=2,4N$<br>Tần số của dòng điện xoay chiều là:","difficultySource":"ai"}}]},{"id":673551,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":1,"options":["60 g.","80 g.","45 g.","30 g."],"question":"Một khối khí chứa 1,2.10<sup>24</sup> phân tử. Nếu khối lượng mol của khí đó là 40 g/mol, số Avogadro 6,02.10<sup>23</sup> mol−1, khối lượng của khối khí xấp xỉ bằng","difficulty":"trung-binh","explanation":"$n=\\frac{N}{N_A}=\\frac{1,2.10^{24}}{6,02.10^{23}}\\approx 1,993mol$<br>$m=nM=1,993.40\\approx 79,7g$","difficultySource":"ai"},"ex":[{"exam":447,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":1,"options":["60 g.","80 g.","45 g.","30 g."],"question":"Một khối khí chứa 1,2.10<sup>24</sup> phân tử. Nếu khối lượng mol của khí đó là 40 g/mol, số Avogadro 6,02.10<sup>23</sup> mol−1, khối lượng của khối khí xấp xỉ bằng","difficulty":"trung-binh","explanation":"$n=\\frac{N}{N_A}=\\frac{1,2.10^{24}}{6,02.10^{23}}\\approx 1,993mol$<br>$m=nM=1,993.40\\approx 79,7g$","difficultySource":"ai"}}]},{"id":673552,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["350 kJ.","350 J.","3,15.10<sup>4</sup> kJ.","31,5 kJ."],"question":"Biết nhiệt nóng chảy riêng của bạc là 1, 05.105 J/kg. Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn khối bạc có khối lượng 300 kg bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy được tính theo công thức $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng và $m$ là khối lượng vật.</p><p class=\"text-base leading-relaxed my-2\">Với $\\lambda = 1{,}05.10^5\\ \\text{J/kg}$ và $m = 300\\ \\text{kg}$:</p><p class=\"text-base leading-relaxed my-2\">$Q = 1{,}05.10^5 \\cdot 300 = 3{,}15.10^7\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 3{,}15.10^4\\ \\text{kJ}$</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt lượng cần thiết là $3{,}15.10^4\\ \\text{kJ}$, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":447,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["350 kJ.","350 J.","3,15.10<sup>4</sup> kJ.","31,5 kJ."],"question":"Biết nhiệt nóng chảy riêng của bạc là 1, 05.105 J/kg. Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn khối bạc có khối lượng 300 kg bằng","difficulty":"de","explanation":"$Q=m\\lambda =300.1,05.10^5=3,15.10^7J=3,15.10^4kJ$","difficultySource":"ai"}}]},{"id":673554,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["23.106 J/kg.","2,1. 10<sup>6</sup> J/kg.","2,3.10<sup>6</sup> J/kg.","21.106 J/kg."],"question":"Khi thực hành trong phòng thí nghiệm, một học sinh cho một lượng hơi nước ở 1000C ngưng tụ trong một nhiệt lượng kế chứa 0,35 kg nước ở 100C. Kết quả là nhiệt độ của nước tăng lên đến 420C và khối lượng nước trong nhiệt lượng kế tăng thêm 0,020 kg. Biết nhiệt dung riêng của nước là cn = 4200 J/kg. K. Nhiệt hoá hơi riêng của nước trong thí nghiệm này bằng","difficulty":"trung-binh","explanation":"$m_hL+m_hc\\left(t_h−t\\right)=m_nc\\left(t−t_n\\right)$<br>$\\Rightarrow 0,02.L+0,02.4200.\\left(100−42\\right)=0,35.4200.\\left(42−10\\right)$<br>$\\Rightarrow L=2108400\\left(J/kg\\right)=2,1.10^6\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":447,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["23.106 J/kg.","2,1. 10<sup>6</sup> J/kg.","2,3.10<sup>6</sup> J/kg.","21.106 J/kg."],"question":"Khi thực hành trong phòng thí nghiệm, một học sinh cho một lượng hơi nước ở 1000C ngưng tụ trong một nhiệt lượng kế chứa 0,35 kg nước ở 100C. Kết quả là nhiệt độ của nước tăng lên đến 420C và khối lượng nước trong nhiệt lượng kế tăng thêm 0,020 kg. Biết nhiệt dung riêng của nước là cn = 4200 J/kg. K. Nhiệt hoá hơi riêng của nước trong thí nghiệm này bằng","difficulty":"trung-binh","explanation":"$m_hL+m_hc\\left(t_h−t\\right)=m_nc\\left(t−t_n\\right)$<br>$\\Rightarrow 0,02.L+0,02.4200.\\left(100−42\\right)=0,35.4200.\\left(42−10\\right)$<br>$\\Rightarrow L=2108400\\left(J/kg\\right)=2,1.10^6\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":673558,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Hình vẽ bên biểu diễn hệ thống làm mát của động cơ ô tô. Nước làm mát sẽ hấp thụ nhiệt tỏa ra từ động cơ, sau đó được bơm qua các lá tản nhiệt. Tại đây, nước được làm mát bởi luồng khí từ quạt để hạ về nhiệt độ ban đầu. Trong một lần thử nghiệm hệ thống này, các số liệu được thống kê ở bảng. Cho rằng, khi nhiên liệu bị đốt cháy hoàn toàn thì 30% nhiệt năng từ nhiên liệu sẽ chuyển hóa thành cơ năng có ích.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047185076-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Dung dịch làm mát nên dùng các chất có nhiệt dung riêng nhỏ để dễ hấp thụ nhiệt lượng tỏa ra từ động cơ.","answer":false},{"text":"Phần nhiệt năng từ nhiên liệu chuyển thành công có ích khoảng 1,1.10<sup>6</sup> J.","answer":true},{"text":"Khi 1 kg nước tăng thêm 10C thì nó tỏa ra một nhiệt lượng là 4,2 kJ.","answer":false},{"text":"Nhiệt độ của dòng không khí sau khi đi qua các cánh tản nhiệt là 68,60C.","answer":true}],"explanation":"a) sai<br>Có nhiệt dung riêng lớn<br>b) đúng<br>$Q=qm=4,6.10^7.0,08=3,68.10^6J$<br>$A=HQ=0,3.3,68.10^6=1,104.10^6J$<br>c) sai<br>Khi 1kg nước tăng thêm 10C thì nó thu vào một nhiệt lượng 4,2kJ<br>d) đúng<br>$m_nc_n\\left(t_n−t_m\\right)=m_{kk}c_{kk}\\left(t−t_{kk}\\right)\\Rightarrow 0,22.4200.\\left(80−30\\right)=1,25.760.\\left(t−20\\right)\\Rightarrow t\\approx 68,6^0C$","difficultySource":"ai"},"ex":[{"exam":447,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Hình vẽ bên biểu diễn hệ thống làm mát của động cơ ô tô. Nước làm mát sẽ hấp thụ nhiệt tỏa ra từ động cơ, sau đó được bơm qua các lá tản nhiệt. Tại đây, nước được làm mát bởi luồng khí từ quạt để hạ về nhiệt độ ban đầu. Trong một lần thử nghiệm hệ thống này, các số liệu được thống kê ở bảng. Cho rằng, khi nhiên liệu bị đốt cháy hoàn toàn thì 30% nhiệt năng từ nhiên liệu sẽ chuyển hóa thành cơ năng có ích.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047185076-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Dung dịch làm mát nên dùng các chất có nhiệt dung riêng nhỏ để dễ hấp thụ nhiệt lượng tỏa ra từ động cơ.","answer":false},{"text":"Phần nhiệt năng từ nhiên liệu chuyển thành công có ích khoảng 1,1.10<sup>6</sup> J.","answer":true},{"text":"Khi 1 kg nước tăng thêm 10C thì nó tỏa ra một nhiệt lượng là 4,2 kJ.","answer":false},{"text":"Nhiệt độ của dòng không khí sau khi đi qua các cánh tản nhiệt là 68,60C.","answer":true}],"explanation":"a) sai<br>Có nhiệt dung riêng lớn<br>b) đúng<br>$Q=qm=4,6.10^7.0,08=3,68.10^6J$<br>$A=HQ=0,3.3,68.10^6=1,104.10^6J$<br>c) sai<br>Khi 1kg nước tăng thêm 10C thì nó thu vào một nhiệt lượng 4,2kJ<br>d) đúng<br>$m_nc_n\\left(t_n−t_m\\right)=m_{kk}c_{kk}\\left(t−t_{kk}\\right)\\Rightarrow 0,22.4200.\\left(80−30\\right)=1,25.760.\\left(t−20\\right)\\Rightarrow t\\approx 68,6^0C$","difficultySource":"ai"}}]},{"id":673570,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":0,"options":["13,9 Bq.","9,13 Bq.","21,3 Bq.","31 Bq."],"question":"Potassium (Kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có 0,0117% là đồng vị phóng xạ 1940K với chu kì bán rã là 1,25.10<sup>9</sup> năm (1 năm = 365 ngày). Chuối, khoai tây, khoai lang là những thực phẩm hàm lượng potassium cao. Một quả chuối trung bình chứa khoảng 450 mg potassium. Độ phóng xạ của lượng potassium đó là","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{450.10^{−3}.0,00117/100}{40}=1,31625.10^{−6} mol$<br>$N=nN_A=1,31625.10^{−6}.6,02.10^{23}\\approx 7,9.10^{17}$<br>$H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{1,25.10^9.365.24.60.60}.7,9.10^{17}\\approx 13,9(Bq)$","difficultySource":"ai"},"ex":[{"exam":448,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":0,"options":["13,9 Bq.","9,13 Bq.","21,3 Bq.","31 Bq."],"question":"Potassium (Kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có 0,0117% là đồng vị phóng xạ 1940K với chu kì bán rã là 1,25.10<sup>9</sup> năm (1 năm = 365 ngày). Chuối, khoai tây, khoai lang là những thực phẩm hàm lượng potassium cao. Một quả chuối trung bình chứa khoảng 450 mg potassium. Độ phóng xạ của lượng potassium đó là","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{450.10^{−3}.0,00117/100}{40}=1,31625.10^{−6} mol$<br>$N=nN_A=1,31625.10^{−6}.6,02.10^{23}\\approx 7,9.10^{17}$<br>$H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{1,25.10^9.365.24.60.60}.7,9.10^{17}\\approx 13,9(Bq)$","difficultySource":"ai"}}]},{"id":673583,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Hình bên mô phỏng một thiết bị báo động nhiệt độ đơn giản. Một xi lanh dẫn nhiệt tốt được cố định trên mặt phẳng nằm ngang. Nhiệt độ trong xi lanh và môi trường bằng nhau. Piston mỏng khối lượng m = 1 kg và tiết diện ngang 10 cm3 bịt kín một lượng khí lí tưởng. Vật nặng M = 2 kg treo phía trên piston bằng sợi dây nhẹ, không dãn. Ban đầu, nhiệt độ trong xi lanh là 270C, khoảng cách giữa piston và đáy xi lanh là H = 10 cm, khoảng cách giữa đáy vật piston là h = 1 cm. Nung nóng chậm khí trong xi lanh, piston dịch chuyển đi lên. Khi piston chạm vào vật M và đẩy vật làm lực căng dây treo giảm đi một nửa so với ban đầu thì còi báo động phát âm thanh. Bỏ qua ma sát giữa piston với xi lanh. Áp H suất khí quyển là p0 = 105 Pa và gia tốc rơi tự do là g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047190966-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất khí trong xi lanh khi còi bắt đầu phát ra âm thanh báo động là 1,3.10<sup>5</sup> Pa.","answer":false},{"text":"Nhiệt độ trong xi lanh khi còi bắt đầu phát ra âm thanh báo động là 870C.","answer":true},{"text":"Nhiệt độ trong xi lanh khi piston vừa tiếp xúc với vật nặng M là 470C.","answer":false},{"text":"Ban đầu áp suất khí trong xi lanh là 1,1.10<sup>5</sup> Pa.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Dữ kiện: $S=10$ cm$^2=10^{-3}$ m$^2$ (đề viết cm$^3$ là nhầm đơn vị); $p_0=10^5$ Pa; $T_1=300$ K; $H=10$ cm; $h=1$ cm.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Ban đầu piston cân bằng: $p_1S=p_0S+mg$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p_1=p_0+\\dfrac{mg}{S}=10^5+\\dfrac{10}{10^{-3}}=1{,}1\\cdot10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Từ lúc đầu đến khi piston chạm vật M là quá trình đẳng áp ($p=p_1$): $\\dfrac{H}{T_1}=\\dfrac{H+h}{T_2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T_2=300\\cdot\\dfrac{11}{10}=330$ K $=57^\\circ C$, không phải $47^\\circ C$.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. Ban đầu lực căng dây bằng $Mg=20$ N; còi kêu khi lực căng giảm còn 10 N nên piston đẩy M lên một lực 10 N. Cân bằng piston: $pS=p_0S+mg+10$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p=10^5+\\dfrac{10+10}{10^{-3}}=1{,}2\\cdot10^5$ Pa, không phải $1{,}3\\cdot10^5$ Pa.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Thể tích khi còi kêu vẫn ứng với chiều cao $11$ cm (piston bị vật M giữ): $\\dfrac{p_1H}{T_1}=\\dfrac{p\\,(H+h)}{T_3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T_3=300\\cdot\\dfrac{1{,}2\\cdot11}{1{,}1\\cdot10}=360$ K $=87^\\circ C$.</p>","difficultySource":"ai"},"ex":[{"exam":448,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Hình bên mô phỏng một thiết bị báo động nhiệt độ đơn giản. Một xi lanh dẫn nhiệt tốt được cố định trên mặt phẳng nằm ngang. Nhiệt độ trong xi lanh và môi trường bằng nhau. Piston mỏng khối lượng m = 1 kg và tiết diện ngang 10 cm3 bịt kín một lượng khí lí tưởng. Vật nặng M = 2 kg treo phía trên piston bằng sợi dây nhẹ, không dãn. Ban đầu, nhiệt độ trong xi lanh là 270C, khoảng cách giữa piston và đáy xi lanh là H = 10 cm, khoảng cách giữa đáy vật piston là h = 1 cm. Nung nóng chậm khí trong xi lanh, piston dịch chuyển đi lên. Khi piston chạm vào vật M và đẩy vật làm lực căng dây treo giảm đi một nửa so với ban đầu thì còi báo động phát âm thanh. Bỏ qua ma sát giữa piston với xi lanh. Áp H suất khí quyển là p0 = 105 Pa và gia tốc rơi tự do là g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047190966-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất khí trong xi lanh khi còi bắt đầu phát ra âm thanh báo động là 1,3.10<sup>5</sup> Pa.","answer":true},{"text":"Nhiệt độ trong xi lanh khi còi bắt đầu phát ra âm thanh báo động là 870C.","answer":false},{"text":"Nhiệt độ trong xi lanh khi piston vừa tiếp xúc với vật nặng M là 470C.","answer":false},{"text":"Ban đầu áp suất khí trong xi lanh là 1,1.10<sup>5</sup> Pa.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":673611,"nq":{"form":"bai_tap","type":"true_false","topic":"Từ thông. Hiện tượng cảm ứng điện từ","question":"Khi chụp cộng hưởng từ (MRI), người bệnh không được mang các vật bằng kim loại vào phòng chụp. Từ trường thay đổi, làm xuất hiện dòng điện cảm ứng trong vòng dây kim loại. Dòng điện này có thể gây nóng, bỏng hoặc thậm chí hút chặt vật kim loại vào máy MRI với lực lớn, đe dọa nghiêm trọng đến sự an toàn của bệnh nhân.<br>Xét một vòng dây kim loại tròn có diện tích 100 cm2, điện trở 4 Ω nằm trong từ trường đều của máy MRI. Mặt phẳng vòng dây đặt vuông góc với vectơ cảm ứng từ của từ trường do máy tạo ra. Ban đầu, cảm ứng từ có độ lớn 0,6 T và có chiều như hình vẽ. Cho độ lớn cảm ứng từ tăng đều đến 1,4 T trong thời gian 0,25 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047196934-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197143-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong vòng dây xuất hiện dòng điện cảm ứng.","answer":true},{"text":"Chiều dòng điện cảm ứng xuất hiện trong vòng dây cùng chiều kim đồng hồ.","answer":true},{"text":"Độ lớn suất điện động cảm ứng xuất hiện trong vòng dây là 3,2 V.","answer":false},{"text":"Công suất tỏa nhiệt trên vòng dây là 2,65.10<sup>−4</sup> W.","answer":false}],"explanation":"a) đúng<br>Do độ lớn cảm ứng từ thay đổi (tăng đều) nên từ thông xuyên qua vòng dây biến thiên (tăng) làm xuất hiện dòng điện cảm ứng trong vòng dây.<br>b) đúng<br>Do từ thông xuyên qua vòng dây tăng nên  $\\vec{B}_C$   ngược hướng với vector cảm ứng từ  $\\vec{B}$  của từ trường máy MRI. Dùng quy tắc nắm bàn tay phải ta xác định được chiều dòng điện cảm ứng cùng chiều quay của kim đồng hồ.<br>c) sai<br>Độ lớn suất điện động cảm ứng xuất hiện trong vòng dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197298-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) sai<br>Công suất tỏa nhiệt trên vòng dây là:<br>$P=\\frac{{\\left|e_C\\right|}^2}{R}=\\frac{0,032^2}{4}=2,56.10^{−4}W$","difficultySource":"ai"},"ex":[{"exam":449,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Từ thông. Hiện tượng cảm ứng điện từ","question":"Khi chụp cộng hưởng từ (MRI), người bệnh không được mang các vật bằng kim loại vào phòng chụp. Từ trường thay đổi, làm xuất hiện dòng điện cảm ứng trong vòng dây kim loại. Dòng điện này có thể gây nóng, bỏng hoặc thậm chí hút chặt vật kim loại vào máy MRI với lực lớn, đe dọa nghiêm trọng đến sự an toàn của bệnh nhân.<br>Xét một vòng dây kim loại tròn có diện tích 100 cm2, điện trở 4 Ω nằm trong từ trường đều của máy MRI. Mặt phẳng vòng dây đặt vuông góc với vectơ cảm ứng từ của từ trường do máy tạo ra. Ban đầu, cảm ứng từ có độ lớn 0,6 T và có chiều như hình vẽ. Cho độ lớn cảm ứng từ tăng đều đến 1,4 T trong thời gian 0,25 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047196934-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197143-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong vòng dây xuất hiện dòng điện cảm ứng.","answer":true},{"text":"Chiều dòng điện cảm ứng xuất hiện trong vòng dây cùng chiều kim đồng hồ.","answer":true},{"text":"Độ lớn suất điện động cảm ứng xuất hiện trong vòng dây là 3,2 V.","answer":false},{"text":"Công suất tỏa nhiệt trên vòng dây là 2,65.10<sup>−4</sup> W.","answer":false}],"explanation":"a) đúng<br>Do độ lớn cảm ứng từ thay đổi (tăng đều) nên từ thông xuyên qua vòng dây biến thiên (tăng) làm xuất hiện dòng điện cảm ứng trong vòng dây.<br>b) đúng<br>Do từ thông xuyên qua vòng dây tăng nên  $\\vec{B}_C$   ngược hướng với vector cảm ứng từ  $\\vec{B}$  của từ trường máy MRI. Dùng quy tắc nắm bàn tay phải ta xác định được chiều dòng điện cảm ứng cùng chiều quay của kim đồng hồ.<br>c) sai<br>Độ lớn suất điện động cảm ứng xuất hiện trong vòng dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197298-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) sai<br>Công suất tỏa nhiệt trên vòng dây là:<br>$P=\\frac{{\\left|e_C\\right|}^2}{R}=\\frac{0,032^2}{4}=2,56.10^{−4}W$","difficultySource":"ai"}}]},{"id":673612,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Potassium (kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có 0,0117% là đồng vị phóng xạ  ${}_{19}^{40}K$ với chu kì bán rã là 1,25.10<sup>9</sup> năm. Biết phóng xạ  ${}_{19}^{40}K$  là phóng xạ β−. Chuối, khoai tây, khoai lang là những thực phẩm có hàm lượng potassium cao. Một củ khoai lang cỡ vừa trung bình chứa khoảng 500 mg potassium.","difficulty":"kho","statements":[{"text":"Tia phóng xạ β− phát ra từ nguồn phóng xạ khi đi vào vùng điện trường giữa hai bản kim loại nhiễm điện trái dấu thì bị lệch về phía bản kim loại nhiễm điện dương.","answer":true},{"text":"Coi 1 năm có 365 ngày thì hằng số phóng xạ của  ${}_{19}^{40}K$  bằng 5,545.10<sup>−10</sup> s−1.","answer":false},{"text":"Khối lượng  ${}_{19}^{40}K$  có trong một củ khoai lang cỡ vừa bằng 5,85 mg.","answer":false},{"text":"Độ phóng xạ của lượng potassium có trong một rổ có 6 củ khoai lang cỡ vừa bằng 92,87 Bq.","answer":true}],"explanation":"a) đúng<br>Tia phóng xạ β− gồm các hạt electron phát ra từ nguồn phóng xạ khi đi vào vùng điện trường giữa hai bản kim loại nhiễm điện trái dấu thì bị lệch về phía bản kim loại nhiễm điện dương do lực điện của điện trường  $\\vec{F}=q.\\vec{E}$  (q < 0 nên  $\\vec{F}$  ngược hướng với  $\\vec{E}$  ).<br>b) sai<br>Coi 1 năm có 365 ngày thì hằng số phóng xạ của  ${}_{19}^{40}K$  bằng:<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{1,25.10^9.365.24.3600}\\approx 1,758.10^{−17}s^{−1}$<br>c) sai<br>Khối lượng  ${}_{19}^{40}K$  có trong một củ khoai lang cỡ vừa bằng:<br>𝑚 = 0,0117%.500 = 0,0585 mg.<br>d) đúng<br>Độ phóng xạ của lượng potassium có trong một rổ có 6 củ khoai lang cỡ vừa bằng:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197525-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":449,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Potassium (kali) là nguyên tố dinh dưỡng khoáng thiết yếu đối với cây trồng. Trong potassium tự nhiên có 0,0117% là đồng vị phóng xạ  ${}_{19}^{40}K$ với chu kì bán rã là 1,25.10<sup>9</sup> năm. Biết phóng xạ  ${}_{19}^{40}K$  là phóng xạ β−. Chuối, khoai tây, khoai lang là những thực phẩm có hàm lượng potassium cao. Một củ khoai lang cỡ vừa trung bình chứa khoảng 500 mg potassium.","difficulty":"kho","statements":[{"text":"Tia phóng xạ β− phát ra từ nguồn phóng xạ khi đi vào vùng điện trường giữa hai bản kim loại nhiễm điện trái dấu thì bị lệch về phía bản kim loại nhiễm điện dương.","answer":true},{"text":"Coi 1 năm có 365 ngày thì hằng số phóng xạ của  ${}_{19}^{40}K$  bằng 5,545.10<sup>−10</sup> s−1.","answer":false},{"text":"Khối lượng  ${}_{19}^{40}K$  có trong một củ khoai lang cỡ vừa bằng 5,85 mg.","answer":false},{"text":"Độ phóng xạ của lượng potassium có trong một rổ có 6 củ khoai lang cỡ vừa bằng 92,87 Bq.","answer":true}],"explanation":"a) đúng<br>Tia phóng xạ β− gồm các hạt electron phát ra từ nguồn phóng xạ khi đi vào vùng điện trường giữa hai bản kim loại nhiễm điện trái dấu thì bị lệch về phía bản kim loại nhiễm điện dương do lực điện của điện trường  $\\vec{F}=q.\\vec{E}$  (q < 0 nên  $\\vec{F}$  ngược hướng với  $\\vec{E}$  ).<br>b) sai<br>Coi 1 năm có 365 ngày thì hằng số phóng xạ của  ${}_{19}^{40}K$  bằng:<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{1,25.10^9.365.24.3600}\\approx 1,758.10^{−17}s^{−1}$<br>c) sai<br>Khối lượng  ${}_{19}^{40}K$  có trong một củ khoai lang cỡ vừa bằng:<br>𝑚 = 0,0117%.500 = 0,0585 mg.<br>d) đúng<br>Độ phóng xạ của lượng potassium có trong một rổ có 6 củ khoai lang cỡ vừa bằng:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047197525-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":673673,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"4,1","question":"Năng lượng tỏa ra khi 500 g  ${}_{92}^{235}U$ phân hạch là x.10<sup>13</sup> J. Tìm giá trị của x (Kết quả làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{92}^{235}U$  có trong 500 gam là:<br>$N=\\frac{m}{M}.N_A=\\frac{500}{235}.6,02.10^{23}\\approx 1,28085.10^{24}$  hạt<br>Năng lượng tỏa ra khi toàn bộ số hạt này phân hạch:<br>E = N.ΔE =1,28085.1024.200MeV  $\\approx$   4,0987.10<sup>13</sup> J.<br>So sánh với dạng x.10<sup>13</sup> J, ta có x  $\\approx$  4,1.","difficultySource":"ai"},"ex":[]},{"id":673750,"nq":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Cung cấp nhiệt lượng cho một viên nước đá tinh khiết có khối lượng 180 g ở 0°C chuyển từ thể rắn sang thể lỏng và hóa hơi hoàn toàn. Đồ thị biểu diễn nhiệt độ t theo nhiệt lượng cung cấp Q được mô tả như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240442-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cần cung cấp để nhiệt độ của nước tăng từ 00C đến 1000C là 75 kJ.","answer":true},{"text":"Nhiệt lượng cần cung cấp để hóa lỏng hoàn toàn viên nước đá ở 00C là 60 J.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá ở 0°C là 3,33.10<sup>6</sup> J/kg.","answer":false},{"text":"Nhiệt độ sôi của nước là 1000C","answer":true}],"explanation":"a) đúng<br>Trong giai đoạn nước (thể lỏng) tăng nhiệt độ, nhiệt lượng thu vào tỉ lệ thuận với độ tăng nhiệt độ (ΔQ = mcΔt).  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta thấy để tăng thêm 800C (từ 00C lên 800C ) cần 60 kJ .<br>Vậy để nhiệt độ tăng thêm 1000C (từ 00C lên 1000C ), nhiệt lượng cần cung cấp là:<br>$Q=\\frac{60}{80}.100=75\\left(kJ\\right)$<br>b) sai<br>Nhìn vào đồ thị, giai đoạn nằm ngang đầu tiên tương ứng với quá trình viên nước đá hóa lỏng. Trục hoành sử dụng đơn vị là kJ. Do đó, nhiệt lượng cần cung cấp là 60 kJ (tương đương 60000 J), chứ không phải 60 J.<br>c) sai<br>Đổi khối lượng nước đá: m = 180 g = 0,18 kg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng cần cung cấp để hóa lỏng hoàn toàn viên nước đá là Qnc = 60 kJ = 60000 J.<br>Nhiệt nóng chảy riêng của nước đá là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240608-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Quá trình hóa hơi hoàn toàn tương ứng với đoạn đồ thị nằm ngang thứ hai. Theo phân tích chia ô trên trục tung ở phần đầu, đoạn nằm ngang này ứng với mốc nhiệt độ 100C . Đây chính là nhiệt độ sôi của nước.","difficultySource":"ai"},"ex":[{"exam":454,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Cung cấp nhiệt lượng cho một viên nước đá tinh khiết có khối lượng 180 g ở 0°C chuyển từ thể rắn sang thể lỏng và hóa hơi hoàn toàn. Đồ thị biểu diễn nhiệt độ t theo nhiệt lượng cung cấp Q được mô tả như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240442-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cần cung cấp để nhiệt độ của nước tăng từ 00C đến 1000C là 75 kJ.","answer":true},{"text":"Nhiệt lượng cần cung cấp để hóa lỏng hoàn toàn viên nước đá ở 00C là 60 J.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá ở 0°C là 3,33.10<sup>6</sup> J/kg.","answer":false},{"text":"Nhiệt độ sôi của nước là 1000C","answer":true}],"explanation":"a) đúng<br>Trong giai đoạn nước (thể lỏng) tăng nhiệt độ, nhiệt lượng thu vào tỉ lệ thuận với độ tăng nhiệt độ (ΔQ = mcΔt).  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta thấy để tăng thêm 800C (từ 00C lên 800C ) cần 60 kJ .<br>Vậy để nhiệt độ tăng thêm 1000C (từ 00C lên 1000C ), nhiệt lượng cần cung cấp là:<br>$Q=\\frac{60}{80}.100=75\\left(kJ\\right)$<br>b) sai<br>Nhìn vào đồ thị, giai đoạn nằm ngang đầu tiên tương ứng với quá trình viên nước đá hóa lỏng. Trục hoành sử dụng đơn vị là kJ. Do đó, nhiệt lượng cần cung cấp là 60 kJ (tương đương 60000 J), chứ không phải 60 J.<br>c) sai<br>Đổi khối lượng nước đá: m = 180 g = 0,18 kg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng cần cung cấp để hóa lỏng hoàn toàn viên nước đá là Qnc = 60 kJ = 60000 J.<br>Nhiệt nóng chảy riêng của nước đá là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240608-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Quá trình hóa hơi hoàn toàn tương ứng với đoạn đồ thị nằm ngang thứ hai. Theo phân tích chia ô trên trục tung ở phần đầu, đoạn nằm ngang này ứng với mốc nhiệt độ 100C . Đây chính là nhiệt độ sôi của nước.","difficultySource":"ai"}}]},{"id":673752,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Cho nhiệt hóa hơi của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1 kg nước ở nhiệt độ sôi là bao nhiêu MJ (kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn khối lượng m = 1 kg nước ở nhiệt độ sôi là:<br>Q = 2,3.106.1= 2,3.10<sup>6</sup> J = 2,3MJ .","difficultySource":"ai"},"ex":[{"exam":454,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Cho nhiệt hóa hơi của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1 kg nước ở nhiệt độ sôi là bao nhiêu MJ (kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn khối lượng m = 1 kg nước ở nhiệt độ sôi là:<br>Q = 2,3.106.1= 2,3.10<sup>6</sup> J = 2,3MJ .","difficultySource":"ai"}}]},{"id":673753,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"0,15","question":"Một khung dây phẳng có diện tích 25 cm2 gồm 10 vòng dây, đặt trong từ trường đều, mặt phẳng khung vuông góc với các đường cảm ứng từ. Cảm ứng từ biến thiên theo thời gian như đồ thị hình vẽ. Suất điện động cảm ứng xuất hiện trong khung kể từ t = 0 đến t = 0, 4 s có độ lớn bằng bao nhiêu mV (kết quả làm tròn đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240939-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đổi đơn vị diện tích: S = 25 cm2 = 25.10<sup>−4</sup> m2.<br>Mặt phẳng khung dây vuông góc với các đường cảm ứng từ nên góc hợp bởi vectơ pháp tuyến của mặt phẳng khung dây và vectơ cảm ứng từ là  $\\alpha =0^0\\Rightarrow cos(0^0)=1$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Dựa vào đồ thị, độ biến thiên cảm ứng từ trong khoảng thời gian Δt = 0,4 - 0 = 0,4 s là:<br>ΔB = B2 - B1 = 0 - 2,4mT = -2,4.10<sup>−3</sup> T .<br>Độ lớn suất điện động cảm ứng xuất hiện trong khung dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047241112-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":454,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"0,15","question":"Một khung dây phẳng có diện tích 25 cm2 gồm 10 vòng dây, đặt trong từ trường đều, mặt phẳng khung vuông góc với các đường cảm ứng từ. Cảm ứng từ biến thiên theo thời gian như đồ thị hình vẽ. Suất điện động cảm ứng xuất hiện trong khung kể từ t = 0 đến t = 0, 4 s có độ lớn bằng bao nhiêu mV (kết quả làm tròn đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047240939-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đổi đơn vị diện tích: S = 25 cm2 = 25.10<sup>−4</sup> m2.<br>Mặt phẳng khung dây vuông góc với các đường cảm ứng từ nên góc hợp bởi vectơ pháp tuyến của mặt phẳng khung dây và vectơ cảm ứng từ là  $\\alpha =0^0\\Rightarrow cos(0^0)=1$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Dựa vào đồ thị, độ biến thiên cảm ứng từ trong khoảng thời gian Δt = 0,4 - 0 = 0,4 s là:<br>ΔB = B2 - B1 = 0 - 2,4mT = -2,4.10<sup>−3</sup> T .<br>Độ lớn suất điện động cảm ứng xuất hiện trong khung dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047241112-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":673757,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"3","question":"Một xilanh một đầu bịt kín chứa khí lí tưởng có áp suất 105 Pa. Ấn pit-tông từ từ để nén khí sao cho nhiệt độ khí trong xilanh không thay đổi. Khi thể tích của khí trong xilanh giảm đi 4 lần thì áp suất của khí tăng thêm 3.10<sup>5</sup> Pa. Giá trị của a là bao nhiêu? (kết quả làm tròn đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"Trạng thái ban đầu (1): Áp suất p1 = 105 Pa , thể tích V1 =V .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trạng thái sau khi nén (2): Thể tích giảm đi 4 lần nên  $V_2=\\frac{V}{4}$<br>Áp dụng định luật Boyle, ta tính được áp suất lúc sau:<br>$p_1V_1=p_2.V_2\\Rightarrow 10^5.V=p_2.\\frac{V}{4}\\Rightarrow p_2=4.10^5Pa$<br>Độ tăng áp suất của khí trong xilanh là:<br>$\\Delta p=p_2−p_1=4.10^5−10^5=3.10^5Pa$<br>Vậy a = 3","difficultySource":"ai"},"ex":[{"exam":454,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"3","question":"Một xilanh một đầu bịt kín chứa khí lí tưởng có áp suất 105 Pa. Ấn pit-tông từ từ để nén khí sao cho nhiệt độ khí trong xilanh không thay đổi. Khi thể tích của khí trong xilanh giảm đi 4 lần thì áp suất của khí tăng thêm 3.10<sup>5</sup> Pa. Giá trị của a là bao nhiêu? (kết quả làm tròn đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"Trạng thái ban đầu (1): Áp suất p1 = 105 Pa , thể tích V1 =V .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trạng thái sau khi nén (2): Thể tích giảm đi 4 lần nên  $V_2=\\frac{V}{4}$<br>Áp dụng định luật Boyle, ta tính được áp suất lúc sau:<br>$p_1V_1=p_2.V_2\\Rightarrow 10^5.V=p_2.\\frac{V}{4}\\Rightarrow p_2=4.10^5Pa$<br>Độ tăng áp suất của khí trong xilanh là:<br>$\\Delta p=p_2−p_1=4.10^5−10^5=3.10^5Pa$<br>Vậy a = 3","difficultySource":"ai"}}]},{"id":673773,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["1,69.1024 J.","6,74.10<sup>24</sup> MeV.","6,74.1024 J.","1,69.10<sup>24</sup> MeV."],"question":"Tổng hợp hạt nhân helium từ phản ứng  ${}_1^2D+{}_3^6{Li}\\rightarrow {}_2^4{He}+X.$  Mỗi phản ứng giải phóng năng lượng 22,4 MeV. Khi tổng hợp được 0,25 mol khí helium  ${}_2^4{He}$  từ phản ứng này thì giải phóng được năng lượng xấp xỉ bằng","difficulty":"trung-binh","explanation":"Phương trình phản ứng tổng hợp helium:  ${}_1^2D+{}_3^6{Li} 2 {}_2^4{He}$<br>Số hạt helium tạo thành:  $N_{He}=n.N_A$<br>Số phản ứng xảy ra:  $N=\\frac{1}{2}.N_{He}=\\frac{1}{2}.n.N_A$<br>Tổng năng lượng giải phóng khi thực hiện N phản ứng:<br>$E=N.\\Delta E=\\frac{1}{2}.n.N_A.\\Delta E=\\frac{1}{2}.0,25.6,02.{10}^{23}.22,4\\approx 1,69.{10}^{24}$  MeV.","difficultySource":"ai"},"ex":[{"exam":455,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":3,"options":["1,69.1024 J.","6,74.10<sup>24</sup> MeV.","6,74.1024 J.","1,69.10<sup>24</sup> MeV."],"question":"Tổng hợp hạt nhân helium từ phản ứng  ${}_1^2D+{}_3^6{Li}\\rightarrow {}_2^4{He}+X.$  Mỗi phản ứng giải phóng năng lượng 22,4 MeV. Khi tổng hợp được 0,25 mol khí helium  ${}_2^4{He}$  từ phản ứng này thì giải phóng được năng lượng xấp xỉ bằng","difficulty":"trung-binh","explanation":"Phương trình phản ứng tổng hợp helium:  ${}_1^2D+{}_3^6{Li} 2 {}_2^4{He}$<br>Số hạt helium tạo thành:  $N_{He}=n.N_A$<br>Số phản ứng xảy ra:  $N=\\frac{1}{2}.N_{He}=\\frac{1}{2}.n.N_A$<br>Tổng năng lượng giải phóng khi thực hiện N phản ứng:<br>$E=N.\\Delta E=\\frac{1}{2}.n.N_A.\\Delta E=\\frac{1}{2}.0,25.6,02.{10}^{23}.22,4\\approx 1,69.{10}^{24}$  MeV.","difficultySource":"ai"}}]},{"id":673777,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Sóng điện từ được ứng dụng rộng rãi trong đời sống và kĩ thuật như thông tin vô tuyến, wifi, chụp X – quang y tế.","difficulty":"trung-binh","statements":[{"text":"Sóng wifi và sóng vô tuyến đều là sóng điện từ và có thể truyền được trong chân không.","answer":true},{"text":"Tia X có cùng bản chất với sóng wifi nhưng có tần số lớn hơn nhiều.","answer":true},{"text":"Khi truyền trong chân không, sóng wifi truyền chậm hơn ánh sáng nhìn thấy do có tần số nhỏ hơn.","answer":false},{"text":"Với E, B lần lượt là giá trị tức thời của cường độ điện trường và cảm ứng từ.  $E_0,$   $B_0$  lần lượt là giá trị cực đại tương ứng. Tại một điểm trên phương truyền sóng, ở một thời điểm bất kì, ta có:  $\\frac{E^2}{{E_0}^2}+\\frac{B^2}{{B_0}^2}=1.$","answer":false}],"explanation":"a) đúng<br>Sóng wifi và sóng vô tuyến đều là sóng điện từ và có thể truyền được trong chân không.<br>b) đúng<br>Tia X và sóng wifi có cùng bản chất là sóng điện từ, khác nhau về tần số và bước sóng. Trong đó, tia X có tần số lớn hơn rất nhiều so với sóng wifi.<br>c) sai<br>Trong chân không, mọi sóng điện từ đều truyền với cùng tốc độ là 3.10<sup>8</sup> m/s. Tốc độ truyền không phụ thuộc vào tần số hay bước sóng.<br>d) sai<br>Tại một điểm xác định trên phương truyền sóng, điện trường và từ trường của sóng điện từ biến thiên điều hòa theo thời gian và cùng pha. Nên ta có:  $\\frac{E}{E_0}=\\frac{B}{B_0}$ .","difficultySource":"ai"},"ex":[{"exam":455,"idx":19,"el":{"form":"ly_thuyet","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Sóng điện từ được ứng dụng rộng rãi trong đời sống và kĩ thuật như thông tin vô tuyến, wifi, chụp X – quang y tế.","difficulty":"trung-binh","statements":[{"text":"Sóng wifi và sóng vô tuyến đều là sóng điện từ và có thể truyền được trong chân không.","answer":true},{"text":"Tia X có cùng bản chất với sóng wifi nhưng có tần số lớn hơn nhiều.","answer":true},{"text":"Khi truyền trong chân không, sóng wifi truyền chậm hơn ánh sáng nhìn thấy do có tần số nhỏ hơn.","answer":false},{"text":"Với E, B lần lượt là giá trị tức thời của cường độ điện trường và cảm ứng từ.  $E_0,$   $B_0$  lần lượt là giá trị cực đại tương ứng. Tại một điểm trên phương truyền sóng, ở một thời điểm bất kì, ta có:  $\\frac{E^2}{{E_0}^2}+\\frac{B^2}{{B_0}^2}=1.$","answer":false}],"explanation":"a) đúng<br>Sóng wifi và sóng vô tuyến đều là sóng điện từ và có thể truyền được trong chân không.<br>b) đúng<br>Tia X và sóng wifi có cùng bản chất là sóng điện từ, khác nhau về tần số và bước sóng. Trong đó, tia X có tần số lớn hơn rất nhiều so với sóng wifi.<br>c) sai<br>Trong chân không, mọi sóng điện từ đều truyền với cùng tốc độ là 3.10<sup>8</sup> m/s. Tốc độ truyền không phụ thuộc vào tần số hay bước sóng.<br>d) sai<br>Tại một điểm xác định trên phương truyền sóng, điện trường và từ trường của sóng điện từ biến thiên điều hòa theo thời gian và cùng pha. Nên ta có:  $\\frac{E}{E_0}=\\frac{B}{B_0}$ .","difficultySource":"ai"}}]},{"id":673778,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Khi đo độ phóng xạ của một mẫu gỗ thuộc một cổ vật, người ta phát hiện được 240 phân rã mỗi phút. Biết trong mẫu gỗ có chứa 25 g carbon gồm hai đồng vị  ${}_6^{14}C$  và  ${}_6^{12}C$ . Chu kì bán rã của  ${}_6^{14}C$  là 5730 năm. Khi sinh vật còn sống, tỉ lệ số nguyên tử  ${}_6^{12}C$  và  ${}_6^{14}C$  là 1012:1. Lấy 1 năm = 365 ngày.","difficulty":"kho","statements":[{"text":"Độ phóng xạ của mẫu gỗ là 240 Bq.","answer":false},{"text":"Mẫu gỗ có tuổi càng lớn thì độ phóng xạ của mẫu đo được càng lớn.","answer":false},{"text":"Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ xấp xỉ bằng 1,04.10<sup>12</sup> nguyên tử.","answer":true},{"text":"Độ tuổi của cổ vật xấp xỉ bằng 1500 năm (làm tròn kết quả đến chữ số hàng trăm).","answer":true}],"explanation":"a) sai<br>Độ phóng xạ của mẫu gỗ là: 240 phân rã/phút = 4 phân rã/giây = 4 Bq.<br>b) sai<br>Mẫu gỗ có tuổi càng lớn thì độ phóng xạ của mẫu đo được càng nhỏ.<br>c) đúng<br>Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ là:<br>$H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.N_{t_{C14}}$    $N_{t_{C14}}=\\frac{T.H_t}{\\ln\\left(2\\right)}=\\frac{5730.365.24.3600.4}{\\ln\\left(2\\right)}\\approx 1,04.{10}^{12}$  nguyên tử.<br>d) đúng<br>Số nguyên tử  ${}_6^{12}C$  có trong 25 g carbon trong mẫu gỗ:<br>$m_{C12}+m_{t_{C14}}=25g$    $\\frac{N_{C12}}{N_A}.12+\\frac{N_{t_{C14}}}{N_A}.14=25$    $N_{C12}=\\frac{25.N_A-14.N_{t_{C14}}}{12}$<br>Thay số ta được:  $N_{C12}=\\frac{25.6,02.{10}^{23}-14.1,04.{10}^{12}}{12}\\approx 1,25.{10}^{24}$  nguyên tử.<br>Số nguyên tử  ${}_6^{14}C$  ban đầu:<br>$\\frac{N_{C12}}{N_{0_{C14}}}=\\frac{{10}^{12}}{1}$    $N_{0_{C14}}=\\frac{N_{C12}}{{10}^{12}}=\\frac{1,25.{10}^{24}}{{10}^{12}}=1,25.{10}^{12}$  nguyên tử.<br>Độ tuổi của cổ vật là:<br>$N_{t_{C14}}=N_{0_{C14}}.2^{-\\frac{t}{T}}$    $t=T.{log}_2\\left(\\frac{N_{0_{C14}}}{N_{t_{C14}}}\\right)=5730.{log}_2\\left(\\frac{1,25.{10}^{12}}{1,04.{10}^{12}}\\right)\\approx 1500$  năm.","difficultySource":"ai"},"ex":[{"exam":455,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Khi đo độ phóng xạ của một mẫu gỗ thuộc một cổ vật, người ta phát hiện được 240 phân rã mỗi phút. Biết trong mẫu gỗ có chứa 25 g carbon gồm hai đồng vị  ${}_6^{14}C$  và  ${}_6^{12}C$ . Chu kì bán rã của  ${}_6^{14}C$  là 5730 năm. Khi sinh vật còn sống, tỉ lệ số nguyên tử  ${}_6^{12}C$  và  ${}_6^{14}C$  là 1012:1. Lấy 1 năm = 365 ngày.","difficulty":"kho","statements":[{"text":"Độ phóng xạ của mẫu gỗ là 240 Bq.","answer":false},{"text":"Mẫu gỗ có tuổi càng lớn thì độ phóng xạ của mẫu đo được càng lớn.","answer":false},{"text":"Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ xấp xỉ bằng 1,04.10<sup>12</sup> nguyên tử.","answer":true},{"text":"Độ tuổi của cổ vật xấp xỉ bằng 1500 năm (làm tròn kết quả đến chữ số hàng trăm).","answer":true}],"explanation":"a) sai<br>Độ phóng xạ của mẫu gỗ là: 240 phân rã/phút = 4 phân rã/giây = 4 Bq.<br>b) sai<br>Mẫu gỗ có tuổi càng lớn thì độ phóng xạ của mẫu đo được càng nhỏ.<br>c) đúng<br>Số nguyên tử  ${}_6^{14}C$  có trong mẫu gỗ là:<br>$H_t=.N_t=\\frac{\\ln\\left(2\\right)}{T}.N_{t_{C14}}$    $N_{t_{C14}}=\\frac{T.H_t}{\\ln\\left(2\\right)}=\\frac{5730.365.24.3600.4}{\\ln\\left(2\\right)}\\approx 1,04.{10}^{12}$  nguyên tử.<br>d) đúng<br>Số nguyên tử  ${}_6^{12}C$  có trong 25 g carbon trong mẫu gỗ:<br>$m_{C12}+m_{t_{C14}}=25g$    $\\frac{N_{C12}}{N_A}.12+\\frac{N_{t_{C14}}}{N_A}.14=25$    $N_{C12}=\\frac{25.N_A-14.N_{t_{C14}}}{12}$<br>Thay số ta được:  $N_{C12}=\\frac{25.6,02.{10}^{23}-14.1,04.{10}^{12}}{12}\\approx 1,25.{10}^{24}$  nguyên tử.<br>Số nguyên tử  ${}_6^{14}C$  ban đầu:<br>$\\frac{N_{C12}}{N_{0_{C14}}}=\\frac{{10}^{12}}{1}$    $N_{0_{C14}}=\\frac{N_{C12}}{{10}^{12}}=\\frac{1,25.{10}^{24}}{{10}^{12}}=1,25.{10}^{12}$  nguyên tử.<br>Độ tuổi của cổ vật là:<br>$N_{t_{C14}}=N_{0_{C14}}.2^{-\\frac{t}{T}}$    $t=T.{log}_2\\left(\\frac{N_{0_{C14}}}{N_{t_{C14}}}\\right)=5730.{log}_2\\left(\\frac{1,25.{10}^{12}}{1,04.{10}^{12}}\\right)\\approx 1500$  năm.","difficultySource":"ai"}}]},{"id":673800,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Người ta dùng một lò hồ quang điện để nấu chảy một khối kim loại nặng 20 kg. Biết lò hồ quang truyền nhiệt cho khối kim loại với công suất không đổi là 5000 W. Sự thay đổi nhiệt độ của khối kim loại được ghi lại theo thời gian như hình bên dưới.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258228-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giai đoạn AB trên đồ thị tương ứng với quá trình nóng chảy của kim loại.","answer":false},{"text":"Trong giai đoạn BC, khối kim loại không nhận thêm nhiệt lượng từ lò nung.","answer":false},{"text":"Nhiệt dung riêng của khối kim loại là 500 J/kg.K.","answer":true},{"text":"Nhiệt nóng chảy riêng của khối kim loại là 3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Giai đoạn AB trên đồ thị tương ứng với giai đoạn mà khối kim loại đang tăng nhiệt độ từ  $30℃$  đến  $1530℃$ .<br>b) sai<br>Trong giai đoạn BC, khối kim loại đang trong quá trình chuyển thể, do đó nhiệt độ của khối kim loại không tăng. Tuy nhiên khối kim loại vẫn đang nhận nhiệt từ lò để phục vụ cho quá trình này.<br>c) đúng<br>Xét giai đoạn AB, nhiệt lượng cần cung cấp để khối kim loại tăng nhiệt độ từ  $30℃$  đến  $1530℃$ :<br>$m.c.\\Delta t=Q_{AB}$<br>$⟺20∙c∙\\left(1530-30\\right)=5000∙\\left(50∙60\\right)$<br>$⟹c=500 J/kg.K$<br>d) đúng<br>Xét giai đoạn BC, nhiệt lượng cần thiết để khối kim loại đó nóng chảy hoàn toàn ở nhiệt độ nóng chảy:<br>$m.\\lambda =Q_{BC}$<br>$⟺20∙\\lambda =5000∙\\left(20∙60\\right)$<br>$⟹\\lambda ={3.10}^5 J/kg.$","difficultySource":"ai"},"ex":[{"exam":456,"idx":15,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Người ta dùng một lò hồ quang điện để nấu chảy một khối kim loại nặng 20 kg. Biết lò hồ quang truyền nhiệt cho khối kim loại với công suất không đổi là 5000 W. Sự thay đổi nhiệt độ của khối kim loại được ghi lại theo thời gian như hình bên dưới.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258228-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Giai đoạn AB trên đồ thị tương ứng với quá trình nóng chảy của kim loại.","answer":false},{"text":"Trong giai đoạn BC, khối kim loại không nhận thêm nhiệt lượng từ lò nung.","answer":false},{"text":"Nhiệt dung riêng của khối kim loại là 500 J/kg.K.","answer":true},{"text":"Nhiệt nóng chảy riêng của khối kim loại là 3.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Giai đoạn AB trên đồ thị tương ứng với giai đoạn mà khối kim loại đang tăng nhiệt độ từ  $30℃$  đến  $1530℃$ .<br>b) sai<br>Trong giai đoạn BC, khối kim loại đang trong quá trình chuyển thể, do đó nhiệt độ của khối kim loại không tăng. Tuy nhiên khối kim loại vẫn đang nhận nhiệt từ lò để phục vụ cho quá trình này.<br>c) đúng<br>Xét giai đoạn AB, nhiệt lượng cần cung cấp để khối kim loại tăng nhiệt độ từ  $30℃$  đến  $1530℃$ :<br>$m.c.\\Delta t=Q_{AB}$<br>$⟺20∙c∙\\left(1530-30\\right)=5000∙\\left(50∙60\\right)$<br>$⟹c=500 J/kg.K$<br>d) đúng<br>Xét giai đoạn BC, nhiệt lượng cần thiết để khối kim loại đó nóng chảy hoàn toàn ở nhiệt độ nóng chảy:<br>$m.\\lambda =Q_{BC}$<br>$⟺20∙\\lambda =5000∙\\left(20∙60\\right)$<br>$⟹\\lambda ={3.10}^5 J/kg.$","difficultySource":"ai"}}]},{"id":673801,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng xác định thực hiện quá trình biến đổi trạng thái từ (1)  (2)  (3)  (4)  (5). Đồ thị biểu diễn quá trình (1)  (2) là một đường hyperbol. Nhiệt độ của khối khí ở trạng thái (1) là  $30℃$ .<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258451-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số mol của khối khí đang xét xấp xỉ bằng 0,15 mol (làm tròn kết quả đến chữ số hàng phần trăm).","answer":false},{"text":"Thể tích của khối khí ở trạng thái (2) bằng 4,5.10<sup>−3</sup> m3.","answer":true},{"text":"Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của các phân tử khí giảm 3 lần.","answer":false},{"text":"Nhiệt độ của khối khí ở trạng thái (5) là 454,5 K.","answer":true}],"explanation":"a) sai<br>Áp dụng phương trình Clapeyron cho trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟺{3.10}^5∙{1,5.10}^{-3}=n∙8,31∙\\left(30+273\\right)$<br>$⟹n=\\frac{{3.10}^5∙{1,5.10}^{-3}}{8,31∙\\left(30+273\\right)}\\approx 0,18 mol.$<br>b) đúng<br>Áp dụng định luật Boyle cho quá trình từ (1) sang (2):<br>$p_1.V_1=p_2.V_2$<br>$⟹V_2=\\frac{p_1.V_1}{p_2}=\\frac{{3.10}^5∙{1,5.10}^{-3}}{{10}^5}={4,5.10}^{-3} m^3.$<br>c) sai<br>Ta có mối liên hệ giữa động năng tịnh tiến trung bình và áp suất của khí:<br>$p=\\frac{2}{3}.\\mu .\\overline{E_đ}$<br>Từ trạng thái (2) sang trạng thái (3), áp suất tăng 3 lần và thể tích không đổi nên động năng tịnh tiến trung bình cũng tăng 3 lần.<br>d) đúng<br>Áp dụng phương trình trạng thái khí lí tưởng cho khối khí ở trạng thái (1) và (5):<br>$\\frac{p_1.V_1}{T_1}=\\frac{p_5.V_5}{T_5}$<br>$⟺\\frac{{3.10}^5∙1,5}{\\left(30+273\\right)}=\\frac{{10}^5∙\\left(1,5∙4,5\\right)}{T_5}$<br>$⟹T_5=454,5 K.$","difficultySource":"ai"},"ex":[{"exam":456,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng xác định thực hiện quá trình biến đổi trạng thái từ (1)  (2)  (3)  (4)  (5). Đồ thị biểu diễn quá trình (1)  (2) là một đường hyperbol. Nhiệt độ của khối khí ở trạng thái (1) là  $30℃$ .<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258451-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số mol của khối khí đang xét xấp xỉ bằng 0,15 mol (làm tròn kết quả đến chữ số hàng phần trăm).","answer":false},{"text":"Thể tích của khối khí ở trạng thái (2) bằng 4,5.10<sup>−3</sup> m3.","answer":true},{"text":"Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của các phân tử khí giảm 3 lần.","answer":false},{"text":"Nhiệt độ của khối khí ở trạng thái (5) là 454,5 K.","answer":true}],"explanation":"a) sai<br>Áp dụng phương trình Clapeyron cho trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟺{3.10}^5∙{1,5.10}^{-3}=n∙8,31∙\\left(30+273\\right)$<br>$⟹n=\\frac{{3.10}^5∙{1,5.10}^{-3}}{8,31∙\\left(30+273\\right)}\\approx 0,18 mol.$<br>b) đúng<br>Áp dụng định luật Boyle cho quá trình từ (1) sang (2):<br>$p_1.V_1=p_2.V_2$<br>$⟹V_2=\\frac{p_1.V_1}{p_2}=\\frac{{3.10}^5∙{1,5.10}^{-3}}{{10}^5}={4,5.10}^{-3} m^3.$<br>c) sai<br>Ta có mối liên hệ giữa động năng tịnh tiến trung bình và áp suất của khí:<br>$p=\\frac{2}{3}.\\mu .\\overline{E_đ}$<br>Từ trạng thái (2) sang trạng thái (3), áp suất tăng 3 lần và thể tích không đổi nên động năng tịnh tiến trung bình cũng tăng 3 lần.<br>d) đúng<br>Áp dụng phương trình trạng thái khí lí tưởng cho khối khí ở trạng thái (1) và (5):<br>$\\frac{p_1.V_1}{T_1}=\\frac{p_5.V_5}{T_5}$<br>$⟺\\frac{{3.10}^5∙1,5}{\\left(30+273\\right)}=\\frac{{10}^5∙\\left(1,5∙4,5\\right)}{T_5}$<br>$⟹T_5=454,5 K.$","difficultySource":"ai"}}]},{"id":673802,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","question":"Một thanh kim loại nhẹ có thể quay tự do quanh trục Q, trong khi đầu bên dưới của nó chỉ chạm vào một chất lỏng dẫn điện trong bình kim loại. Một từ trường đều được áp dụng trên vùng ABCD và chứa một phần của thanh như hình vẽ. Khi công tắc K đóng, thanh bị văng ra khỏi bề mặt chất lỏng. Moment lực từ ban đầu khiến thanh văng ra là 1,4.10<sup>−3</sup> Nm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258613-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thanh bị văng về phía sau của mặt phẳng trang giấy.","answer":false},{"text":"Sau khi thanh bị văng ra khỏi chất lỏng thì mạch hở, lực từ tác dụng lên thanh bị mất, thanh sẽ trở lại vị trí ban đầu. Sau đó quá trình này lặp lại làm thanh tiếp tục bị văng.","answer":true},{"text":"Lực từ tác dụng lên thanh có độ lớn 2 mN.","answer":false},{"text":"Nếu dòng điện chạy qua mạch có cường độ 2,6 A thì độ lớn cảm ứng từ của vùng ABCD xấp xỉ 0,06 T.","answer":false}],"explanation":"a) sai<br>Dựa vào chiều của nguồn điện, ta có thể xác định dòng điện có chiều từ đầu trên của thanh xuống phía dưới. Áp dụng quy tắc bàn tay trái, ta có thể xác định được lực từ có chiều hướng sang phải. Vì vậy, dưới tác dụng của từ trường, thanh bị văng sang phải<br>b) đúng<br>Sau khi thanh bị văng ra khỏi chất lỏng thì mạch hở, lực từ tác dụng lên thanh bị mất, thanh sẽ trở lại vị trí ban đầu. Sau đó quá trình này lặp lại làm thanh tiếp tục bị văng.<br>c) sai<br>Khoảng cách từ trục quay đến giá của lực từ:<br>$d=4+\\frac{6}{2}=7 cm=0,07 m$<br>Lực từ tác dụng lên thanh có độ lớn:<br>$F_t.d=M_{F_t}⟹F_t=\\frac{M_{F_t}}{d}=\\frac{{1,4.10}^{-3}}{0,07}=0,02 N=20 mN$<br>d) sai<br>Độ lớn cảm ứng từ của vùng ABCD:<br>$B.I.l.\\sin\\left(\\alpha \\right)=F_t$<br>$⟹B=\\frac{F_t}{I.l.\\sin\\left(\\alpha \\right)}=\\frac{0,02}{2,6∙0,06∙\\sin\\left(90^{\\circ}\\right)}\\approx 0,13 T.$","difficultySource":"ai"},"ex":[{"exam":456,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","question":"Một thanh kim loại nhẹ có thể quay tự do quanh trục Q, trong khi đầu bên dưới của nó chỉ chạm vào một chất lỏng dẫn điện trong bình kim loại. Một từ trường đều được áp dụng trên vùng ABCD và chứa một phần của thanh như hình vẽ. Khi công tắc K đóng, thanh bị văng ra khỏi bề mặt chất lỏng. Moment lực từ ban đầu khiến thanh văng ra là 1,4.10<sup>−3</sup> Nm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047258613-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thanh bị văng về phía sau của mặt phẳng trang giấy.","answer":false},{"text":"Sau khi thanh bị văng ra khỏi chất lỏng thì mạch hở, lực từ tác dụng lên thanh bị mất, thanh sẽ trở lại vị trí ban đầu. Sau đó quá trình này lặp lại làm thanh tiếp tục bị văng.","answer":true},{"text":"Lực từ tác dụng lên thanh có độ lớn 2 mN.","answer":false},{"text":"Nếu dòng điện chạy qua mạch có cường độ 2,6 A thì độ lớn cảm ứng từ của vùng ABCD xấp xỉ 0,06 T.","answer":false}],"explanation":"a) sai<br>Dựa vào chiều của nguồn điện, ta có thể xác định dòng điện có chiều từ đầu trên của thanh xuống phía dưới. Áp dụng quy tắc bàn tay trái, ta có thể xác định được lực từ có chiều hướng sang phải. Vì vậy, dưới tác dụng của từ trường, thanh bị văng sang phải<br>b) đúng<br>Sau khi thanh bị văng ra khỏi chất lỏng thì mạch hở, lực từ tác dụng lên thanh bị mất, thanh sẽ trở lại vị trí ban đầu. Sau đó quá trình này lặp lại làm thanh tiếp tục bị văng.<br>c) sai<br>Khoảng cách từ trục quay đến giá của lực từ:<br>$d=4+\\frac{6}{2}=7 cm=0,07 m$<br>Lực từ tác dụng lên thanh có độ lớn:<br>$F_t.d=M_{F_t}⟹F_t=\\frac{M_{F_t}}{d}=\\frac{{1,4.10}^{-3}}{0,07}=0,02 N=20 mN$<br>d) sai<br>Độ lớn cảm ứng từ của vùng ABCD:<br>$B.I.l.\\sin\\left(\\alpha \\right)=F_t$<br>$⟹B=\\frac{F_t}{I.l.\\sin\\left(\\alpha \\right)}=\\frac{0,02}{2,6∙0,06∙\\sin\\left(90^{\\circ}\\right)}\\approx 0,13 T.$","difficultySource":"ai"}}]},{"id":673803,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Đồng vị Sắt  ${}_{26}^{59}{Fe}$  là chất phóng xạ  $\\beta^-$  với chu kì bán rã 44,5 ngày và thường được sử dụng trong y học. Để có được một nhận định y khoa chính xác về tình trạng thiếu sắt trong cơ thể bệnh nhân, người ta cho bệnh nhân uống một loại đồ uống chứa 0,25.10<sup>−12</sup> kg đồng vị  ${}_{26}^{59}{Fe}$ . Khi bệnh nhân bị thiếu sắt ở mức độ nghiêm trọng, cơ thể sẽ hấp thụ hoàn toàn đồng vị sắt này. Sau 15 ngày, độ phóng xạ của  ${}_{26}^{59}{Fe}$  trong cơ thể được đo lại. Lấy khối lượng mol của  ${}_{26}^{59}{Fe}$  xấp xỉ 58,93 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{26}^{59}{Fe}$  sau khi phóng xạ  $\\beta^-$  thì biến thành hạt nhân  ${}_{27}^{59}{Co}.$","answer":true},{"text":"Trong đồ uống của bệnh nhân có chứa khoảng 2,55.10<sup>12</sup> hạt nhân  ${}_{26}^{59}{Fe}.$","answer":true},{"text":"Lượng  ${}_{26}^{59}{Fe}$  trong đồ uống của bệnh nhân có độ phóng xạ khoảng  0,46 MBq.","answer":true},{"text":"Sau 15 ngày được đưa vào cơ thể bệnh nhân, lượng  ${}_{26}^{59}{Fe}$  bị đào thải ra khỏi cơ thể là 10% một phần đã bị phân rã, phần còn lại có độ phóng xạ là 0,39 MBq.","answer":false}],"explanation":"a) đúng<br>Quá trình phản ứng hạt nhân trong trường hợp này:<br>${}_{26}^{59}{Fe}⟶{}_Z^AX+\\beta^-$<br>Áp dụng định luật bảo toàn số khối và định luật bảo toàn điện tích:<br>$\\left\\{\\begin{aligned}A+0=59 <br>Z+\\left(-1\\right)=26\\end{aligned}⟹\\left\\{\\begin{aligned}A=59 <br>Z=27\\end{aligned}\\right.\\right.$<br>b) đúng<br>Số hạt nhân  ${}_{26}^{59}{Fe}$  có trong mẫu chất ban đầu:<br>$N_0=\\frac{m}{M}.N_A=\\frac{{0,25.10}^{-9}}{58,93}.{6,02.10}^{23}\\approx {2,55.10}^{12} hạt.$<br>c) đúng<br>Độ phóng xạ tại thời điểm ban đầu của mẫu chất:<br>$H_0=\\lambda .N_0=\\frac{\\ln\\left(2\\right)}{\\left(44,5∙86400\\right)} ∙\\frac{{0,25.10}^{-9}}{58,93}.{6,02.10}^{23}\\approx {0,46.10}^6 Bq=0,46 MBq.$<br>d) sai<br>Do đã bị đào thải ra bên ngoài 10% và một phần đã bị phân rã nên độ phóng xạ của phần còn lại:<br>$H=0,9.H_0.2^{-\\frac{t}{T}}=0,9∙0,46∙2^{-\\frac{15}{44,5}}\\approx 0,33 MBq.$","difficultySource":"ai"},"ex":[{"exam":456,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Đồng vị Sắt  ${}_{26}^{59}{Fe}$  là chất phóng xạ  $\\beta^-$  với chu kì bán rã 44,5 ngày và thường được sử dụng trong y học. Để có được một nhận định y khoa chính xác về tình trạng thiếu sắt trong cơ thể bệnh nhân, người ta cho bệnh nhân uống một loại đồ uống chứa 0,25.10<sup>−12</sup> kg đồng vị  ${}_{26}^{59}{Fe}$ . Khi bệnh nhân bị thiếu sắt ở mức độ nghiêm trọng, cơ thể sẽ hấp thụ hoàn toàn đồng vị sắt này. Sau 15 ngày, độ phóng xạ của  ${}_{26}^{59}{Fe}$  trong cơ thể được đo lại. Lấy khối lượng mol của  ${}_{26}^{59}{Fe}$  xấp xỉ 58,93 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{26}^{59}{Fe}$  sau khi phóng xạ  $\\beta^-$  thì biến thành hạt nhân  ${}_{27}^{59}{Co}.$","answer":true},{"text":"Trong đồ uống của bệnh nhân có chứa khoảng 2,55.10<sup>12</sup> hạt nhân  ${}_{26}^{59}{Fe}.$","answer":true},{"text":"Lượng  ${}_{26}^{59}{Fe}$  trong đồ uống của bệnh nhân có độ phóng xạ khoảng  0,46 MBq.","answer":true},{"text":"Sau 15 ngày được đưa vào cơ thể bệnh nhân, lượng  ${}_{26}^{59}{Fe}$  bị đào thải ra khỏi cơ thể là 10% một phần đã bị phân rã, phần còn lại có độ phóng xạ là 0,39 MBq.","answer":false}],"explanation":"a) đúng<br>Quá trình phản ứng hạt nhân trong trường hợp này:<br>${}_{26}^{59}{Fe}⟶{}_Z^AX+\\beta^-$<br>Áp dụng định luật bảo toàn số khối và định luật bảo toàn điện tích:<br>$\\left\\{\\begin{aligned}A+0=59 <br>Z+\\left(-1\\right)=26\\end{aligned}⟹\\left\\{\\begin{aligned}A=59 <br>Z=27\\end{aligned}\\right.\\right.$<br>b) đúng<br>Số hạt nhân  ${}_{26}^{59}{Fe}$  có trong mẫu chất ban đầu:<br>$N_0=\\frac{m}{M}.N_A=\\frac{{0,25.10}^{-9}}{58,93}.{6,02.10}^{23}\\approx {2,55.10}^{12} hạt.$<br>c) đúng<br>Độ phóng xạ tại thời điểm ban đầu của mẫu chất:<br>$H_0=\\lambda .N_0=\\frac{\\ln\\left(2\\right)}{\\left(44,5∙86400\\right)} ∙\\frac{{0,25.10}^{-9}}{58,93}.{6,02.10}^{23}\\approx {0,46.10}^6 Bq=0,46 MBq.$<br>d) sai<br>Do đã bị đào thải ra bên ngoài 10% và một phần đã bị phân rã nên độ phóng xạ của phần còn lại:<br>$H=0,9.H_0.2^{-\\frac{t}{T}}=0,9∙0,46∙2^{-\\frac{15}{44,5}}\\approx 0,33 MBq.$","difficultySource":"ai"}}]},{"id":673830,"nq":{"form":"bai_tap","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Năng lượng của Mặt Trời và các ngôi sao trong vũ trụ đều có nguồn gốc từ các phản ứng đốt cháy hydrogen để tạo thành helium (gọi là chu trình proton – proton). Xét một ngôi sao đã đốt cháy hoàn toàn hydrogen thành helium và coi các hạt nhân helium tạo thành đều tham gia vào quá trình ba – alpha theo phương trình ${}_2^4He+{}_2^4He\\rightarrow {}_6^{12}C+7,275MeV$ . Ở thời điểm ban đầu, khối lượng của ngôi sao là 4,0.10<sup>30</sup> kg (Khi tất cả hạt trong ngôi sao đều là Helium) và công suất tỏa nhiệt của ngôi sao là 3,8.10<sup>30</sup> W.","difficulty":"kho","statements":[{"text":"Phản ứng đốt cháy hydrogen để tạo thành helium bên trong Mặt Trời là phản ứng phân hạch.","answer":false},{"text":"Số hạt nhân  ${}_2^4He$  tại thời điểm ban đầu là 6,02.10<sup>56</sup>.","answer":true},{"text":"Số hạt nhân  ${}_6^{12}C$  tạo thành sau 1 năm là 1,03.10<sup>50</sup>.","answer":true},{"text":"Thời gian để toàn bộ hạt nhân  ${}_2^4He$  chuyển hóa hoàn toàn thành  ${}_6^{12}C$  là khoảng 1,95 triệu năm.","answer":true}],"explanation":"a) sai<br>1 phân tử toả 7,275 MeV<br>Phản ứng đốt cháy hydrogen để tạo thành helium bên trong Mặt Trời là phản ứng nhiệt hạch.<br>b) đúng<br>Số hạt He ở thời điểm ban đầu:  $\\frac{4.10^{30}.10^3}{4}.6,02.10^{23}=6,02.10^{56}$  (hạt)<br>Xét 1 năm là 365 ngày:  $Q=P.t=3,8.10^{30}.365.24.60.60=1,198.10^{38}\\left(J\\right)$<br>c) đúng<br>1 phản ứng cần 3 hạt He  $\\Rightarrow \\frac{So hat He}{3}=So phan ung$<br>Số phản ứng = Số hạt C:  $\\frac{Q_{toa}}{7,275.1.6.10^{−13}}=1,03.10^{50}$  (phản ứng)<br>d) đúng<br>Số phản ứng:  $=\\frac{Q∑}{P}=t\\Rightarrow \\left[\\frac{6,02.10^{56}}{3}.7,275.1,6.10^{−13}Q toa cua1 phan ung\\right]:\\left(3,8.10^{30}\\right)=6,146.10^{13}\\left(s\\right)$<br>$\\frac{6,146.10^{13}}{365.24.60.60}=1,95.10^6$  (năm)","difficultySource":"ai"},"ex":[{"exam":457,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Năng lượng của Mặt Trời và các ngôi sao trong vũ trụ đều có nguồn gốc từ các phản ứng đốt cháy hydrogen để tạo thành helium (gọi là chu trình proton – proton). Xét một ngôi sao đã đốt cháy hoàn toàn hydrogen thành helium và coi các hạt nhân helium tạo thành đều tham gia vào quá trình ba – alpha theo phương trình ${}_2^4He+{}_2^4He\\rightarrow {}_6^{12}C+7,275MeV$ . Ở thời điểm ban đầu, khối lượng của ngôi sao là 4,0.10<sup>30</sup> kg (Khi tất cả hạt trong ngôi sao đều là Helium) và công suất tỏa nhiệt của ngôi sao là 3,8.10<sup>30</sup> W.","difficulty":"kho","statements":[{"text":"Phản ứng đốt cháy hydrogen để tạo thành helium bên trong Mặt Trời là phản ứng phân hạch.","answer":false},{"text":"Số hạt nhân  ${}_2^4He$  tại thời điểm ban đầu là 6,02.10<sup>56</sup>.","answer":true},{"text":"Số hạt nhân  ${}_6^{12}C$  tạo thành sau 1 năm là 1,03.10<sup>50</sup>.","answer":true},{"text":"Thời gian để toàn bộ hạt nhân  ${}_2^4He$  chuyển hóa hoàn toàn thành  ${}_6^{12}C$  là khoảng 1,95 triệu năm.","answer":true}],"explanation":"a) sai<br>1 phân tử toả 7,275 MeV<br>Phản ứng đốt cháy hydrogen để tạo thành helium bên trong Mặt Trời là phản ứng nhiệt hạch.<br>b) đúng<br>Số hạt He ở thời điểm ban đầu:  $\\frac{4.10^{30}.10^3}{4}.6,02.10^{23}=6,02.10^{56}$  (hạt)<br>Xét 1 năm là 365 ngày:  $Q=P.t=3,8.10^{30}.365.24.60.60=1,198.10^{38}\\left(J\\right)$<br>c) đúng<br>1 phản ứng cần 3 hạt He  $\\Rightarrow \\frac{So hat He}{3}=So phan ung$<br>Số phản ứng = Số hạt C:  $\\frac{Q_{toa}}{7,275.1.6.10^{−13}}=1,03.10^{50}$  (phản ứng)<br>d) đúng<br>Số phản ứng:  $=\\frac{Q∑}{P}=t\\Rightarrow \\left[\\frac{6,02.10^{56}}{3}.7,275.1,6.10^{−13}Q toa cua1 phan ung\\right]:\\left(3,8.10^{30}\\right)=6,146.10^{13}\\left(s\\right)$<br>$\\frac{6,146.10^{13}}{365.24.60.60}=1,95.10^6$  (năm)","difficultySource":"ai"}}]},{"id":673937,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Hình dưới là thí nghiệm về nhiệt kế khí. Nhiệt kế có bình chứa khí được nhúng vào môi trường cần đo nhiệt độ. Thể tích của khí trong bình được giữ cố định bằng cách nâng hoặc hạ mực nước ở bình B để giữ cho mức nước ở bình A không thay đổi. Ban đầu nhiệt độ T0 = 300 K thì mực nước 2 cột A và B ngang nhau và ở vạch số 0. Sau đó đưa khối khí vào dung dịch cần đo nhiệt độ và đồng thời thực hiện đổ thêm nước vào bình B để mực nước bình A luôn ở vạch số 0. Lúc này đo được độ chênh lệch độ cao nước 2 bình là h = 50 cm. Cho biết khối lượng riêng của nước D = 1000 kg/m3.<br>áp suất khí quyển P0 = 105 Pa, lấy gia tốc trọng trường g = 10 $m/s^2$. Bỏ qua sự trao đổi nhiệt của đường nối bình chứa khí với bình A.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293284-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quá trình biến đổi trạng thái của lượng khí nối với bình A là đẳng tích.","answer":true},{"text":"Ban đầu áp suất lượng khí nối với bình A bằng 105 Pa.","answer":true},{"text":"Áp suất sau của lượng khí nối với bình A bằng 1,5.10<sup>5</sup> Pa.","answer":false},{"text":"Nhiệt độ dung dịch cần đo bằng 450 K.","answer":false}],"explanation":"a) đúng<br>Đề bài nêu rõ \"thể tích của khí trong bình được giữ cố định\" bằng cách điều chỉnh mực nước ở bình B sao cho \"mực nước bình A luôn ở vạch số 0 \".  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Điều này có nghĩa là thể tích khí không đổi trong suốt quá trình thực hiện thí nghiệm. Do đó, đây là quá trình biến đổi đẳng tích<br>b) đúng<br>Ở trạng thái ban đầu (trạng thái 1), mực nước ở hai nhánh A và B ngang nhau (cùng ở vạch số 0).<br>Khi đó, áp suất của khối lượng khí trong bình cân bằng với áp suất khí quyển tác dụng lên nhánh B.<br>Suy ra:  $p_1=p_0=10^5Pa$<br>c) sai<br>Ở trạng thái sau (trạng thái 2), mực nước ở nhánh B cao hơn nhánh A một đoạn h = 50 cm = 0,5 m.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp suất của khối khí lúc này bằng áp suất khí quyển cộng với áp suất do trọng lượng của cột nước chênh lệch gây ra:  $p_2=p_0+D.g.h=10^5+1000.10.0,5=1,05.10^5Pa$<br>d) sai<br>Vì khối khí trải qua quá trình đẳng tích, ta áp dụng định luật Sác-lơ giữa trạng thái 1 và trạng thái 2:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293498-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":461,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Hình dưới là thí nghiệm về nhiệt kế khí. Nhiệt kế có bình chứa khí được nhúng vào môi trường cần đo nhiệt độ. Thể tích của khí trong bình được giữ cố định bằng cách nâng hoặc hạ mực nước ở bình B để giữ cho mức nước ở bình A không thay đổi. Ban đầu nhiệt độ T0 = 300 K thì mực nước 2 cột A và B ngang nhau và ở vạch số 0. Sau đó đưa khối khí vào dung dịch cần đo nhiệt độ và đồng thời thực hiện đổ thêm nước vào bình B để mực nước bình A luôn ở vạch số 0. Lúc này đo được độ chênh lệch độ cao nước 2 bình là h = 50 cm. Cho biết khối lượng riêng của nước D = 1000 kg/m3.<br>áp suất khí quyển P0 = 105 Pa, lấy gia tốc trọng trường g = 10 m/s2. Bỏ qua sự trao đổi nhiệt của đường nối bình chứa khí với bình A.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293284-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quá trình biến đổi trạng thái của lượng khí nối với bình A là đẳng tích.","answer":true},{"text":"Ban đầu áp suất lượng khí nối với bình A bằng 105 Pa.","answer":true},{"text":"Áp suất sau của lượng khí nối với bình A bằng 1,5.10<sup>5</sup> Pa.","answer":false},{"text":"Nhiệt độ dung dịch cần đo bằng 450 K.","answer":false}],"explanation":"a) đúng<br>Đề bài nêu rõ \"thể tích của khí trong bình được giữ cố định\" bằng cách điều chỉnh mực nước ở bình B sao cho \"mực nước bình A luôn ở vạch số 0 \".  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Điều này có nghĩa là thể tích khí không đổi trong suốt quá trình thực hiện thí nghiệm. Do đó, đây là quá trình biến đổi đẳng tích<br>b) đúng<br>Ở trạng thái ban đầu (trạng thái 1), mực nước ở hai nhánh A và B ngang nhau (cùng ở vạch số 0).<br>Khi đó, áp suất của khối lượng khí trong bình cân bằng với áp suất khí quyển tác dụng lên nhánh B.<br>Suy ra:  $p_1=p_0=10^5Pa$<br>c) sai<br>Ở trạng thái sau (trạng thái 2), mực nước ở nhánh B cao hơn nhánh A một đoạn h = 50 cm = 0,5 m.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp suất của khối khí lúc này bằng áp suất khí quyển cộng với áp suất do trọng lượng của cột nước chênh lệch gây ra:  $p_2=p_0+D.g.h=10^5+1000.10.0,5=1,05.10^5Pa$<br>d) sai<br>Vì khối khí trải qua quá trình đẳng tích, ta áp dụng định luật Sác-lơ giữa trạng thái 1 và trạng thái 2:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293498-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":673939,"nq":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Hạt nhân  ${}_{92}^{235}U$  hấp thụ một neutron nhiệt rồi vỡ ra thành hai hạt nhân  ${}_{56}^{141}{Ba}$ và  ${}_{36}^{93}{Kr}$  kèm theo giải phóng một số hạt neutron mới. Biết rằng tổng khối lượng các hạt trước phản ứng lớn hơn tổng khối lượng các hạt sau phản ứng là 0,2147 amu. Biết l amu = 931,5 Mev/c2.","difficulty":"kho","statements":[{"text":"Quá trình này giải phóng kèm theo 3 hạt neutron mới.","answer":false},{"text":"Phản ứng phân hạch là nguồn gốc năng lượng của các ngôi sao.","answer":false},{"text":"Năng lượng tỏa ra sau phản ứng (làm tròn đến phần nguyên) là 200 MeV.","answer":true},{"text":"Phản ứng trên được sử dụng trong một nhà máy điện hạt nhân có công suất phát điện 1000 MW, hiệu suất chuyển đổi năng lượng hạt nhân thành điện năng bằng 30% thì trong một năm (365 ngày), khối lượng ${}_{}^{235}U$ tiêu thụ vào khoảng 1250 kg. (Cho biết khối lượng mol của  ${}_{}^{235}U$ là 235 g/mol)","answer":false}],"explanation":"a) sai<br>Phương trình phản ứng:  ${}_0^1n+_{92}^{235}U\\rightarrow_{56}^{141}Ba+_{36}^{93}Kr+k._0^1n$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp dụng định luật bảo toàn số khối: $1+235=141+93+k.1\\Rightarrow 236=234+k\\Rightarrow k=2$  .<br>Vậy phản ứng sinh ra 2 hạt neutron mới, không phải 3<br>b) sai<br>Nguồn gốc năng lượng của các ngôi sao là do các phản ứng nhiệt hạch (tổng hợp các hạt nhân nhẹ thành hạt nhân nặng hơn), không phải phản ứng phân hạch<br>c) đúng<br>Năng lượng tỏa ra của một phản ứng phân hạch là:<br>ΔE = Δm.c2 = 0,2147.931,5  $\\approx$  199,99MeV  $\\approx$  200MeV<br>d) sai<br>Điện năng nhà máy phát ra trong 1 năm (365 ngày) là:<br>A = P.t =1000.106.(365.24.3600) = 3,1536.10<sup>16</sup> J<br>Năng lượng nhiệt từ phản ứng phân hạch cần cung cấp (năng lượng toàn phần) là:<br>$W=\\frac{A}{H}=\\frac{3,1536.10^{16}}{0,3}=1,0512.10^{17}J$<br>Năng lượng tỏa ra của 1 phân hạch: ΔE = 200MeV = 200.106.1,6.10<sup>−19</sup> J = 3,2.10<sup>−11</sup> J .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số hạt nhân  ${}_{}^{235}U$ cần dùng (chính là số phân hạch):<br>$N=\\frac{W}{\\Delta E}=\\frac{1,0512.10^{17}}{3,2.10^{−11}}=3,285.10^{27}$  hạt<br>Khối lượng  ${}_{}^{235}U$ tiêu thụ là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293961-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":461,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Năng lượng toả ra của phản ứng hạt nhân","question":"Hạt nhân  ${}_{92}^{235}U$  hấp thụ một neutron nhiệt rồi vỡ ra thành hai hạt nhân  ${}_{56}^{141}{Ba}$ và  ${}_{36}^{93}{Kr}$  kèm theo giải phóng một số hạt neutron mới. Biết rằng tổng khối lượng các hạt trước phản ứng lớn hơn tổng khối lượng các hạt sau phản ứng là 0,2147 amu. Biết l amu = 931,5 Mev/c2.","difficulty":"kho","statements":[{"text":"Quá trình này giải phóng kèm theo 3 hạt neutron mới.","answer":false},{"text":"Phản ứng phân hạch là nguồn gốc năng lượng của các ngôi sao.","answer":false},{"text":"Năng lượng tỏa ra sau phản ứng (làm tròn đến phần nguyên) là 200 MeV.","answer":true},{"text":"Phản ứng trên được sử dụng trong một nhà máy điện hạt nhân có công suất phát điện 1000 MW, hiệu suất chuyển đổi năng lượng hạt nhân thành điện năng bằng 30% thì trong một năm (365 ngày), khối lượng ${}_{}^{235}U$ tiêu thụ vào khoảng 1250 kg. (Cho biết khối lượng mol của  ${}_{}^{235}U$ là 235 g/mol)","answer":false}],"explanation":"a) sai<br>Phương trình phản ứng:  ${}_0^1n+_{92}^{235}U\\rightarrow_{56}^{141}Ba+_{36}^{93}Kr+k._0^1n$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp dụng định luật bảo toàn số khối: $1+235=141+93+k.1\\Rightarrow 236=234+k\\Rightarrow k=2$  .<br>Vậy phản ứng sinh ra 2 hạt neutron mới, không phải 3<br>b) sai<br>Nguồn gốc năng lượng của các ngôi sao là do các phản ứng nhiệt hạch (tổng hợp các hạt nhân nhẹ thành hạt nhân nặng hơn), không phải phản ứng phân hạch<br>c) đúng<br>Năng lượng tỏa ra của một phản ứng phân hạch là:<br>ΔE = Δm.c2 = 0,2147.931,5  $\\approx$  199,99MeV  $\\approx$  200MeV<br>d) sai<br>Điện năng nhà máy phát ra trong 1 năm (365 ngày) là:<br>A = P.t =1000.106.(365.24.3600) = 3,1536.10<sup>16</sup> J<br>Năng lượng nhiệt từ phản ứng phân hạch cần cung cấp (năng lượng toàn phần) là:<br>$W=\\frac{A}{H}=\\frac{3,1536.10^{16}}{0,3}=1,0512.10^{17}J$<br>Năng lượng tỏa ra của 1 phân hạch: ΔE = 200MeV = 200.106.1,6.10<sup>−19</sup> J = 3,2.10<sup>−11</sup> J .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số hạt nhân  ${}_{}^{235}U$ cần dùng (chính là số phân hạch):<br>$N=\\frac{W}{\\Delta E}=\\frac{1,0512.10^{17}}{3,2.10^{−11}}=3,285.10^{27}$  hạt<br>Khối lượng  ${}_{}^{235}U$ tiêu thụ là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047293961-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":673940,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Quạt điều hòa là thiết bị làm mát hoạt động dựa trên nguyên lý bay hơi nước, kết hợp với cơ chế lưu thông không khí. Khi không khí nóng đi qua các tấm làm mát được giữ ẩm, nước trên tấm này bay hơi, hấp thụ nhiệt từ không khí, làm giảm nhiệt độ của luồng gió thổi ra. Quá trình này không chỉ giúp làm mát mà còn tạo độ ẩm cho không gian. Một quạt điều hòa dùng cho gia đình có dung tích bình chứa nước là 8 lít, khi công suất của quạt cực đại thì lưu lượng gió qua quạt là 400 m3/h. Một gia đình sử dụng quạt bật ở chế độ cực đại để làm mát ở điều kiện nhiệt độ bên ngoài là 350C thì không khí quạt thổi ra có nhiệt độ 270C. Biết<br>khối lượng riêng của không khí là 1,12 kg/m3 nhiệt hóa hơi riêng của nước ở 350C là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của nước 1000 kg/m3, nhiệt dung riêng của không khí là 1005 J/(kg.K). tốc độ bay hơi của nước được xem là đều.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047294127-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ của không khí giảm 46,4 (0F) khi đi qua các tấm làm mát.","answer":false},{"text":"Nhiệt lượng mà nước thu vào để hóa hơi được lấy từ không khí đi qua mát.","answer":true},{"text":"Nhiệt lượng mà nước thu vào để hóa hơi trong một đơn vị thời gian (làm tròn đến hàng phần mười) là 750,4 J","answer":false},{"text":"Nước trong bình chứa được đổ đầy trước khi sử dụng, thời gian sử dụng của quạt cho đến khi hết nước trong bình (làm tròn đến hàng phần trăm) là 5,02 giờ.","answer":true}],"explanation":"a) sai<br>Độ biến thiên nhiệt độ của không khí theo thang Celsius là:  $\\Delta t=35−27=8^0C$<br>Độ biến thiên nhiệt độ theo thang Fahrenheit là:  $\\Delta T(^0F)=1,8\\Delta t(^0C)=1,8.8=14,4^0F$<br>b) đúng<br>Theo nguyên lý hoạt động của quạt điều hòa được mô tả, nước bay hơi sẽ thu nhiệt lượng từ luồng không khí nóng thổi qua, từ đó làm giảm nhiệt độ của không khí<br>c) sai<br>Khối lượng không khí đi qua quạt trong 1 giây (1 đơn vị thời gian) là:<br>$m_{kk}=\\frac{400}{3600}.1,12=\\frac{1,12}{9}(kg/s)$<br>Nhiệt lượng không khí tỏa ra trong 1 giây để hạ từ 350C xuống 270C cũng chính là nhiệt lượng nước thu vào để hóa hơi trong 1 giây:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047294302-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Thể tích nước tối đa trong bình là V = 8 lít = 8.10<sup>−3</sup> m3.<br>Khối lượng nước trong bình: $m_n=V.D_n=8.10^{−3}.1000=8kg$  .<br>Tổng nhiệt lượng cần cung cấp để toàn bộ 8 kg nước này hóa hơi là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Qtong = mn.L = 8.2,26.10<sup>6</sup> = 18,08.10<sup>6</sup> J<br>Thời gian để quạt sử dụng hết lượng nước này là:<br>$t=\\frac{Q_{tong}}{Q_{1s}}=\\frac{18,08.10^6}{1000,533}\\approx 18070,36s\\approx 5,02$  giờ","difficultySource":"ai"},"ex":[{"exam":461,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Quạt điều hòa là thiết bị làm mát hoạt động dựa trên nguyên lý bay hơi nước, kết hợp với cơ chế lưu thông không khí. Khi không khí nóng đi qua các tấm làm mát được giữ ẩm, nước trên tấm này bay hơi, hấp thụ nhiệt từ không khí, làm giảm nhiệt độ của luồng gió thổi ra. Quá trình này không chỉ giúp làm mát mà còn tạo độ ẩm cho không gian. Một quạt điều hòa dùng cho gia đình có dung tích bình chứa nước là 8 lít, khi công suất của quạt cực đại thì lưu lượng gió qua quạt là 400 m3/h. Một gia đình sử dụng quạt bật ở chế độ cực đại để làm mát ở điều kiện nhiệt độ bên ngoài là 350C thì không khí quạt thổi ra có nhiệt độ 270C. Biết<br>khối lượng riêng của không khí là 1,12 kg/m3 nhiệt hóa hơi riêng của nước ở 350C là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của nước 1000 kg/m3, nhiệt dung riêng của không khí là 1005 J/(kg.K). tốc độ bay hơi của nước được xem là đều.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047294127-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ của không khí giảm 46,4 (0F) khi đi qua các tấm làm mát.","answer":false},{"text":"Nhiệt lượng mà nước thu vào để hóa hơi được lấy từ không khí đi qua mát.","answer":true},{"text":"Nhiệt lượng mà nước thu vào để hóa hơi trong một đơn vị thời gian (làm tròn đến hàng phần mười) là 750,4 J","answer":false},{"text":"Nước trong bình chứa được đổ đầy trước khi sử dụng, thời gian sử dụng của quạt cho đến khi hết nước trong bình (làm tròn đến hàng phần trăm) là 5,02 giờ.","answer":true}],"explanation":"a) sai<br>Độ biến thiên nhiệt độ của không khí theo thang Celsius là:  $\\Delta t=35−27=8^0C$<br>Độ biến thiên nhiệt độ theo thang Fahrenheit là:  $\\Delta T(^0F)=1,8\\Delta t(^0C)=1,8.8=14,4^0F$<br>b) đúng<br>Theo nguyên lý hoạt động của quạt điều hòa được mô tả, nước bay hơi sẽ thu nhiệt lượng từ luồng không khí nóng thổi qua, từ đó làm giảm nhiệt độ của không khí<br>c) sai<br>Khối lượng không khí đi qua quạt trong 1 giây (1 đơn vị thời gian) là:<br>$m_{kk}=\\frac{400}{3600}.1,12=\\frac{1,12}{9}(kg/s)$<br>Nhiệt lượng không khí tỏa ra trong 1 giây để hạ từ 350C xuống 270C cũng chính là nhiệt lượng nước thu vào để hóa hơi trong 1 giây:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047294302-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>Thể tích nước tối đa trong bình là V = 8 lít = 8.10<sup>−3</sup> m3.<br>Khối lượng nước trong bình: $m_n=V.D_n=8.10^{−3}.1000=8kg$  .<br>Tổng nhiệt lượng cần cung cấp để toàn bộ 8 kg nước này hóa hơi là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Qtong = mn.L = 8.2,26.10<sup>6</sup> = 18,08.10<sup>6</sup> J<br>Thời gian để quạt sử dụng hết lượng nước này là:<br>$t=\\frac{Q_{tong}}{Q_{1s}}=\\frac{18,08.10^6}{1000,533}\\approx 18070,36s\\approx 5,02$  giờ","difficultySource":"ai"}}]},{"id":673946,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"57","question":"Để nghiên cứu đường đi của phân bón trong cây trồng, người ta sẽ bón phân có chứa ${}_{15}^{32}P$ , một đồng vị của phosphor có tính phóng xạ β‒ với chu kì bán rã là 14,28 ngày. Giả sử một mẫu phân bón có chứa 0,2 µg đồng vị  ${}_{15}^{32}P$  thì độ phóng xạ của nó bằng bao nhiêu mCi? Biết 1 Ci = 3,7.10<sup>10</sup> Bq. (Kết quả làm tròn đến phần nguyên).","difficulty":"trung-binh","explanation":"Đổi đơn vị chu kì bán rã T = 14,28.24.3600 =1233792 s.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lấy hằng số Avogadro NA  $\\approx$  6,02.10<sup>23</sup> mol-1, số hạt nhân  ${}_{15}^{32}P$ có trong mẫu là:<br>$N=\\frac{0,2.10^{−6}}{32}.6,02.10^{23}=3,7625.10^{15}$  hạt<br>Độ phóng xạ của mẫu phân bón là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047295022-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đổi sang đơn vị mCi ta được:  $H=\\frac{2,114.10^9}{3,7.10^{10}}.1000\\approx 57mCi$","difficultySource":"ai"},"ex":[{"exam":461,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"57","question":"Để nghiên cứu đường đi của phân bón trong cây trồng, người ta sẽ bón phân có chứa ${}_{15}^{32}P$ , một đồng vị của phosphor có tính phóng xạ β‒ với chu kì bán rã là 14,28 ngày. Giả sử một mẫu phân bón có chứa 0,2 µg đồng vị  ${}_{15}^{32}P$  thì độ phóng xạ của nó bằng bao nhiêu mCi? Biết 1 Ci = 3,7.10<sup>10</sup> Bq. (Kết quả làm tròn đến phần nguyên).","difficulty":"trung-binh","explanation":"Đổi đơn vị chu kì bán rã T = 14,28.24.3600 =1233792 s.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lấy hằng số Avogadro NA  $\\approx$  6,02.10<sup>23</sup> mol-1, số hạt nhân  ${}_{15}^{32}P$ có trong mẫu là:<br>$N=\\frac{0,2.10^{−6}}{32}.6,02.10^{23}=3,7625.10^{15}$  hạt<br>Độ phóng xạ của mẫu phân bón là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047295022-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đổi sang đơn vị mCi ta được:  $H=\\frac{2,114.10^9}{3,7.10^{10}}.1000\\approx 57mCi$","difficultySource":"ai"}}]},{"id":673963,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một cốc nhôm có khối lượng 0,20 kg chứa 0,50 kg nước ở nhiệt độ 25 C được đặt vào ngăn đông của tủ lạnh. Sau khoảng thời gian τ (s), nhiệt độ của cả cốc và nước giảm xuống còn 5 C. Bỏ qua sự trao đổi nhiệt với môi trường khác và sự bay hơi của nước. Xem nhiệt độ của nước trong cốc là đồng nhất và bằng nhiệt độ của cốc.<br>Cho nhiệt dung riêng của nước là 4200 J/(kg.K) và của nhôm là 900 J/(kg.K). Nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg.","difficulty":"kho","statements":[{"text":"Nhiệt lượng mà cốc nhôm và nước đã tỏa ra trong khoảng thời gian τ là 42 kJ.","answer":false},{"text":"Công suất làm lạnh trung bình của tủ lạnh  $℘\\left(W\\right)$  được xác định bằng biểu thức  $℘=\\frac{Q}{\\Delta \\tau }.$  Trong đó, Q (J) là nhiệt lượng mà tủ lạnh nhận được từ cốc nhôm và nước trong khoảng thời gian τ (s).","answer":true},{"text":"Nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, nhiệt độ của cốc nhôm và nước giảm từ 5 C xuống còn 0 C.","answer":false},{"text":"Nếu công suất làm lạnh của tủ lạnh không đổi thì khoảng thời gian cần thiết để làm đông đặc hoàn toàn lượng nước trong cốc (ở 0 C) là 1,5τ.","answer":false}],"explanation":"a) sai<br>Nhiệt lượng mà cốc nhôm và nước đã tỏa ra trong khoảng thời gian τ là:<br>$Q_1=\\left(m_c.c_{nh}+m_n.c_n\\right).\\left(t_0-t\\right)=\\left(0,2.900+0,5.4200\\right).\\left(25-5\\right)=45600$  J = 45,6 kJ.<br>b) đúng<br>Công suất làm lạnh trung bình của tủ lạnh ℘ (W) được xác định bằng biểu thức  $℘=\\frac{Q}{\\Delta \\tau }$ . Trong đó, Q (J) là nhiệt lượng mà tủ lạnh nhận được từ cốc nhôm và nước trong khoảng thời gian τ (s).<br>c) sai<br>Nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, độ giảm nhiệt độ của cốc nhôm và nước là:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $\\left(m_c.c_{nh}+m_n.c_n\\right).\\Delta t=℘.0,2\\tau =0,2.Q_1$<br>$\\Delta t=\\frac{0,2.Q_1}{m_c.c_{nh}+m_n.c_n}=\\frac{0,2.45600}{0,2.900+0,5.4200}=4$  C.<br>Vậy, nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, nhiệt độ của cốc nhôm và nước giảm từ 5 C xuống còn 1 C.<br>d) sai<br>Nếu công suất làm lạnh của tủ lạnh không đổi thì khoảng thời gian cần thiết để làm đông đặc hoàn toàn lượng nước trong cốc (ở 0 C) là:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $.m_n=℘.\\tau$<br>Mà:  $Q_1=℘.\\tau$<br>Suy ra:  $\\Delta \\tau =\\frac{.m_n.\\tau }{Q_1}=\\frac{3,34.{10}^5.0,5.\\tau }{45600}\\approx 3,7.\\tau$","difficultySource":"ai"},"ex":[{"exam":462,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một cốc nhôm có khối lượng 0,20 kg chứa 0,50 kg nước ở nhiệt độ 25 C được đặt vào ngăn đông của tủ lạnh. Sau khoảng thời gian τ (s), nhiệt độ của cả cốc và nước giảm xuống còn 5 C. Bỏ qua sự trao đổi nhiệt với môi trường khác và sự bay hơi của nước. Xem nhiệt độ của nước trong cốc là đồng nhất và bằng nhiệt độ của cốc.<br>Cho nhiệt dung riêng của nước là 4200 J/(kg.K) và của nhôm là 900 J/(kg.K). Nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg.","difficulty":"kho","statements":[{"text":"Nhiệt lượng mà cốc nhôm và nước đã tỏa ra trong khoảng thời gian τ là 42 kJ.","answer":false},{"text":"Công suất làm lạnh trung bình của tủ lạnh  $℘\\left(W\\right)$  được xác định bằng biểu thức  $℘=\\frac{Q}{\\Delta \\tau }.$  Trong đó, Q (J) là nhiệt lượng mà tủ lạnh nhận được từ cốc nhôm và nước trong khoảng thời gian τ (s).","answer":true},{"text":"Nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, nhiệt độ của cốc nhôm và nước giảm từ 5 C xuống còn 0 C.","answer":false},{"text":"Nếu công suất làm lạnh của tủ lạnh không đổi thì khoảng thời gian cần thiết để làm đông đặc hoàn toàn lượng nước trong cốc (ở 0 C) là 1,5τ.","answer":false}],"explanation":"a) sai<br>Nhiệt lượng mà cốc nhôm và nước đã tỏa ra trong khoảng thời gian τ là:<br>$Q_1=\\left(m_c.c_{nh}+m_n.c_n\\right).\\left(t_0-t\\right)=\\left(0,2.900+0,5.4200\\right).\\left(25-5\\right)=45600$  J = 45,6 kJ.<br>b) đúng<br>Công suất làm lạnh trung bình của tủ lạnh ℘ (W) được xác định bằng biểu thức  $℘=\\frac{Q}{\\Delta \\tau }$ . Trong đó, Q (J) là nhiệt lượng mà tủ lạnh nhận được từ cốc nhôm và nước trong khoảng thời gian τ (s).<br>c) sai<br>Nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, độ giảm nhiệt độ của cốc nhôm và nước là:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $\\left(m_c.c_{nh}+m_n.c_n\\right).\\Delta t=℘.0,2\\tau =0,2.Q_1$<br>$\\Delta t=\\frac{0,2.Q_1}{m_c.c_{nh}+m_n.c_n}=\\frac{0,2.45600}{0,2.900+0,5.4200}=4$  C.<br>Vậy, nếu công suất làm lạnh của tủ lạnh không đổi thì trong khoảng thời gian 0,2τ tiếp theo, nhiệt độ của cốc nhôm và nước giảm từ 5 C xuống còn 1 C.<br>d) sai<br>Nếu công suất làm lạnh của tủ lạnh không đổi thì khoảng thời gian cần thiết để làm đông đặc hoàn toàn lượng nước trong cốc (ở 0 C) là:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $.m_n=℘.\\tau$<br>Mà:  $Q_1=℘.\\tau$<br>Suy ra:  $\\Delta \\tau =\\frac{.m_n.\\tau }{Q_1}=\\frac{3,34.{10}^5.0,5.\\tau }{45600}\\approx 3,7.\\tau$","difficultySource":"ai"}}]},{"id":673964,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Hệ thống cảnh báo áp suất lốp xe (TPMS) trên ô tô giúp người lái giám sát áp suất không khí trong lốp. Xem không khí trong lốp là khí lí tưởng, thể tích lốp và lượng không khí trong lốp không đổi. Khi xe đang đỗ, nhiệt độ không khí trong lốp là 27 C và áp suất không khí trong lốp là 2,20.10<sup>5</sup> Pa. Sau khi xe chạy một thời gian, nhiệt độ không khí trong lốp là 57 C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047305581-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi nhiệt độ celsius của không khí trong lốp tăng gấp đôi thì động năng tịnh tiến trung bình của các phân tử khí trong lốp cũng tăng gấp đôi.","answer":false},{"text":"Khi nhiệt độ không khí trong lốp là 57 C, áp suất không khí trong lốp là 2,42.10<sup>5</sup> Pa.","answer":true},{"text":"Quá trình biến đổi trạng thái của không khí trong lốp từ nhiệt độ 27 C lên đến 57 C được biểu diễn trong hệ tọa độ (p, T) bằng một đoạn thẳng có đường kéo dài đi qua gốc tọa độ.","answer":true},{"text":"Để áp suất không khí trong lốp giảm còn 1,20.10<sup>5</sup> Pa ở nhiệt độ 27 C, cần xả bớt khoảng 45% lượng không khí trong lốp so với ban đầu.","answer":true}],"explanation":"a) sai<br>Khi nhiệt độ tuyệt đối của không khí trong lốp tăng gấp đôi thì động năng tịnh tiến trung bình của các phân tử khí trong lốp ( $E_đ=\\frac{3}{2}kT$ ) cũng tăng gấp đôi.<br>b) đúng<br>Do thể tích lốp và lượng không khí trong lốp không đổi nên quá trình biến đổi trạng thái của lượng không khí trong lốp là quá trình đẳng tích.<br>Khi nhiệt độ không khí trong lốp là 57 C, áp suất không khí trong lốp là:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{T_2.p_1}{T_1}=\\frac{\\left(57+273\\right).2,2.{10}^5}{27+273}=2,42.{10}^5$  Pa.<br>c) đúng<br>Do quá trình biến đổi trạng thái của không khí trong lốp từ nhiệt độ 27 C lên đến 57 C là quá trình đẳng tích nên được biểu diễn trong hệ tọa độ (p, T) bằng một đoạn thẳng có đường kéo dài đi qua gốc tọa độ.<br>d) đúng<br>Tỉ số giữa lượng không khí cần xả bớt và lượng không khí ban đầu để áp suất không khí trong lốp giảm còn 1,2.10<sup>5</sup> Pa ở nhiệt độ 27 C là:<br>$\\frac{\\Delta n}{n_1}=1-\\frac{n_3}{n_1}=1-\\frac{p_3}{p_1}=1-\\frac{1,2.{10}^5}{2,2.{10}^5}\\approx 45%$ .","difficultySource":"ai"},"ex":[{"exam":462,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Hệ thống cảnh báo áp suất lốp xe (TPMS) trên ô tô giúp người lái giám sát áp suất không khí trong lốp. Xem không khí trong lốp là khí lí tưởng, thể tích lốp và lượng không khí trong lốp không đổi. Khi xe đang đỗ, nhiệt độ không khí trong lốp là 27 C và áp suất không khí trong lốp là 2,20.10<sup>5</sup> Pa. Sau khi xe chạy một thời gian, nhiệt độ không khí trong lốp là 57 C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047305581-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi nhiệt độ celsius của không khí trong lốp tăng gấp đôi thì động năng tịnh tiến trung bình của các phân tử khí trong lốp cũng tăng gấp đôi.","answer":false},{"text":"Khi nhiệt độ không khí trong lốp là 57 C, áp suất không khí trong lốp là 2,42.10<sup>5</sup> Pa.","answer":true},{"text":"Quá trình biến đổi trạng thái của không khí trong lốp từ nhiệt độ 27 C lên đến 57 C được biểu diễn trong hệ tọa độ (p, T) bằng một đoạn thẳng có đường kéo dài đi qua gốc tọa độ.","answer":true},{"text":"Để áp suất không khí trong lốp giảm còn 1,20.10<sup>5</sup> Pa ở nhiệt độ 27 C, cần xả bớt khoảng 45% lượng không khí trong lốp so với ban đầu.","answer":true}],"explanation":"a) sai<br>Khi nhiệt độ tuyệt đối của không khí trong lốp tăng gấp đôi thì động năng tịnh tiến trung bình của các phân tử khí trong lốp ( $E_đ=\\frac{3}{2}kT$ ) cũng tăng gấp đôi.<br>b) đúng<br>Do thể tích lốp và lượng không khí trong lốp không đổi nên quá trình biến đổi trạng thái của lượng không khí trong lốp là quá trình đẳng tích.<br>Khi nhiệt độ không khí trong lốp là 57 C, áp suất không khí trong lốp là:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{T_2.p_1}{T_1}=\\frac{\\left(57+273\\right).2,2.{10}^5}{27+273}=2,42.{10}^5$  Pa.<br>c) đúng<br>Do quá trình biến đổi trạng thái của không khí trong lốp từ nhiệt độ 27 C lên đến 57 C là quá trình đẳng tích nên được biểu diễn trong hệ tọa độ (p, T) bằng một đoạn thẳng có đường kéo dài đi qua gốc tọa độ.<br>d) đúng<br>Tỉ số giữa lượng không khí cần xả bớt và lượng không khí ban đầu để áp suất không khí trong lốp giảm còn 1,2.10<sup>5</sup> Pa ở nhiệt độ 27 C là:<br>$\\frac{\\Delta n}{n_1}=1-\\frac{n_3}{n_1}=1-\\frac{p_3}{p_1}=1-\\frac{1,2.{10}^5}{2,2.{10}^5}\\approx 45%$ .","difficultySource":"ai"}}]},{"id":673966,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Một mẫu phóng xạ alpha  ${}_{88}^{226}{Ra}$  có chu kì bán rã 1600 năm. Ban đầu mẫu chỉ chứa 22,6 g  ${}_{88}^{226}{Ra}.$  Giả sử các hạt alpha sinh ra đều trở thành khí helium và được giữ lại trong bình. Coi khối lượng mol của nguyên tử (g/mol) có giá trị xấp xỉ bằng số khối của nguyên tử đó. Xem khí helium là khí lí tưởng.","difficulty":"kho","statements":[{"text":"Phương trình phóng xạ của  ${}_{88}^{226}{Ra}$  là  ${}_{88}^{226}{Ra}\\rightarrow {}_{86}^{222}{Rn}+{}_2^4{He}.$","answer":true},{"text":"Hằng số phóng xạ của  ${}_{88}^{226}{Ra}$  xấp xỉ bằng 4,33.10<sup>4</sup> năm1.","answer":true},{"text":"Sau 1600 năm, khối lượng  ${}_{88}^{226}{Ra}$  còn lại trong mẫu là 11,3 g.","answer":true},{"text":"Sau 1600 năm, nếu thu toàn bộ khí helium sinh ra ở điều kiện chuẩn (nhiệt độ 25 C, áp suất 1 Bar = 105 Pa) thì thể tích khí helium thu được xấp xỉ bằng 1,12 lít.","answer":false}],"explanation":"a) đúng<br>Do  ${}_{88}^{226}{Ra}$  là chất phóng xạ alpha nên phương trình phóng xạ của  ${}_{88}^{226}{Ra}$  là  ${}_{88}^{226}{Ra}\\rightarrow {}_{86}^{222}{Rn}+{}_2^4{He}$ .<br>b) đúng<br>Hằng số phóng xạ của  ${}_{88}^{226}{Ra}$  là:  $=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{1600}\\approx 4,33.{10}^{-4}$  năm1.<br>c) đúng<br>Sau 1600 năm, khối lượng  ${}_{88}^{226}{Ra}$  còn lại trong mẫu là:<br>$m_t=m_0.2^{-\\frac{t}{T}}=22,6.2^{-\\frac{1600}{1600}}=11,3$  g.<br>d) sai<br>Số hạt nhân  ${}_{88}^{226}{Ra}$  đã phân rã trong khoảng thời gian t bằng số hạt nhân  ${}_2^4{He}$  tạo thành.<br>$\\Delta N=N_0-N_t=N_0\\left(1-2^{-\\frac{t}{T}}\\right)=\\frac{m_0}{M_{Ra}}.N_A.\\left(1-2^{-\\frac{t}{T}}\\right)$<br>Số mol  ${}_2^4{He}$  được tạo thành trong khoảng thời gian t:<br>$n=\\frac{\\Delta N}{N_A}=\\frac{m_0}{M_{Ra}}.\\left(1-2^{-\\frac{t}{T}}\\right)$<br>Thể tích khí helium thu được ở điều kiện chuẩn là:<br>$pV=nRT$<br>$V=\\frac{nRT}{p}=\\frac{m_0}{M_{Ra}}.\\left(1-2^{-\\frac{t}{T}}\\right).\\frac{RT}{p}=\\frac{22,6}{226}.\\left(1-2^{-\\frac{1600}{1600}}\\right).\\frac{8,31.\\left(25+273\\right)}{{10}^5}\\approx 1,24.{10}^{-3}$  m3 = 1,24 lít.","difficultySource":"ai"},"ex":[{"exam":462,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Một mẫu phóng xạ alpha  ${}_{88}^{226}{Ra}$  có chu kì bán rã 1600 năm. Ban đầu mẫu chỉ chứa 22,6 g  ${}_{88}^{226}{Ra}.$  Giả sử các hạt alpha sinh ra đều trở thành khí helium và được giữ lại trong bình. Coi khối lượng mol của nguyên tử (g/mol) có giá trị xấp xỉ bằng số khối của nguyên tử đó. Xem khí helium là khí lí tưởng.","difficulty":"kho","statements":[{"text":"Phương trình phóng xạ của  ${}_{88}^{226}{Ra}$  là  ${}_{88}^{226}{Ra}\\rightarrow {}_{86}^{222}{Rn}+{}_2^4{He}.$","answer":true},{"text":"Hằng số phóng xạ của  ${}_{88}^{226}{Ra}$  xấp xỉ bằng 4,33.10<sup>4</sup> năm1.","answer":true},{"text":"Sau 1600 năm, khối lượng  ${}_{88}^{226}{Ra}$  còn lại trong mẫu là 11,3 g.","answer":true},{"text":"Sau 1600 năm, nếu thu toàn bộ khí helium sinh ra ở điều kiện chuẩn (nhiệt độ 25 C, áp suất 1 Bar = 105 Pa) thì thể tích khí helium thu được xấp xỉ bằng 1,12 lít.","answer":false}],"explanation":"a) đúng<br>Do  ${}_{88}^{226}{Ra}$  là chất phóng xạ alpha nên phương trình phóng xạ của  ${}_{88}^{226}{Ra}$  là  ${}_{88}^{226}{Ra}\\rightarrow {}_{86}^{222}{Rn}+{}_2^4{He}$ .<br>b) đúng<br>Hằng số phóng xạ của  ${}_{88}^{226}{Ra}$  là:  $=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{1600}\\approx 4,33.{10}^{-4}$  năm1.<br>c) đúng<br>Sau 1600 năm, khối lượng  ${}_{88}^{226}{Ra}$  còn lại trong mẫu là:<br>$m_t=m_0.2^{-\\frac{t}{T}}=22,6.2^{-\\frac{1600}{1600}}=11,3$  g.<br>d) sai<br>Số hạt nhân  ${}_{88}^{226}{Ra}$  đã phân rã trong khoảng thời gian t bằng số hạt nhân  ${}_2^4{He}$  tạo thành.<br>$\\Delta N=N_0-N_t=N_0\\left(1-2^{-\\frac{t}{T}}\\right)=\\frac{m_0}{M_{Ra}}.N_A.\\left(1-2^{-\\frac{t}{T}}\\right)$<br>Số mol  ${}_2^4{He}$  được tạo thành trong khoảng thời gian t:<br>$n=\\frac{\\Delta N}{N_A}=\\frac{m_0}{M_{Ra}}.\\left(1-2^{-\\frac{t}{T}}\\right)$<br>Thể tích khí helium thu được ở điều kiện chuẩn là:<br>$pV=nRT$<br>$V=\\frac{nRT}{p}=\\frac{m_0}{M_{Ra}}.\\left(1-2^{-\\frac{t}{T}}\\right).\\frac{RT}{p}=\\frac{22,6}{226}.\\left(1-2^{-\\frac{1600}{1600}}\\right).\\frac{8,31.\\left(25+273\\right)}{{10}^5}\\approx 1,24.{10}^{-3}$  m3 = 1,24 lít.","difficultySource":"ai"}}]},{"id":673967,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"240","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20 C. Cho nhiệt hóa hơi riêng của nước là 2.10<sup>6</sup> J/kg. Bỏ qua sự thất thoát nhiệt ra môi trường. Sau khi nước đạt đến nhiệt độ sôi, người ta mở nắp và tiếp tục đun thêm 2 phút nữa. Khối lượng nước còn lại trong ấm bằng bao nhiêu gam (g)? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Khối lượng nước đã hóa hơi:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $℘.\\tau =L.m_{hh}$    $m_{hh}=\\frac{℘.\\tau }{L}=\\frac{1000.2.60}{2.{10}^6}=0,06$  kg = 60 g.<br>Khối lượng nước còn lại trong ấm bằng 300 – 60 = 240 g.","difficultySource":"ai"},"ex":[{"exam":462,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"240","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20 C. Cho nhiệt hóa hơi riêng của nước là 2.10<sup>6</sup> J/kg. Bỏ qua sự thất thoát nhiệt ra môi trường. Sau khi nước đạt đến nhiệt độ sôi, người ta mở nắp và tiếp tục đun thêm 2 phút nữa. Khối lượng nước còn lại trong ấm bằng bao nhiêu gam (g)? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Khối lượng nước đã hóa hơi:<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $℘.\\tau =L.m_{hh}$    $m_{hh}=\\frac{℘.\\tau }{L}=\\frac{1000.2.60}{2.{10}^6}=0,06$  kg = 60 g.<br>Khối lượng nước còn lại trong ấm bằng 300 – 60 = 240 g.","difficultySource":"ai"}}]},{"id":673972,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,15","question":"Trong điều trị ung thư bằng phương pháp xạ trị, trước đây nhiều bệnh viện sử dụng nguồn phát tia gamma từ đồng vị phóng xạ  ${}_{27}^{60}{Co}.$  Đồng vị này có chu kì bán rã 5,27 năm (mỗi năm xem như có 365 ngày). Các tia gamma phát ra trong quá trình phóng xạ của  ${}_{27}^{60}{Co}$  được dùng để tiêu diệt tế bào ung thư. Một nguồn phóng xạ  ${}_{27}^{60}{Co}$  tại bệnh viện có độ phóng xạ 5800 Ci (1 Ci = 3,7.10<sup>10</sup> Bq). Số hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ là x.10<sup>22</sup> hạt. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ là:<br>$H=N=\\frac{\\ln\\left(2\\right)}{T}.N$    $N=\\frac{T.H}{\\ln\\left(2\\right)}=\\frac{5,27.365.24.3600.5800.3,7.{10}^{10}}{\\ln\\left(2\\right)}\\approx 5,15.{10}^{22}$  hạt.<br>Vậy x = 5,15.","difficultySource":"ai"},"ex":[{"exam":462,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,15","question":"Trong điều trị ung thư bằng phương pháp xạ trị, trước đây nhiều bệnh viện sử dụng nguồn phát tia gamma từ đồng vị phóng xạ  ${}_{27}^{60}{Co}.$  Đồng vị này có chu kì bán rã 5,27 năm (mỗi năm xem như có 365 ngày). Các tia gamma phát ra trong quá trình phóng xạ của  ${}_{27}^{60}{Co}$  được dùng để tiêu diệt tế bào ung thư. Một nguồn phóng xạ  ${}_{27}^{60}{Co}$  tại bệnh viện có độ phóng xạ 5800 Ci (1 Ci = 3,7.10<sup>10</sup> Bq). Số hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ là x.10<sup>22</sup> hạt. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{27}^{60}{Co}$  chứa trong nguồn phóng xạ là:<br>$H=N=\\frac{\\ln\\left(2\\right)}{T}.N$    $N=\\frac{T.H}{\\ln\\left(2\\right)}=\\frac{5,27.365.24.3600.5800.3,7.{10}^{10}}{\\ln\\left(2\\right)}\\approx 5,15.{10}^{22}$  hạt.<br>Vậy x = 5,15.","difficultySource":"ai"}}]},{"id":673974,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["4,8.10<sup>5</sup> J.","2,4.10<sup>4</sup> J.","2,4.10<sup>5</sup> J.","3,6.10<sup>4</sup> J."],"question":"Nhiệt lượng tối thiểu cần cung cấp để làm giảm khối lượng bao thóc như trên xấp xỉ bằng","difficulty":"de","explanation":"Nhiệt lượng tối thiểu cần cung cấp để làm giảm khối lượng bao thóc như trên xấp xỉ bằng<br>$Q=L.m=2,4.{10}^6.\\left(20-19,8\\right)=4,8.{10}^5$  J.","difficultySource":"ai"},"ex":[{"exam":463,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["4,8.10<sup>5</sup> J.","2,4.10<sup>4</sup> J.","2,4.10<sup>5</sup> J.","3,6.10<sup>4</sup> J."],"question":"Nhiệt lượng tối thiểu cần cung cấp để làm giảm khối lượng bao thóc như trên xấp xỉ bằng","difficulty":"de","explanation":"Nhiệt lượng tối thiểu cần cung cấp để làm giảm khối lượng bao thóc như trên xấp xỉ bằng<br>$Q=L.m=2,4.{10}^6.\\left(20-19,8\\right)=4,8.{10}^5$  J.","difficultySource":"ai"}}]},{"id":673987,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":2,"options":["19,03.10<sup>10</sup> MeV.","6,02.10<sup>23</sup> MeV.","12,04.10<sup>23</sup> MeV.","16,04.10<sup>23</sup> MeV."],"question":"Giả sử mỗi hạt nhân Uranium  ${}_{92}^{235}U$  khi phân hạch tỏa ra năng lượng 200 MeV. Nếu 2,35 g  ${}_{92}^{235}U$  bị phân hạch hoàn toàn thì tổng năng lượng tỏa ra xấp xỉ bằng","difficulty":"trung-binh","explanation":"Tổng năng lượng tỏa ra khi 2,35 g  ${}_{92}^{235}U$  phân hạch hoàn toàn là:<br>$E=N.\\Delta E=\\frac{m}{M}.N_A.\\Delta E=\\frac{2,35}{235}.6,02.{10}^{23}.200=12,04.{10}^{23}$  MeV.","difficultySource":"ai"},"ex":[{"exam":463,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":2,"options":["19,03.10<sup>10</sup> MeV.","6,02.10<sup>23</sup> MeV.","12,04.10<sup>23</sup> MeV.","16,04.10<sup>23</sup> MeV."],"question":"Giả sử mỗi hạt nhân Uranium  ${}_{92}^{235}U$  khi phân hạch tỏa ra năng lượng 200 MeV. Nếu 2,35 g  ${}_{92}^{235}U$  bị phân hạch hoàn toàn thì tổng năng lượng tỏa ra xấp xỉ bằng","difficulty":"trung-binh","explanation":"Tổng năng lượng tỏa ra khi 2,35 g  ${}_{92}^{235}U$  phân hạch hoàn toàn là:<br>$E=N.\\Delta E=\\frac{m}{M}.N_A.\\Delta E=\\frac{2,35}{235}.6,02.{10}^{23}.200=12,04.{10}^{23}$  MeV.","difficultySource":"ai"}}]},{"id":673992,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Hình vẽ bên dưới là mô hình “tên lửa nước” gồm một chai nhựa có dung tích 2,0 lít, được gắn thêm mũi và cánh. Người ta đổ nước vào chai sao cho thể tích không khí còn lại trong chai là 1,5 lít. Ban đầu, không khí trong chai có nhiệt độ 27 C, áp suất 1,0.10<sup>5</sup> Pa và khối lượng là m0 (kg), Sau đó, người ta bơm thêm vào chai một lượng không khí có khối lượng 3m0 (kg). Khi đó, nhiệt độ của không khí trong chai là 37 C. Xem thể tích phần không khí trong chai không đổi, nước chưa phụt ra ngoài và xem không khí là khí lí tưởng. Khối lượng mol của không khí là 29 g/mol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047309706-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng không khí trong chai ở thời điểm ban đầu xấp xỉ bằng 1,7 g.","answer":true},{"text":"Áp suất của không khí trong chai sau khi bơm thêm 3m0 (kg) không khí vào là 3,1.10<sup>5</sup> Pa.","answer":false},{"text":"Khi nhiệt độ của không khí trong chai tăng lên, động năng tịnh tiến trung bình của các phân tử khí cũng tăng.","answer":true},{"text":"Biết diện tích mặt nước là 0,014 m2. Khi nhiệt độ của không khí trong chai tăng từ 27 C lên đến 37 C, lực của không khí tác dụng lên mặt nước tăng 5787 N (kết quả được làm tròn đến chữ số hàng đơn vị).","answer":false}],"explanation":"a) đúng<br>Khối lượng không khí trong chai ở thời điểm ban đầu là:<br>$p_0V=\\frac{m_0}{M}RT_0$    $m_0=\\frac{Mp_0V}{RT_0}=\\frac{29.{10}^5.1,5.{10}^{-3}}{8,31.\\left(27+273\\right)}\\approx 1,7$  g.<br>b) sai<br>Áp suất của không khí trong chai sau khi bơm thêm 3m0 (kg) không khí vào là:<br>Ta có:  $p_0V=\\frac{m_0}{M}RT_0$  và  $pV=\\frac{m_0+3m_0}{M}RT$ .<br>Suy ra:  $p=\\frac{4Tp_0}{T_0}=\\frac{4.\\left(37+273\\right).{10}^5}{27+273}=\\frac{62}{15}.{10}^5Pa\\approx 4,1.{10}^5$  Pa.<br>c) đúng<br>Khi nhiệt độ tuyệt đối (hay nhiệt độ) của không khí trong chai tăng lên, động năng tịnh tiến trung bình của các phân tử khí ( $E_đ=\\frac{3}{2}kT$ ) cũng tăng.<br>d) sai<br>Khi nhiệt độ của không khí trong chai tăng từ 27 C lên đến 37 C, lực của không khí tác dụng lên mặt nước tăng một lượng  $\\Delta F=\\Delta p.S=\\left(p-p_0\\right).S=\\left(\\frac{62}{15}.{10}^5-{10}^5\\right).0,014\\approx 4387$  N.","difficultySource":"ai"},"ex":[{"exam":463,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Hình vẽ bên dưới là mô hình “tên lửa nước” gồm một chai nhựa có dung tích 2,0 lít, được gắn thêm mũi và cánh. Người ta đổ nước vào chai sao cho thể tích không khí còn lại trong chai là 1,5 lít. Ban đầu, không khí trong chai có nhiệt độ 27 C, áp suất 1,0.10<sup>5</sup> Pa và khối lượng là m0 (kg), Sau đó, người ta bơm thêm vào chai một lượng không khí có khối lượng 3m0 (kg). Khi đó, nhiệt độ của không khí trong chai là 37 C. Xem thể tích phần không khí trong chai không đổi, nước chưa phụt ra ngoài và xem không khí là khí lí tưởng. Khối lượng mol của không khí là 29 g/mol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047309706-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng không khí trong chai ở thời điểm ban đầu xấp xỉ bằng 1,7 g.","answer":true},{"text":"Áp suất của không khí trong chai sau khi bơm thêm 3m0 (kg) không khí vào là 3,1.10<sup>5</sup> Pa.","answer":false},{"text":"Khi nhiệt độ của không khí trong chai tăng lên, động năng tịnh tiến trung bình của các phân tử khí cũng tăng.","answer":true},{"text":"Biết diện tích mặt nước là 0,014 m2. Khi nhiệt độ của không khí trong chai tăng từ 27 C lên đến 37 C, lực của không khí tác dụng lên mặt nước tăng 5787 N (kết quả được làm tròn đến chữ số hàng đơn vị).","answer":false}],"explanation":"a) đúng<br>Khối lượng không khí trong chai ở thời điểm ban đầu là:<br>$p_0V=\\frac{m_0}{M}RT_0$    $m_0=\\frac{Mp_0V}{RT_0}=\\frac{29.{10}^5.1,5.{10}^{-3}}{8,31.\\left(27+273\\right)}\\approx 1,7$  g.<br>b) sai<br>Áp suất của không khí trong chai sau khi bơm thêm 3m0 (kg) không khí vào là:<br>Ta có:  $p_0V=\\frac{m_0}{M}RT_0$  và  $pV=\\frac{m_0+3m_0}{M}RT$ .<br>Suy ra:  $p=\\frac{4Tp_0}{T_0}=\\frac{4.\\left(37+273\\right).{10}^5}{27+273}=\\frac{62}{15}.{10}^5Pa\\approx 4,1.{10}^5$  Pa.<br>c) đúng<br>Khi nhiệt độ tuyệt đối (hay nhiệt độ) của không khí trong chai tăng lên, động năng tịnh tiến trung bình của các phân tử khí ( $E_đ=\\frac{3}{2}kT$ ) cũng tăng.<br>d) sai<br>Khi nhiệt độ của không khí trong chai tăng từ 27 C lên đến 37 C, lực của không khí tác dụng lên mặt nước tăng một lượng  $\\Delta F=\\Delta p.S=\\left(p-p_0\\right).S=\\left(\\frac{62}{15}.{10}^5-{10}^5\\right).0,014\\approx 4387$  N.","difficultySource":"ai"}}]},{"id":673994,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Radon là chất khí không màu, không mùi, không vị nên không thể phát hiện bằng các giác quan của con người. Đồng vị  ${}_{86}^{222}{Rn}$  là chất phóng xạ alpha có chu kì bán rã là 3,82 ngày và biến đổi thành hạt nhân con X. Radon được sinh ra từ các nguyên tố phóng xạ có trong đất đá, có thể khuếch tán vào không khí và tích tụ trong các không gian kín như nhà ở, hầm, trường học. Theo Tổ chức Y tế Thế giới (WHO), radon được xem là nguyên nhân thứ hai gây ung thư phổi sau thuốc lá.<br>Trong một khảo sát tại khu công nghiệp, người ta đo được trong 1 lít không khí có chứa 10,8.10<sup>3</sup> nguyên tử 222Rn. Biết rằng nồng độ phóng xạ an toàn của radon trong không khí khoảng 150 Bq/m3. Nồng độ phóng xạ  $\\mu_H\\left(Bq/m^3\\right)$  được xác định bằng công thức  $\\mu_H=\\frac{H}{V}.$  Trong đó, H (Bq) là độ phóng xạ; V (m3) là thể tích.","difficulty":"kho","statements":[{"text":"Độ phóng xạ của một lượng radon  ${}_{86}^{222}{Rn}$  giảm dần theo thời gian theo quy luật hàm mũ.","answer":true},{"text":"Hằng số phóng xạ của  ${}_{86}^{222}{Rn}$  xấp xỉ bằng 2,1.106 s1.","answer":true},{"text":"Hạt nhân X có 134 hạt neutron.","answer":true},{"text":"Nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát vượt mức an toàn.","answer":false}],"explanation":"a) đúng<br>Độ phóng xạ của một lượng chất phóng xạ bất kì ( $H=N=N_0e^{-t}$ ) giảm dần theo thời gian theo quy luật hàm mũ.<br>b) đúng<br>Hằng số phóng xạ của  ${}_{86}^{222}{Rn}$  là:  $=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{3,82.24.3600}\\approx 2,1.{10}^{-6}$  s1.<br>c) đúng<br>Phương trình phóng xạ:  ${}_{86}^{222}{Rn}\\rightarrow {}_2^4{He}+{}_{84}^{218}{Po}$ .<br>Hạt nhân X là  ${}_{84}^{218}{Po}$  có 218 – 84 = 134 hạt neutron.<br>d) sai<br>Nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát là:<br>$\\mu_H=\\frac{H}{V}=\\frac{N.\\ln\\left(2\\right)}{T.V}=\\frac{10,8.{10}^3.\\ln\\left(2\\right)}{3,82.24.3600.1.{10}^{-3}}\\approx 22,7$  Bq/m3 < 150 Bq/m3.<br>Vậy, nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát chưa vượt mức an toàn.","difficultySource":"ai"},"ex":[{"exam":463,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Radon là chất khí không màu, không mùi, không vị nên không thể phát hiện bằng các giác quan của con người. Đồng vị  ${}_{86}^{222}{Rn}$  là chất phóng xạ alpha có chu kì bán rã là 3,82 ngày và biến đổi thành hạt nhân con X. Radon được sinh ra từ các nguyên tố phóng xạ có trong đất đá, có thể khuếch tán vào không khí và tích tụ trong các không gian kín như nhà ở, hầm, trường học. Theo Tổ chức Y tế Thế giới (WHO), radon được xem là nguyên nhân thứ hai gây ung thư phổi sau thuốc lá.<br>Trong một khảo sát tại khu công nghiệp, người ta đo được trong 1 lít không khí có chứa 10,8.10<sup>3</sup> nguyên tử 222Rn. Biết rằng nồng độ phóng xạ an toàn của radon trong không khí khoảng 150 Bq/m3. Nồng độ phóng xạ  $\\mu_H\\left(Bq/m^3\\right)$  được xác định bằng công thức  $\\mu_H=\\frac{H}{V}.$  Trong đó, H (Bq) là độ phóng xạ; V (m3) là thể tích.","difficulty":"kho","statements":[{"text":"Độ phóng xạ của một lượng radon  ${}_{86}^{222}{Rn}$  giảm dần theo thời gian theo quy luật hàm mũ.","answer":true},{"text":"Hằng số phóng xạ của  ${}_{86}^{222}{Rn}$  xấp xỉ bằng 2,1.106 s1.","answer":true},{"text":"Hạt nhân X có 134 hạt neutron.","answer":true},{"text":"Nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát vượt mức an toàn.","answer":false}],"explanation":"a) đúng<br>Độ phóng xạ của một lượng chất phóng xạ bất kì ( $H=N=N_0e^{-t}$ ) giảm dần theo thời gian theo quy luật hàm mũ.<br>b) đúng<br>Hằng số phóng xạ của  ${}_{86}^{222}{Rn}$  là:  $=\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{3,82.24.3600}\\approx 2,1.{10}^{-6}$  s1.<br>c) đúng<br>Phương trình phóng xạ:  ${}_{86}^{222}{Rn}\\rightarrow {}_2^4{He}+{}_{84}^{218}{Po}$ .<br>Hạt nhân X là  ${}_{84}^{218}{Po}$  có 218 – 84 = 134 hạt neutron.<br>d) sai<br>Nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát là:<br>$\\mu_H=\\frac{H}{V}=\\frac{N.\\ln\\left(2\\right)}{T.V}=\\frac{10,8.{10}^3.\\ln\\left(2\\right)}{3,82.24.3600.1.{10}^{-3}}\\approx 22,7$  Bq/m3 < 150 Bq/m3.<br>Vậy, nồng độ phóng xạ của khí radon tại khu công nghiệp trên ở thời điểm khảo sát chưa vượt mức an toàn.","difficultySource":"ai"}}]},{"id":674005,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["p = 1,013.10<sup>5</sup> Pa","V = n.11,4 lít","T = 270 K","V = 22,4 m3"],"question":"Tại điều kiện tiêu chuẩn, một lượng khí có số mol n luôn có áp suất, nhiệt độ, thể tích bằng:","difficulty":"de","explanation":"Tại điều kiện tiêu chuẩn một lượng khí có số mol n luon có áp suất p = 1,013.10<sup>5</sup> Pa, nhiệt độ T = 273K, thể tích V = n.22,4 lit","difficultySource":"ai"},"ex":[{"exam":464,"idx":4,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["p = 1,013.10<sup>5</sup> Pa","V = n.11,4 lít","T = 270 K","V = 22,4 m3"],"question":"Tại điều kiện tiêu chuẩn, một lượng khí có số mol n luôn có áp suất, nhiệt độ, thể tích bằng:","difficulty":"de","explanation":"Tại điều kiện tiêu chuẩn một lượng khí có số mol n luon có áp suất p = 1,013.10<sup>5</sup> Pa, nhiệt độ T = 273K, thể tích V = n.22,4 lit","difficultySource":"ai"}}]},{"id":674006,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":0,"options":["3.10<sup>4</sup> Pa","4,1.10<sup>4</sup> Pa","2,4.10<sup>4</sup> Pa","1,2.10<sup>4</sup> Pa"],"question":"Trong một quá trình đẳng áp của một lượng khí, khối khí nhận công là 4,5.10<sup>4</sup> J làm một lượng khí có thể tích thay đổi từ 2,6 m3 đến 1,1 m3. Áp suất trong quá trình này là bao nhiêu?","difficulty":"de","explanation":"Ta có:  $A=p.\\Delta V\\Rightarrow p=\\frac{A}{\\Delta V}=\\frac{4,5.10^4}{2,6−1,1}=3.10^4\\left(Pa\\right)$","difficultySource":"ai"},"ex":[{"exam":464,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":0,"options":["3.10<sup>4</sup> Pa","4,1.10<sup>4</sup> Pa","2,4.10<sup>4</sup> Pa","1,2.10<sup>4</sup> Pa"],"question":"Trong một quá trình đẳng áp của một lượng khí, khối khí nhận công là 4,5.10<sup>4</sup> J làm một lượng khí có thể tích thay đổi từ 2,6 m3 đến 1,1 m3. Áp suất trong quá trình này là bao nhiêu?","difficulty":"de","explanation":"Ta có:  $A=p.\\Delta V\\Rightarrow p=\\frac{A}{\\Delta V}=\\frac{4,5.10^4}{2,6−1,1}=3.10^4\\left(Pa\\right)$","difficultySource":"ai"}}]},{"id":674023,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thang nhiệt độ. Nhiệt kế","answer":"15,3","question":"Amos Dolbear một nhà Vật lý người Mĩ đã tìm ra liên hệ giữa tiếng kêu của con Dế và nhiệt độ ngoài trời theo nhiệt giai Fahrenheit, tới năm 2007, tiến sĩ Peggy LeMone của NASA đã tiến hành chương trình \"The GLOBE\" nhằm nghiên cứu lý thuyết trên để có thể đưa ra một công thức khoa học cụ thể, và công thức mà tiến sĩ tìm được $t_F=\\frac{7n}{30}+40$ , trong đó n là số tiếng dế kêu trong thời gian 60 s. Nếu trong đêm bạn ngồi nghe tiếng dế kều bạn đếm được 168 lần trong thời gian 2 phút thì nhiệt độ ngoài trời sẽ khoảng bao nhiêu độ C) (Làm tròn đến chữ số thứ 1 sau dấu phẩy).","difficulty":"trung-binh","explanation":"Ta có:  $t_F=\\frac{7n}{30}+40=32+1,8.t^0C\\Rightarrow \\frac{7.\\frac{168}{2}}{30}+40=32+1,8t^0C\\Rightarrow t^0C=15,3\\left({}^0C\\right)$<br>Dùng dữ kiện sau cho câu 2 và câu 3: Trong thực tế khi chế tạo các đồ dùng để thờ cúng người ta thường chế tạo bằng đồng tại một ngôi chùa người ta muốn đúc một chiếc chuông đồng 1000 kg. Biết nhiệt độ môi trường khi đó là 350C và đồng nóng chảy ở nhiệt độ 10840C và đồng có nhiệt dung riêng c = 380 J/kg.K; nhiệt nóng chảy λ = 1,8.10<sup>5</sup> J/kg và năng suất tỏa nhiệt của than cốc là q = 30 MJ/kg và hiệu suất nấu cỡ 20%.<br>Dùng dữ kiện sau cho câu 2 và câu 3:<br>Trong thực tế khi chế tạo các đồ dùng để thờ cúng người ta thường chế tạo bằng đồng tại một ngôi chùa người ta muốn đúc một chiếc chuông đồng 1000 kg. Biết nhiệt độ môi trường khi đó là 350C và đồng nóng chảy ở nhiệt độ 10840C và đồng có nhiệt dung riêng c = 380 J/kg.K; nhiệt nóng chảy λ = 1,8.10<sup>5</sup> J/kg và năng suất tỏa nhiệt của than cốc là q = 30 MJ/kg và hiệu suất nấu cỡ 20%.","difficultySource":"ai"},"ex":[{"exam":464,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Thang nhiệt độ. Nhiệt kế","answer":"15,3","question":"Amos Dolbear một nhà Vật lý người Mĩ đã tìm ra liên hệ giữa tiếng kêu của con Dế và nhiệt độ ngoài trời theo nhiệt giai Fahrenheit, tới năm 2007, tiến sĩ Peggy LeMone của NASA đã tiến hành chương trình \"The GLOBE\" nhằm nghiên cứu lý thuyết trên để có thể đưa ra một công thức khoa học cụ thể, và công thức mà tiến sĩ tìm được $t_F=\\frac{7n}{30}+40$ , trong đó n là số tiếng dế kêu trong thời gian 60 s. Nếu trong đêm bạn ngồi nghe tiếng dế kều bạn đếm được 168 lần trong thời gian 2 phút thì nhiệt độ ngoài trời sẽ khoảng bao nhiêu độ C) (Làm tròn đến chữ số thứ 1 sau dấu phẩy).","difficulty":"trung-binh","explanation":"Ta có:  $t_F=\\frac{7n}{30}+40=32+1,8.t^0C\\Rightarrow \\frac{7.\\frac{168}{2}}{30}+40=32+1,8t^0C\\Rightarrow t^0C=15,3\\left({}^0C\\right)$<br>Dùng dữ kiện sau cho câu 2 và câu 3: Trong thực tế khi chế tạo các đồ dùng để thờ cúng người ta thường chế tạo bằng đồng tại một ngôi chùa người ta muốn đúc một chiếc chuông đồng 1000 kg. Biết nhiệt độ môi trường khi đó là 350C và đồng nóng chảy ở nhiệt độ 10840C và đồng có nhiệt dung riêng c = 380 J/kg.K; nhiệt nóng chảy λ = 1,8.10<sup>5</sup> J/kg và năng suất tỏa nhiệt của than cốc là q = 30 MJ/kg và hiệu suất nấu cỡ 20%.<br>Dùng dữ kiện sau cho câu 2 và câu 3:<br>Trong thực tế khi chế tạo các đồ dùng để thờ cúng người ta thường chế tạo bằng đồng tại một ngôi chùa người ta muốn đúc một chiếc chuông đồng 1000 kg. Biết nhiệt độ môi trường khi đó là 350C và đồng nóng chảy ở nhiệt độ 10840C và đồng có nhiệt dung riêng c = 380 J/kg.K; nhiệt nóng chảy λ = 1,8.10<sup>5</sup> J/kg và năng suất tỏa nhiệt của than cốc là q = 30 MJ/kg và hiệu suất nấu cỡ 20%.","difficultySource":"ai"}}]},{"id":674033,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":3,"options":["1020 kJ","108,3 kJ","102 kJ","1083 kJ"],"question":"Cho biết nhiệt dung riêng của nước đá là 2100 J/kg.K và nhiệt nóng chảy riêng của nước đá 3, 4.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của nước đá là 0∘C. Nhiệt lượng cần cung cấp cho 3 kg nước đá ở −10∘C chuyển thành nước ở 0∘C là","difficulty":"trung-binh","explanation":"Công thức: đun nước đá từ −10°C lên 0°C rồi làm tan chảy hoàn toàn: Q = mcΔt + mλ.<br>Thay số: Q = 3.2100.10 + 3.3,4.10^5 = 63000 + 1020000 = 1083000 J.","difficultySource":"ai"},"ex":[{"exam":465,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":3,"options":["1020 kJ","108,3 kJ","102 kJ","1083 kJ"],"question":"Cho biết nhiệt dung riêng của nước đá là 2100 J/kg.K và nhiệt nóng chảy riêng của nước đá 3, 4.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của nước đá là 0∘C. Nhiệt lượng cần cung cấp cho 3 kg nước đá ở −10∘C chuyển thành nước ở 0∘C là","difficulty":"trung-binh","explanation":"Công thức: đun nước đá từ −10°C lên 0°C rồi làm tan chảy hoàn toàn: Q = mcΔt + mλ.<br>Thay số: Q = 3.2100.10 + 3.3,4.10^5 = 63000 + 1020000 = 1083000 J.","difficultySource":"ai"}}]},{"id":674046,"nq":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047326440-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 0∘C đến khi tan chảy hết thành nước và hóa hơi ở 100∘C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lẩy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg. K, nhiệt hóa hơi riêng của nước là 2, 3.10<sup>6</sup> J/kg, bỏ qua nhiệt dung của nhiệt lượng kế.","difficulty":"kho","statements":[{"text":"Trong đoạn OA trên đồ thị, khối nước đá nhận nhiệt lượng để thực hiện quá trình nóng chảy.","answer":true},{"text":"Khối lượng khối nước đá ban đầu là 100 g.","answer":true},{"text":"Tại điểm A trên đồ thị, nước đá đã hoàn toàn chuyển sang thể lỏng.","answer":true},{"text":"Tại điểm C trên đồ thị, lượng nước đã hóa hơi là 52,6 g.","answer":false}],"explanation":"a) Đúng — đoạn OA ứng với đoạn nằm ngang (t = 0°C không đổi) trên đồ thị, là quá trình nóng chảy của nước đá.<br>b) Đúng — Công thức: Q(OA) = mλ; Q(AB) = mcΔt với Δt = 100°C. Từ đồ thị Q(A)=Q(B)−Q(AB); thử m=0,1 kg: Q(AB)=0,1.4200.100=42000 J, Q(OA)=mλ=0,1.3,3.10^5=33000 J, tổng 75000 J = 75 kJ đúng bằng điểm B trên đồ thị.<br>c) Đúng — tại A, nước đá vừa nóng chảy hết nên toàn bộ đã chuyển sang thể lỏng (ở 0°C).<br>d) Sai — Công thức: khối lượng hóa hơi từ B đến C: Δm = (Q(C)−Q(B))/L. Thay số: Δm = (121−75).10^3/(2,3.10^6) = 46000/2300000 ≈ 0,02 kg = 20 g, không phải 52,6 g.","difficultySource":"ai"},"ex":[{"exam":465,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047326440-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 0∘C đến khi tan chảy hết thành nước và hóa hơi ở 100∘C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lẩy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg. K, nhiệt hóa hơi riêng của nước là 2, 3.10<sup>6</sup> J/kg, bỏ qua nhiệt dung của nhiệt lượng kế.","difficulty":"kho","statements":[{"text":"Trong đoạn OA trên đồ thị, khối nước đá nhận nhiệt lượng để thực hiện quá trình nóng chảy.","answer":true},{"text":"Khối lượng khối nước đá ban đầu là 100 g.","answer":true},{"text":"Tại điểm A trên đồ thị, nước đá đã hoàn toàn chuyển sang thể lỏng.","answer":true},{"text":"Tại điểm C trên đồ thị, lượng nước đã hóa hơi là 52,6 g.","answer":false}],"explanation":"a) Đúng — đoạn OA ứng với đoạn nằm ngang (t = 0°C không đổi) trên đồ thị, là quá trình nóng chảy của nước đá.<br>b) Đúng — Công thức: Q(OA) = mλ; Q(AB) = mcΔt với Δt = 100°C. Từ đồ thị Q(A)=Q(B)−Q(AB); thử m=0,1 kg: Q(AB)=0,1.4200.100=42000 J, Q(OA)=mλ=0,1.3,3.10^5=33000 J, tổng 75000 J = 75 kJ đúng bằng điểm B trên đồ thị.<br>c) Đúng — tại A, nước đá vừa nóng chảy hết nên toàn bộ đã chuyển sang thể lỏng (ở 0°C).<br>d) Sai — Công thức: khối lượng hóa hơi từ B đến C: Δm = (Q(C)−Q(B))/L. Thay số: Δm = (121−75).10^3/(2,3.10^6) = 46000/2300000 ≈ 0,02 kg = 20 g, không phải 52,6 g.","difficultySource":"ai"}}]},{"id":674049,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,43","question":"Có 1,2 kg nước đang ở nhiệt độ 100∘C, sau khi cung cấp cho nó nhiệt lượng 1, 74.106 J thì còn lại bao nhiêu kg nước? Biết nhiệt hóa hơi riêng của nước ở 100∘C là 2,26. 10<sup>6</sup> J/kg. (Kểt quả lấy đến 2 chữ số sau dấu phẩy thập phân)","difficulty":"trung-binh","explanation":"Công thức: khối lượng nước hóa hơi Δm = Q/L; khối lượng còn lại m' = m − Δm.<br>Thay số: Δm = 1,74.10^6/(2,26.10^6) ≈ 0,7699 kg; m' = 1,2 − 0,7699 ≈ 0,43 kg.","difficultySource":"ai"},"ex":[{"exam":465,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,43","question":"Có 1,2 kg nước đang ở nhiệt độ 100∘C, sau khi cung cấp cho nó nhiệt lượng 1, 74.106 J thì còn lại bao nhiêu kg nước? Biết nhiệt hóa hơi riêng của nước ở 100∘C là 2,26. 10<sup>6</sup> J/kg. (Kểt quả lấy đến 2 chữ số sau dấu phẩy thập phân)","difficulty":"trung-binh","explanation":"Công thức: khối lượng nước hóa hơi Δm = Q/L; khối lượng còn lại m' = m − Δm.<br>Thay số: Δm = 1,74.10^6/(2,26.10^6) ≈ 0,7699 kg; m' = 1,2 − 0,7699 ≈ 0,43 kg.","difficultySource":"ai"}}]},{"id":674060,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["26150 kJ.","23000 kJ.","19865 kJ.","3135 kJ."],"question":"Cho biết nhiệt dung riêng của nước 4200 J/kg.K và nhiệt hóa hơi riêng của nước là 2,3. 10<sup>6</sup> J/kg.<br>Nhiệt lượng cần cung cấp cho 10 kg nước ở 25∘C chuyển thành hơi ở 100∘C là bao nhiêu?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Nước phải được đun từ $25\\,^\\circ$C lên $100\\,^\\circ$C (không đổi pha), rồi hóa hơi hoàn toàn ở $100\\,^\\circ$C, nên $Q=mc\\Delta t+mL$.</p><p class=\"text-base leading-relaxed my-2\">$Q_1=10\\cdot4200\\cdot(100-25)=3{,}15\\cdot10^6$ J; $Q_2=10\\cdot2{,}3\\cdot10^6=2{,}3\\cdot10^7$ J</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q=3{,}15\\cdot10^6+2{,}3\\cdot10^7=2{,}615\\cdot10^7\\ \\text{J}=26150$ kJ</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $23000$ kJ chỉ là nhiệt hóa hơi $mL$, thiếu phần đun nóng $3150$ kJ. $19865$ kJ nhỏ hơn cả phần hóa hơi $23000$ kJ, trong khi $Q$ phải là tổng của hai phần dương. $3135$ kJ chỉ xấp xỉ phần đun nóng $3150$ kJ, thiếu hẳn phần hóa hơi.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":466,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["26150 kJ.","23000 kJ.","19865 kJ.","3135 kJ."],"question":"Cho biết nhiệt dung riêng của nước 4200 J/kg.K và nhiệt hóa hơi riêng của nước là 2,3. 10<sup>6</sup> J/kg.<br>Nhiệt lượng cần cung cấp cho 10 kg nước ở 25∘C chuyển thành hơi ở 100∘C là bao nhiêu?","difficulty":"trung-binh","explanation":"Công thức: đun nước từ 25°C lên 100°C rồi hóa hơi hoàn toàn: Q = mcΔt + mL.<br>Thay số: Q = 10.4200.(100−25) + 10.2,3.10^6 = 3150000 + 23000000 = 26150000 J = 26150 kJ.","difficultySource":"ai"}}]},{"id":674065,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["34.103 J.","0,34. 103 J.","340.105 J.","34.107 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá là 3,4. 10<sup>5</sup> J/kg. Nhiệt lượng Q cần cung cấp để làm nóng chảy 100 g nước đá ở 0∘C là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy: $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng và $m$ là khối lượng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 100\\ \\text{g} = 0{,}1\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}4 \\cdot 10^5 \\cdot 0{,}1 = 3{,}4 \\cdot 10^4\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Viết lại: $Q = 34 \\cdot 10^3\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần cung cấp là $34 \\cdot 10^3\\ \\text{J}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":466,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["34.103 J.","0,34. 103 J.","340.105 J.","34.107 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá là 3,4. 10<sup>5</sup> J/kg. Nhiệt lượng Q cần cung cấp để làm nóng chảy 100 g nước đá ở 0∘C là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy: $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng và $m$ là khối lượng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 100\\ \\text{g} = 0{,}1\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}4 \\cdot 10^5 \\cdot 0{,}1 = 3{,}4 \\cdot 10^4\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Viết lại: $Q = 34 \\cdot 10^3\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần cung cấp là $34 \\cdot 10^3\\ \\text{J}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":674075,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2300","question":"Bạn A muốn đun sôi 1,5 lít nước bằng bếp gas. Do sơ suất nên bạn quên không tắt bếp khi nước sôi. Biết nhiệt hoá hơi riêng của nước là 2,3. 10<sup>6</sup> J/kg. Tính nhiệt lượng đã làm hoá hơi 1 lít nước trong ấm do sơ suất đó theo đơn vị kJ.","difficulty":"de","explanation":"Công thức: nhiệt lượng làm hóa hơi 1 lít (1 kg) nước: Q = mL.<br>Thay số: Q = 1.2,3.10^6 = 2300000 J.","difficultySource":"ai"},"ex":[{"exam":466,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2300","question":"Bạn A muốn đun sôi 1,5 lít nước bằng bếp gas. Do sơ suất nên bạn quên không tắt bếp khi nước sôi. Biết nhiệt hoá hơi riêng của nước là 2,3. 10<sup>6</sup> J/kg. Tính nhiệt lượng đã làm hoá hơi 1 lít nước trong ấm do sơ suất đó theo đơn vị kJ.","difficulty":"de","explanation":"Công thức: nhiệt lượng làm hóa hơi 1 lít (1 kg) nước: Q = mL.<br>Thay số: Q = 1.2,3.10^6 = 2300000 J.","difficultySource":"ai"}}]},{"id":674206,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công, công suất và lực phát động (ôn tập lớp 10)","answer":1,"options":["100,6 km.","62,9 km.","45,0 km.","54,0 km."],"question":"Với 2 lít xăng, một xe máy có công suất 3,2 kW chuyển động đều với tốc độ 45 km/h sẽ đi được bao nhiêu km? Biết hiệu suất động cơ là 25%, năng suất tỏa nhiệt của xăng là 4,6.10<sup>7</sup> J/kg, khối lượng riêng của xăng là 700 kg/m3.","difficulty":"kho","explanation":"$m=VD=2.10^{−3}.700=1,4kg$<br>$Q=qm=4,6.10^7.1,4=64,4.10^6J$<br>$A=HQ=0,25.64,4.10^6=16,1.10^6J$<br>$t=\\frac{A}{P}=\\frac{16,1.10^6}{3,2.10^3}=5031,25s=\\frac{805}{576}h$<br>$s=vt=45.\\frac{805}{576}\\approx 62,9km$","difficultySource":"ai"},"ex":[{"exam":471,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công, công suất và lực phát động (ôn tập lớp 10)","answer":1,"options":["100,6 km.","62,9 km.","45,0 km.","54,0 km."],"question":"Với 2 lít xăng, một xe máy có công suất 3,2 kW chuyển động đều với tốc độ 45 km/h sẽ đi được bao nhiêu km? Biết hiệu suất động cơ là 25%, năng suất tỏa nhiệt của xăng là 4,6.10<sup>7</sup> J/kg, khối lượng riêng của xăng là 700 kg/m3.","difficulty":"kho","explanation":"$m=VD=2.10^{−3}.700=1,4kg$<br>$Q=qm=4,6.10^7.1,4=64,4.10^6J$<br>$A=HQ=0,25.64,4.10^6=16,1.10^6J$<br>$t=\\frac{A}{P}=\\frac{16,1.10^6}{3,2.10^3}=5031,25s=\\frac{805}{576}h$<br>$s=vt=45.\\frac{805}{576}\\approx 62,9km$","difficultySource":"ai"}}]},{"id":674208,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Cung cấp nhiệt lượng 1,5 J cho một khối khí trong cylinder đặt nằm ngang, chất khí nở ra đẩy piston đi một đoạn 5 cm. Biết lực ma sát giữa piston và cylinder có độ lớn là 20 N, diện tích tiết diện của piston là 1 cm2. Coi piston chuyển động thẳng đều. Bỏ qua áp suất bên ngoài cylinder.","difficulty":"trung-binh","statements":[{"text":"Công của khối khí thực hiện là 1,2 J.","answer":false},{"text":"Độ biến thiên nội năng của khối khí là 0,5 J.","answer":true},{"text":"Trong quá trình giãn nở, áp suất của chất khí là 2.10<sup>5</sup> Pa.","answer":true},{"text":"Thể tích khí trong cylinder tăng lên 5 lít.","answer":false}],"explanation":"a) sai<br>$\\left|A\\right|=Fs=20.0,05=1J$<br>b) đúng<br>$\\Delta U=Q+A=1,5−1=0,5J$<br>c) đúng<br>$p=\\frac{F}{S}=\\frac{20}{10^{−4}}=2.10^5Pa$<br>d) sai<br>$\\Delta V=S.s=1.5=5cm^3\\ne 5ℓ$","difficultySource":"ai"},"ex":[{"exam":471,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Cung cấp nhiệt lượng 1,5 J cho một khối khí trong cylinder đặt nằm ngang, chất khí nở ra đẩy piston đi một đoạn 5 cm. Biết lực ma sát giữa piston và cylinder có độ lớn là 20 N, diện tích tiết diện của piston là 1 cm2. Coi piston chuyển động thẳng đều. Bỏ qua áp suất bên ngoài cylinder.","difficulty":"trung-binh","statements":[{"text":"Công của khối khí thực hiện là 1,2 J.","answer":false},{"text":"Độ biến thiên nội năng của khối khí là 0,5 J.","answer":true},{"text":"Trong quá trình giãn nở, áp suất của chất khí là 2.10<sup>5</sup> Pa.","answer":true},{"text":"Thể tích khí trong cylinder tăng lên 5 lít.","answer":false}],"explanation":"a) sai<br>$\\left|A\\right|=Fs=20.0,05=1J$<br>b) đúng<br>$\\Delta U=Q+A=1,5−1=0,5J$<br>c) đúng<br>$p=\\frac{F}{S}=\\frac{20}{10^{−4}}=2.10^5Pa$<br>d) sai<br>$\\Delta V=S.s=1.5=5cm^3\\ne 5ℓ$","difficultySource":"ai"}}]},{"id":674242,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"118","question":"Cần cho tối thiểu bao nhiêu gam nước đá ở −100C vào 0,5 kg nước ở 200C để thu được nước ở 00C? Cho biết nhiệt dung riêng của nước đá là 2100 J/(kgK), nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg, nhiệt dung riêng của nước là 4200 J/(kgK). (làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Nước đá ở −10 °C phải nóng lên tới 0 °C rồi tan hết: Q_thu = m(c_đá·10 + λ) = m(2100·10 + 3,34.10^5) = 355 000·m.<br>Nước 0,5 kg hạ từ 20 °C xuống 0 °C tỏa ra: Q_tỏa = 0,5 · 4200 · 20 = 42 000 (J).<br>Cân bằng nhiệt: 355 000·m = 42 000 ⇒ m = 0,1183 kg = 118,3 g ≈ 118 g. Đáp số: 118.<br>$m_d\\left(c_d\\Delta t_d+\\lambda \\right)=m_nc_n\\Delta t_n\\Rightarrow m_d\\left(2100.10+3,34.10^5\\right)=0,5.4200.20\\Rightarrow m_d\\approx 0,118kg=118g$","difficultySource":"ai"},"ex":[{"exam":472,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"118","question":"Cần cho tối thiểu bao nhiêu gam nước đá ở −100C vào 0,5 kg nước ở 200C để thu được nước ở 00C? Cho biết nhiệt dung riêng của nước đá là 2100 J/(kgK), nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg, nhiệt dung riêng của nước là 4200 J/(kgK). (làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Nước đá ở −10 °C phải nóng lên tới 0 °C rồi tan hết: Q_thu = m(c_đá·10 + λ) = m(2100·10 + 3,34.10^5) = 355 000·m.<br>Nước 0,5 kg hạ từ 20 °C xuống 0 °C tỏa ra: Q_tỏa = 0,5 · 4200 · 20 = 42 000 (J).<br>Cân bằng nhiệt: 355 000·m = 42 000 ⇒ m = 0,1183 kg = 118,3 g ≈ 118 g. Đáp số: 118.<br>$m_d\\left(c_d\\Delta t_d+\\lambda \\right)=m_nc_n\\Delta t_n\\Rightarrow m_d\\left(2100.10+3,34.10^5\\right)=0,5.4200.20\\Rightarrow m_d\\approx 0,118kg=118g$","difficultySource":"ai"}}]},{"id":674244,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,4","question":"Một hỗn hợp gồm 10 kg nước lỏng và m kg nước đá đều ở nhiệt độ cân bằng 00C. Người ta cung cấp nhiệt lượng cho hỗn hợp trong 1 h và đo được:<br>+ 50 phút đầu: nhiệt độ hỗn hợp không đổi (vẫn 00C).<br>+ 10 phút cuối: nhiệt độ hỗn hợp tăng đều thêm 20C.<br>Cho rằng: Công suất của nguồn nhiệt không đổi, toàn bộ nhiệt lượng chỉ truyền cho hỗn hợp, nhiệt nóng chảy riêng của nước đá và nhiệt dung riêng của nước lần lượt là λ = 3,33 × 10<sup>5</sup> Jkg−1; c = 4186 Jkg−1K−1. Giá trị của m là bao nhiêu? (Kết quả Làm tròn đến chữ số hàng phần chục).","difficulty":"kho","explanation":"Công suất nguồn không đổi ⇒ nhiệt lượng tỉ lệ với thời gian: Q_50/Q_10 = 50/10 = 5.<br>50 phút đầu nhiệt độ không đổi: toàn bộ nhiệt dùng làm tan m kg nước đá: Q_50 = m·λ = 3,4.10^5·m.<br>10 phút cuối, cả (10 + m) kg nước nóng thêm 2 °C: Q_10 = (10 + m)·4200·2 = 8400(10 + m).<br>Suy ra 3,4.10^5·m = 5 · 8400(10 + m) = 42 000(10 + m) ⇒ 298 000·m = 420 000 ⇒ m = 1,41 kg ≈ 1,4. Đáp số: 1,4.<br>$\\left\\{\\begin{aligned}Pt_1=m\\lambda <br>Pt_2=\\left(m_n+m\\right)c\\Delta t\\end{aligned}\\right.\\Rightarrow \\frac{t_1}{t_2}=\\frac{m\\lambda }{\\left(m_n+m\\right)c\\Delta t}\\Rightarrow \\frac{50}{10}=\\frac{m.3,33.10^5}{\\left(10+m\\right).4186.2}\\Rightarrow m\\approx 1,44kg$","difficultySource":"ai"},"ex":[{"exam":472,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,4","question":"Một hỗn hợp gồm 10 kg nước lỏng và m kg nước đá đều ở nhiệt độ cân bằng 00C. Người ta cung cấp nhiệt lượng cho hỗn hợp trong 1 h và đo được:<br>+ 50 phút đầu: nhiệt độ hỗn hợp không đổi (vẫn 00C).<br>+ 10 phút cuối: nhiệt độ hỗn hợp tăng đều thêm 20C.<br>Cho rằng: Công suất của nguồn nhiệt không đổi, toàn bộ nhiệt lượng chỉ truyền cho hỗn hợp, nhiệt nóng chảy riêng của nước đá và nhiệt dung riêng của nước lần lượt là λ = 3,33 × 10<sup>5</sup> Jkg−1; c = 4186 Jkg−1K−1. Giá trị của m là bao nhiêu? (Kết quả Làm tròn đến chữ số hàng phần chục).","difficulty":"kho","explanation":"Công suất nguồn không đổi ⇒ nhiệt lượng tỉ lệ với thời gian: Q_50/Q_10 = 50/10 = 5.<br>50 phút đầu nhiệt độ không đổi: toàn bộ nhiệt dùng làm tan m kg nước đá: Q_50 = m·λ = 3,4.10^5·m.<br>10 phút cuối, cả (10 + m) kg nước nóng thêm 2 °C: Q_10 = (10 + m)·4200·2 = 8400(10 + m).<br>Suy ra 3,4.10^5·m = 5 · 8400(10 + m) = 42 000(10 + m) ⇒ 298 000·m = 420 000 ⇒ m = 1,41 kg ≈ 1,4. Đáp số: 1,4.<br>$\\left\\{\\begin{aligned}Pt_1=m\\lambda <br>Pt_2=\\left(m_n+m\\right)c\\Delta t\\end{aligned}\\right.\\Rightarrow \\frac{t_1}{t_2}=\\frac{m\\lambda }{\\left(m_n+m\\right)c\\Delta t}\\Rightarrow \\frac{50}{10}=\\frac{m.3,33.10^5}{\\left(10+m\\right).4186.2}\\Rightarrow m\\approx 1,44kg$","difficultySource":"ai"}}]},{"id":674261,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh sử dụng bộ dụng cụ như hình vẽ để khảo sát mối quan hệ giữa áp suất và thể tích của một khối khí xác định. Hình vẽ mô tả một ống thủy tinh cố định đặt thẳng đứng, diện tích tiết diện của ống là 7, 5.10<sup>−5</sup> m2 chứa một cột không khí xem là khí lí tưởng bị nhốt bởi dầu. Dầu trong ống được nối với một bình chứa dầu và một áp kế. Một cái bơm tay được nối với hệ thống để tăng áp suất. Khi áp suất của khối khí bị nhốt tăng lên, chiều dài của cột khí bị nhốt giảm xuống. Học sinh thu thập dữ liệu và ghi vào bảng sau.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399225-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Để kiểm chứng định luật Boyle cần phải giữ nhiệt độ khối khí trong ống thuỷ tinh không đổi.","answer":true},{"text":"Đối với khối khí bị nhốt trong ống thuỷ tinh thì áp suất p tỉ lệ nghịch với thể tích V.","answer":true},{"text":"Tích của áp suất và thể tích của khối khí là hằng số và hằng số đó bằng 45.103 Pam3.","answer":false},{"text":"Khi chiều dài cột khí trong ống thuỷ tinh có chiều dài là 20 cm thì áp suất của khí là 225 kPa.","answer":true}],"explanation":"a) đúng<br>Để kiểm chứng định luật Boyle cần phải T không đổi<br>b) đúng<br>Các lần đo đều có:  $pV=pℓS=100.10^3.45.10^{−2}.7,5.10^{−5}=3,375Pam^3$<br>c) sai<br>Tính ở trên<br>d) đúng<br>$pℓS=3,375\\Rightarrow p.0,2.7,5.10^{−5}=3,375\\Rightarrow p=225.10^3Pa=225kPa$","difficultySource":"ai"},"ex":[{"exam":473,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh sử dụng bộ dụng cụ như hình vẽ để khảo sát mối quan hệ giữa áp suất và thể tích của một khối khí xác định. Hình vẽ mô tả một ống thủy tinh cố định đặt thẳng đứng, diện tích tiết diện của ống là 7, 5.10<sup>−5</sup> m2 chứa một cột không khí xem là khí lí tưởng bị nhốt bởi dầu. Dầu trong ống được nối với một bình chứa dầu và một áp kế. Một cái bơm tay được nối với hệ thống để tăng áp suất. Khi áp suất của khối khí bị nhốt tăng lên, chiều dài của cột khí bị nhốt giảm xuống. Học sinh thu thập dữ liệu và ghi vào bảng sau.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399225-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Để kiểm chứng định luật Boyle cần phải giữ nhiệt độ khối khí trong ống thuỷ tinh không đổi.","answer":true},{"text":"Đối với khối khí bị nhốt trong ống thuỷ tinh thì áp suất p tỉ lệ nghịch với thể tích V.","answer":true},{"text":"Tích của áp suất và thể tích của khối khí là hằng số và hằng số đó bằng 45.103 Pam3.","answer":false},{"text":"Khi chiều dài cột khí trong ống thuỷ tinh có chiều dài là 20 cm thì áp suất của khí là 225 kPa.","answer":true}],"explanation":"a) đúng<br>Để kiểm chứng định luật Boyle cần phải T không đổi<br>b) đúng<br>Các lần đo đều có:  $pV=pℓS=100.10^3.45.10^{−2}.7,5.10^{−5}=3,375Pam^3$<br>c) sai<br>Tính ở trên<br>d) đúng<br>$pℓS=3,375\\Rightarrow p.0,2.7,5.10^{−5}=3,375\\Rightarrow p=225.10^3Pa=225kPa$","difficultySource":"ai"}}]},{"id":674264,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh tiến hành thí nghiệm xác định nhiệt nóng chảy riêng của nước đá bằng nhiệt lượng kế có dây nung với công suất P = 24 W, cùng với cân điện tử và cốc hứng nước. Sơ đồ thí nghiệm như hình bên.<br>Bước 1: Cho nước đá vào nhiệt lượng kế, khi nước đá bắt đầu tan chảy cho nước chảy vào cốc trên cân trong thời gian t phút, xác định được khối lượng m của nước trong cốc này.<br>Bước 2: Đổ hết nước trong cốc, bật biến áp nguồn để nung nóng lượng nước đá, cho nước chảy vào cốc trong thời gian t phút, xác định được khối lượng M của nước trong cốc này. Bước 2 được tiến hành ngay sau bước 1, xem dây nung không toả nhiệt ra môi trường, bỏ qua bay hơi và ngưng tụ của nước.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399732-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở bước 1, nước đá tan do nhận nhiệt lượng từ môi trường.","answer":true},{"text":"Ở bước 2, nước đá tan và chảy vào cốc do nhận nhiệt lượng từ dây nung.","answer":false},{"text":"Ở bước 2, nếu bật nguồn trong thời gian 2t phút thì lượng nước đá do dây nung làm tan chảy là 2(M − 2m).","answer":false},{"text":"Nếu t = 2 phút, m = 2 g và M = 10 g thì nhiệt nóng chảy riêng của nước đá mà học sinh này đo được là 3, 6.10<sup>5</sup> J/kg.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Ở bước 1 chỉ có nhiệt từ môi trường làm tan đá: trong thời gian $t$ thu được khối lượng nước $m$. Ở bước 2 đá nhận nhiệt từ cả môi trường và dây nung: cùng thời gian $t$ thu được $M$.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. Bước 1 chưa bật nguồn nên đá chỉ tan nhờ nhiệt lượng nhận từ môi trường.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. Ở bước 2 đá tan do nhận nhiệt từ cả dây nung lẫn môi trường (môi trường vẫn làm tan lượng $m$ như bước 1), không phải chỉ do dây nung.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Trong $2t$ phút tổng nước thu được là $2M$, môi trường làm tan $2m$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Phần do dây nung làm tan là $2M-2m=2(M-m)$, không phải $2(M-2m)$.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Khối lượng đá do dây nung làm tan: $M-m=10-2=8$ g $=0{,}008$ kg; nhiệt lượng dây nung toả ra $Q=Pt=24\\cdot120=2880$ J.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda=\\dfrac{Q}{M-m}=\\dfrac{2880}{0{,}008}=3{,}6\\cdot10^5$ J/kg.</p>","difficultySource":"ai"},"ex":[{"exam":473,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh tiến hành thí nghiệm xác định nhiệt nóng chảy riêng của nước đá bằng nhiệt lượng kế có dây nung với công suất P = 24 W, cùng với cân điện tử và cốc hứng nước. Sơ đồ thí nghiệm như hình bên.<br>Bước 1: Cho nước đá vào nhiệt lượng kế, khi nước đá bắt đầu tan chảy cho nước chảy vào cốc trên cân trong thời gian t phút, xác định được khối lượng m của nước trong cốc này.<br>Bước 2: Đổ hết nước trong cốc, bật biến áp nguồn để nung nóng lượng nước đá, cho nước chảy vào cốc trong thời gian t phút, xác định được khối lượng M của nước trong cốc này. Bước 2 được tiến hành ngay sau bước 1, xem dây nung không toả nhiệt ra môi trường, bỏ qua bay hơi và ngưng tụ của nước.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399732-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở bước 1, nước đá tan do nhận nhiệt lượng từ môi trường.","answer":true},{"text":"Ở bước 2, nước đá tan và chảy vào cốc do nhận nhiệt lượng từ dây nung.","answer":false},{"text":"Ở bước 2, nếu bật nguồn trong thời gian 2t phút thì lượng nước đá do dây nung làm tan chảy là 2(M − 2m).","answer":false},{"text":"Nếu t = 2 phút, m = 2 g và M = 10 g thì nhiệt nóng chảy riêng của nước đá mà học sinh này đo được là 3, 6.10<sup>5</sup> J/kg.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":674267,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"0,12","question":"Biết nhiệt dung riêng của nước là 4190 J/(kg. K) và nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg. Cần cung cấp một nhiệt lượng bằng bao nhiêu MJ để làm cho 200 gam nước có nhiệt độ 100C sôi ở 1000C và 10% khối lượng của nó đã hóa hơi khi sôi (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+0,1mL=0,2.4190.\\left(100−10\\right)+0,1.0,2.2,26.10^6=120620\\left(J\\right)\\approx 0,12\\left(MJ\\right)$","difficultySource":"ai"},"ex":[{"exam":473,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"0,12","question":"Biết nhiệt dung riêng của nước là 4190 J/(kg. K) và nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg. Cần cung cấp một nhiệt lượng bằng bao nhiêu MJ để làm cho 200 gam nước có nhiệt độ 100C sôi ở 1000C và 10% khối lượng của nó đã hóa hơi khi sôi (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+0,1mL=0,2.4190.\\left(100−10\\right)+0,1.0,2.2,26.10^6=120620\\left(J\\right)\\approx 0,12\\left(MJ\\right)$","difficultySource":"ai"}}]},{"id":674269,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"0,77","question":"Cho 200 g nước đá ở −100C vào một cốc cách nhiệt đựng nước ở 300C. Sự thay đổi nhiệt độ của nước đá và nước trong cốc theo thời gian được biểu diễn theo đồ thị hình bên. Biết nhiệt dung riêng của nước đá là 2100 J/(kg. K), nhiệt nóng chảy riêng của nước đá là 3, 4.10<sup>5</sup> J/kg, nhiệt dung riêng của nước là 4200 J/(kg. K), bỏ qua nhiệt dung của cốc. Khối lượng nước trong cốc bằng bao nhiêu kilogam (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399893-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ đồ thị: nhiệt độ cân bằng cuối cùng là $6\\ ^\\circ\\text{C}$, nước đá đã tan hết. Nước trong cốc toả nhiệt hạ từ $30\\ ^\\circ\\text{C}$ xuống $6\\ ^\\circ\\text{C}$; đá thu nhiệt để nóng lên đến $0\\ ^\\circ\\text{C}$, nóng chảy, rồi nóng lên đến $6\\ ^\\circ\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Nhiệt thu vào của đá: $Q_{thu} = 0,2 \\times 2100 \\times 10 + 0,2 \\times 3,4 \\times 10^5 + 0,2 \\times 4200 \\times 6 = 4200 + 68000 + 5040 = 77240\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Phương trình cân bằng nhiệt: $m \\times 4200 \\times (30 - 6) = 77240$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = \\dfrac{77240}{4200 \\times 24} \\approx 0,766\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến hàng phần trăm: $m \\approx 0,77\\ \\text{kg}$.</p>","difficultySource":"ai"},"ex":[{"exam":473,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"0,77","question":"Cho 200 g nước đá ở −100C vào một cốc cách nhiệt đựng nước ở 300C. Sự thay đổi nhiệt độ của nước đá và nước trong cốc theo thời gian được biểu diễn theo đồ thị hình bên. Biết nhiệt dung riêng của nước đá là 2100 J/(kg. K), nhiệt nóng chảy riêng của nước đá là 3, 4.10<sup>5</sup> J/kg, nhiệt dung riêng của nước là 4200 J/(kg. K), bỏ qua nhiệt dung của cốc. Khối lượng nước trong cốc bằng bao nhiêu kilogam (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047399893-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":674291,"nq":{"form":"bai_tap","type":"true_false","topic":"Tốc độ trung bình và vận tốc trung bình","question":"Trái Đất quay một vòng quanh Mặt Trời trong thời gian 365 ngày 6 giờ. Xem chuyển động này gần đúng là chuyển động tròn và khoảng cách từ Trái Đất đến Mặt Trời khoảng  $1,5.10^{11}m.$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/102/1791084576233-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Độ dịch chuyển của Trái Đất khi nó hoàn thành một vòng quanh Mặt Trời là 3π.1011 m.","answer":false},{"text":"Tốc độ trung bình của Trái Đất khi quay một vòng quanh Mặt Trời là 107,5.10<sup>3</sup>km/h.","answer":true},{"text":"Quãng đường của Trái Đất quanh Mặt Trời là 3π.108 km.","answer":true},{"text":"Vận tốc trung bình của Trái Đất khi quay một vòng quanh Mặt Trời là 0 m/s.","answer":true}],"explanation":"Bán kính R = 1,5.10¹¹ m; thời gian T = 365 ngày 6 giờ = 8766 h.<br>a) Sai: sau một vòng trở về vị trí cũ nên độ dịch chuyển bằng 0. b) Đúng: v = 2πR/T = 2π · 1,5.10⁸ km/8766 h ≈ 107,5.10³ km/h.<br>c) Đúng: s = 2πR = 2π · 1,5.10⁸ = 3π.10⁸ km. d) Đúng: độ dịch chuyển bằng 0 nên vận tốc trung bình bằng 0.","difficultySource":"ai"},"ex":[{"exam":474,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Tốc độ trung bình và vận tốc trung bình","question":"Trái Đất quay một vòng quanh Mặt Trời trong thời gian 365 ngày 6 giờ. Xem chuyển động này gần đúng là chuyển động tròn và khoảng cách từ Trái Đất đến Mặt Trời khoảng  $1,5.10^{11}m.$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/102/1791084576233-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Độ dịch chuyển của Trái Đất khi nó hoàn thành một vòng quanh Mặt Trời là 3π.1011 m.","answer":false},{"text":"Tốc độ trung bình của Trái Đất khi quay một vòng quanh Mặt Trời là 107,5.10<sup>3</sup>km/h.","answer":true},{"text":"Quãng đường của Trái Đất quanh Mặt Trời là 3π.108 km.","answer":true},{"text":"Vận tốc trung bình của Trái Đất khi quay một vòng quanh Mặt Trời là 0 m/s.","answer":true}],"explanation":"Bán kính R = 1,5.10¹¹ m; thời gian T = 365 ngày 6 giờ = 8766 h.<br>a) Sai: sau một vòng trở về vị trí cũ nên độ dịch chuyển bằng 0. b) Đúng: v = 2πR/T = 2π · 1,5.10⁸ km/8766 h ≈ 107,5.10³ km/h.<br>c) Đúng: s = 2πR = 2π · 1,5.10⁸ = 3π.10⁸ km. d) Đúng: độ dịch chuyển bằng 0 nên vận tốc trung bình bằng 0.","difficultySource":"ai"}}]},{"id":679007,"nq":{"form":"bai_tap","type":"short_answer","topic":"Từ thông qua khung dây","answer":"1,9","question":"Một cuộn dây tròn gồm 120 vòng dây có bán kính 1 cm, được dùng để đo từ trường biến đổi theo thời gian của xung điện thần kinh trong não tạo ra. Biết cảm ứng từ  $\\vec{B}$  của từ trường này vuông góc với mặt phẳng cuộn dây. Giả sử trong 0,1 s, cảm ứng từ B của từ trường này thay đổi một lượng 0,5.10<sup>−12</sup>T. Độ lớn suất điện động cảm ứng xuất hiện ở cuộn dây bằng x.10<sup>−13</sup>V. Giá trị x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$S=\\pi R^2=\\pi \\left(cm^2\\right)$<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{N.\\Delta B.S}{\\Delta t}\\right|=\\frac{120.0,5.10^{−12}.\\pi .10^{−4}}{0,1}\\approx 1,9.10^{−13}V$","difficultySource":"ai"},"ex":[{"exam":395,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Từ thông qua khung dây","answer":"1,9","question":"Một cuộn dây tròn gồm 120 vòng dây có bán kính 1 cm, được dùng để đo từ trường biến đổi theo thời gian của xung điện thần kinh trong não tạo ra. Biết cảm ứng từ  $\\vec{B}$  của từ trường này vuông góc với mặt phẳng cuộn dây. Giả sử trong 0,1 s, cảm ứng từ B của từ trường này thay đổi một lượng 0,5.10<sup>−12</sup>T. Độ lớn suất điện động cảm ứng xuất hiện ở cuộn dây bằng x.10<sup>−13</sup>V. Giá trị x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$S=\\pi R^2=\\pi \\left(cm^2\\right)$<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{N.\\Delta B.S}{\\Delta t}\\right|=\\frac{120.0,5.10^{−12}.\\pi .10^{−4}}{0,1}\\approx 1,9.10^{−13}V$","difficultySource":"ai"}}]},{"id":680907,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["8 $m/s^2$.","0,8 $m/s^2$.","80 $m/s^2$.","800 $m/s^2$."],"question":"Một tên lửa khối lượng 5 tấn. Tại một thời điểm cụ thể, lực tác dụng lên tên lửa là 4.10<sup>5</sup> N thì gia tốc thu được là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Newton: gia tốc của vật tỉ lệ thuận với lực tác dụng và tỉ lệ nghịch với khối lượng của vật, $a = \\dfrac{F}{m}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 5$ tấn $= 5\\,000$ kg.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc của tên lửa: $a = \\dfrac{F}{m} = \\dfrac{4\\cdot 10^{5}}{5\\,000} = 80\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc của tên lửa là $80$ m/s², đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":518,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["8 m/s2.","0,8 m/s2.","80 m/s2.","800 m/s2."],"question":"Một tên lửa khối lượng 5 tấn. Tại một thời điểm cụ thể, lực tác dụng lên tên lửa là 4.10<sup>5</sup> N thì gia tốc thu được là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Newton: gia tốc của vật tỉ lệ thuận với lực tác dụng và tỉ lệ nghịch với khối lượng của vật, $a = \\dfrac{F}{m}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 5$ tấn $= 5\\,000$ kg.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc của tên lửa: $a = \\dfrac{F}{m} = \\dfrac{4\\cdot 10^{5}}{5\\,000} = 80\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc của tên lửa là $80$ m/s², đáp án C.</p>","difficultySource":"ai"}}]},{"id":681346,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực đẩy Archimedes và điều kiện nổi","answer":"0,31","question":"Một miếng sắt thể tích 4.10<sup>−5</sup> m3 được nhúng chìm trong rượu, biết khối lượng riêng của rượu là 800kg/m3. Lấy g =9,8$m/s^2$. Tính lực đẩy Archimes tác dụng lên miếng sắt theo đơn vị N. Kết quả là tròn đến 2 chữ số thập phân.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Archimedes: lực đẩy tác dụng lên vật nhúng chìm trong chất lỏng có độ lớn bằng trọng lượng của phần chất lỏng bị vật chiếm chỗ, tức $F_A = D \\cdot V \\cdot g$, trong đó $D$ là khối lượng riêng của chất lỏng (kg/m³), $V$ là thể tích phần chất lỏng bị chiếm chỗ (m³), $g$ là gia tốc trọng trường (m/s²).</p><p class=\"text-base leading-relaxed my-2\">Miếng sắt nhúng chìm hoàn toàn trong rượu nên thể tích phần rượu bị chiếm chỗ bằng thể tích miếng sắt: $V = 4\\cdot 10^{-5}\\ \\text{m}^3$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F_A = 800 \\cdot 4\\cdot 10^{-5} \\cdot 9{,}8$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_A = 0{,}032 \\cdot 9{,}8 = 0{,}3136\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến 2 chữ số thập phân: $F_A \\approx 0{,}31\\ \\text{N}$.</p>","difficultySource":"ai"},"ex":[{"exam":535,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực đẩy Archimedes và điều kiện nổi","answer":"0,31","question":"Một miếng sắt thể tích 4.10<sup>−5</sup> m3 được nhúng chìm trong rượu, biết khối lượng riêng của rượu là 800kg/m3. Lấy g =9,8m/s2. Tính lực đẩy Archimes tác dụng lên miếng sắt theo đơn vị N. Kết quả là tròn đến 2 chữ số thập phân.","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":681670,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Công suất","answer":2,"options":["2.540.000W.","2540.109 W.","2540.106 W.","2540.10<sup>−3</sup> W."],"question":"Nhà máy nhiệt điện Phú Mỹ là một tổ hợp gồm 4 nhà máy nhiệt điện do Công ty Nhiệt điện Phú Mỹ quản lý với tổng công suất 2540 MW. Đổi công suất này sang đơn vị W có giá trị bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị công suất: $1\\,\\text{MW} = 10^6\\,\\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 2540\\,\\text{MW} = 2540 \\cdot 10^6\\,\\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công suất $2540$ MW bằng $2540 \\cdot 10^6$ W, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":549,"idx":10,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Công suất","answer":2,"options":["2.540.000W.","2540.109 W.","2540.106 W.","2540.10<sup>−3</sup> W."],"question":"Nhà máy nhiệt điện Phú Mỹ là một tổ hợp gồm 4 nhà máy nhiệt điện do Công ty Nhiệt điện Phú Mỹ quản lý với tổng công suất 2540 MW. Đổi công suất này sang đơn vị W có giá trị bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị công suất: $1\\,\\text{MW} = 10^6\\,\\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 2540\\,\\text{MW} = 2540 \\cdot 10^6\\,\\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công suất $2540$ MW bằng $2540 \\cdot 10^6$ W, đáp án C.</p>","difficultySource":"ai"}}]},{"id":681915,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":"0,08","question":"Một toa tàu có khối lượng 80 tấn chuyển động thẳng với vận tốc không đổi dưới tác dụng của lực kéo nằm ngang có độ lớn F = 6.10<sup>4</sup> N. Lấy g = 10 $m/s^2$. Hệ số ma sát giữa tàu và đường ray là bao nhiêu? (Làm tròn đến hai chữ số thập phân)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Tàu chuyển động thẳng đều nên hợp lực tác dụng lên tàu bằng 0 (định luật I Newton). Chọn chiều dương là chiều chuyển động của tàu.</p><p class=\"text-base leading-relaxed my-2\">Theo phương thẳng đứng: phản lực $N$ cân bằng với trọng lực $P$, nên $N = P = mg$.</p><p class=\"text-base leading-relaxed my-2\">Theo phương ngang: lực kéo $F$ cân bằng với lực ma sát trượt $F_{ms}$, nên $F = F_{ms} = \\mu N$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 80\\ \\text{tấn} = 8.10^4\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng của tàu: $N = mg = 8.10^4 \\cdot 10 = 8.10^5\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Hệ số ma sát: $\\mu = \\dfrac{F}{N} = \\dfrac{6.10^4}{8.10^5} = 0{,}075$.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến hai chữ số thập phân: $\\mu \\approx 0{,}08$.</p>","difficultySource":"ai"},"ex":[{"exam":559,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực ma sát nghỉ, ma sát trượt và hệ số ma sát","answer":"0,08","question":"Một toa tàu có khối lượng 80 tấn chuyển động thẳng với vận tốc không đổi dưới tác dụng của lực kéo nằm ngang có độ lớn F = 6.10<sup>4</sup> N. Lấy g = 10 m/s2. Hệ số ma sát giữa tàu và đường ray là bao nhiêu? (Làm tròn đến hai chữ số thập phân)","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":682360,"nq":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm động lượng, xung lượng của lực","answer":"6440","question":"Một quả bóng golf có khối lượng 46 g đang nằm yên, sau một cú đánh quả bóng bay lên với tốc độ 70 m/s. Biết thời gian gậy tiếp xúc với quả bóng là 0,5.10<sup>−3</sup> s. độ lớn trung bình của lực tác dụng vào quả bóng bao nhiêu N ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định lí động lượng (định luật II Newton dạng xung lượng): lực trung bình tác dụng lên vật bằng độ biến thiên động lượng chia cho thời gian tác dụng.</p><p class=\"text-base leading-relaxed my-2\">$\\bar{F}\\,\\Delta t = m\\Delta v = m(v_2 - v_1)$</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều bóng bay lên. Ban đầu bóng nằm yên nên $v_1 = 0$, sau cú đánh $v_2 = 70$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\bar{F} = \\dfrac{m\\,v_2}{\\Delta t}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 46\\text{ g} = 0{,}046\\text{ kg}$, $\\Delta t = 0{,}5\\cdot 10^{-3}\\text{ s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\bar{F} = \\dfrac{0{,}046 \\cdot 70}{0{,}5\\cdot 10^{-3}} = \\dfrac{3{,}22}{0{,}5\\cdot 10^{-3}} = 6440\\text{ N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn trung bình của lực tác dụng vào quả bóng là $6440$ N.</p>","difficultySource":"ai"},"ex":[{"exam":581,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm động lượng, xung lượng của lực","answer":"6440","question":"Một quả bóng golf có khối lượng 46 g đang nằm yên, sau một cú đánh quả bóng bay lên với tốc độ 70 m/s. Biết thời gian gậy tiếp xúc với quả bóng là 0,5.10<sup>−3</sup> s. độ lớn trung bình của lực tác dụng vào quả bóng bao nhiêu N ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định lí động lượng (định luật II Newton dạng xung lượng): lực trung bình tác dụng lên vật bằng độ biến thiên động lượng chia cho thời gian tác dụng.</p><p class=\"text-base leading-relaxed my-2\">$\\bar{F}\\,\\Delta t = m\\Delta v = m(v_2 - v_1)$</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều bóng bay lên. Ban đầu bóng nằm yên nên $v_1 = 0$, sau cú đánh $v_2 = 70$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\bar{F} = \\dfrac{m\\,v_2}{\\Delta t}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 46\\text{ g} = 0{,}046\\text{ kg}$, $\\Delta t = 0{,}5\\cdot 10^{-3}\\text{ s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\bar{F} = \\dfrac{0{,}046 \\cdot 70}{0{,}5\\cdot 10^{-3}} = \\dfrac{3{,}22}{0{,}5\\cdot 10^{-3}} = 6440\\text{ N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn trung bình của lực tác dụng vào quả bóng là $6440$ N.</p>","difficultySource":"ai"}}]},{"id":682513,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực và trường hợp lực xiên góc","answer":"2","question":"Một tàu thuỷ chạy trên sông theo đường thẳng kéo sà lan chở hàng với lực không đổi 5.10<sup>3</sup>N. Hỏi khi lực thực hiện được công 107J thì sà lan đã dời chỗ theo phương của lực được quãng đường là bao nhiêu kilomet?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi khi vật dời chỗ theo phương của lực: $A = F \\cdot s$, trong đó $F$ là độ lớn lực (N), $s$ là quãng đường (m), $A$ là công (J).</p><p class=\"text-base leading-relaxed my-2\">Suy ra quãng đường: $s = \\dfrac{A}{F}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow s = \\dfrac{10^7}{5\\cdot 10^3} = 2\\cdot 10^3\\ \\text{m} = 2\\ \\text{km}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: sà lan dời chỗ được quãng đường $2$ km.</p>","difficultySource":"ai"},"ex":[{"exam":589,"idx":11,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực và trường hợp lực xiên góc","answer":"2","question":"Một tàu thuỷ chạy trên sông theo đường thẳng kéo sà lan chở hàng với lực không đổi 5.10<sup>3</sup>N. Hỏi khi lực thực hiện được công 107J thì sà lan đã dời chỗ theo phương của lực được quãng đường là bao nhiêu kilomet?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực không đổi khi vật dời chỗ theo phương của lực: $A = F \\cdot s$, trong đó $F$ là độ lớn lực (N), $s$ là quãng đường (m), $A$ là công (J).</p><p class=\"text-base leading-relaxed my-2\">Suy ra quãng đường: $s = \\dfrac{A}{F}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow s = \\dfrac{10^7}{5\\cdot 10^3} = 2\\cdot 10^3\\ \\text{m} = 2\\ \\text{km}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: sà lan dời chỗ được quãng đường $2$ km.</p>","difficultySource":"ai"}}]},{"id":683151,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật 2 Newton — bài toán động lực học","answer":"6405","question":"Một ô tô có các thông số gồm:<br>Khối lượng ô tô (kg)\tTải trọng (kg)\tTốc độ tối ưu (km/h)<br>2,1.10<sup>3</sup>\t950\t75,6<br>Khi ô tô chở đủ tải trọng, nó có thể tăng tốc từ trạng thái nghỉ đến tốc độ tối ưu trong 10 giây. Tính độ lớn của hợp lực tác dụng lên ô tô khi tăng tốc.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật II Newton: hợp lực tác dụng lên vật bằng khối lượng nhân gia tốc, $\\vec{F}=m\\vec{a}$. Ô tô chuyển động thẳng nhanh dần đều từ trạng thái nghỉ, nên gia tốc được tính theo công thức $v=v_0+at$ với $v_0=0$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng toàn bộ khi chở đủ tải trọng: $m=m_{\\text{ô tô}}+m_{\\text{tải}}=2100+950=3050\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi tốc độ tối ưu: $v=75{,}6\\ \\text{km/h}=\\dfrac{75{,}6}{3{,}6}\\ \\text{m/s}=21\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc khi tăng tốc: $a=\\dfrac{v-v_0}{t}=\\dfrac{21-0}{10}=2{,}1\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Hợp lực: $F=ma=3050\\cdot 2{,}1=6405\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: độ lớn hợp lực tác dụng lên ô tô khi tăng tốc là $F=6405\\ \\text{N}$.</p>","difficultySource":"ai"},"ex":[{"exam":616,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật 2 Newton — bài toán động lực học","answer":"6405","question":"Một ô tô có các thông số gồm:<br>Khối lượng ô tô (kg)\tTải trọng (kg)\tTốc độ tối ưu (km/h)<br>2,1.10<sup>3</sup>\t950\t75,6<br>Khi ô tô chở đủ tải trọng, nó có thể tăng tốc từ trạng thái nghỉ đến tốc độ tối ưu trong 10 giây. Tính độ lớn của hợp lực tác dụng lên ô tô khi tăng tốc.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":683635,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật 3 Newton và lực tương tác","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/115/1791100465855-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Người ta dùng máy phát tĩnh điện để tích điện cho hai quả cầu kim loại nhỏ đặt cách nhau 10 cm trong không khí.","difficulty":"trung-binh","statements":[{"text":"Trong hệ SI, điện tích của mỗi quả cầu có đơn vị là Culông (C).","answer":true},{"text":"Nếu hai quả cầu được tích điện cùng dấu và cùng độ lớn, lực điện giữa chúng là lực hút.","answer":false},{"text":"Nếu hai quả cầu được tích điện đến cùng độ lớn bằng 5 nC, lực điện tương tác giữa hai quả cầu bằng 22,5 µN.","answer":true},{"text":"Nếu đưa hai quả cầu lại gần đến vị trí cách nhau 5 cm rồi tích điện cho mỗi quả cầu đến độ lớn 10 nC. Lực điện tương tác giữa hai quả cầu bằng 36.10<sup>−4</sup> N.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Coulomb: $F=k\\dfrac{\\left|q_1q_2\\right|}{r^2}$, $k=9\\cdot10^9$ N·m²/C².</p><p class=\"text-base leading-relaxed my-2\">a) Đơn vị điện tích trong hệ SI là culông (C). Ý a) Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Hai điện tích cùng dấu thì đẩy nhau, không hút. Ý b) Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $F=9\\cdot10^9\\cdot\\dfrac{\\left(5\\cdot10^{-9}\\right)^2}{0{,}1^2}=2{,}25\\cdot10^{-5}$ N $=22{,}5$ µN. Ý c) Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) $F=9\\cdot10^9\\cdot\\dfrac{\\left(10\\cdot10^{-9}\\right)^2}{0{,}05^2}=3{,}6\\cdot10^{-4}$ N.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Giá trị đề cho $36\\cdot10^{-4}$ N $=3{,}6\\cdot10^{-3}$ N lớn gấp 10 lần. Ý d) Sai.</p>","difficultySource":"ai"},"ex":[{"exam":638,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật 3 Newton và lực tương tác","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/115/1791100465855-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Người ta dùng máy phát tĩnh điện để tích điện cho hai quả cầu kim loại nhỏ đặt cách nhau 10 cm trong không khí.","difficulty":"trung-binh","statements":[{"text":"Trong hệ SI, điện tích của mỗi quả cầu có đơn vị là Culông (C).","answer":true},{"text":"Nếu hai quả cầu được tích điện cùng dấu và cùng độ lớn, lực điện giữa chúng là lực hút.","answer":false},{"text":"Nếu hai quả cầu được tích điện đến cùng độ lớn bằng 5 nC, lực điện tương tác giữa hai quả cầu bằng 22,5 µN.","answer":true},{"text":"Nếu đưa hai quả cầu lại gần đến vị trí cách nhau 5 cm rồi tích điện cho mỗi quả cầu đến độ lớn 10 nC. Lực điện tương tác giữa hai quả cầu bằng 36.10<sup>−4</sup> N.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":683639,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật 3 Newton và lực tương tác","answer":"192","question":"Máy lọc không khí tạo ra các chùm ion âm  ${OH}^-$ ( có điện tích -1,6.10<sup>−19</sup> C) ở nơi có điện trường trái đất bằng  $120 V/m$  hướng thẳng đứng từ trên xuống dưới. Hãy xác định lực điện của Trái Đất tác dụng lên ion âm nói trên kết quả tính ra đơn vị là 10-19 N.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích trong điện trường đều được xác định theo công thức $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q| = 1{,}6\\cdot 10^{-19}\\ \\text{C}$ và $E = 120\\ \\text{V/m}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 1{,}6\\cdot 10^{-19} \\cdot 120 = 1{,}92\\cdot 10^{-17}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 192\\cdot 10^{-19}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì ion mang điện âm nên lực điện ngược chiều với véc-tơ cường độ điện trường, tức hướng thẳng đứng từ dưới lên trên.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $192\\cdot 10^{-19}\\ \\text{N}$, hướng thẳng đứng lên trên.</p>","difficultySource":"ai"},"ex":[{"exam":638,"idx":17,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật 3 Newton và lực tương tác","answer":"192","question":"Máy lọc không khí tạo ra các chùm ion âm  ${OH}^-$ ( có điện tích -1,6.10<sup>−19</sup> C) ở nơi có điện trường trái đất bằng  $120 V/m$  hướng thẳng đứng từ trên xuống dưới. Hãy xác định lực điện của Trái Đất tác dụng lên ion âm nói trên kết quả tính ra đơn vị là 10-19 N.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích trong điện trường đều được xác định theo công thức $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q| = 1{,}6\\cdot 10^{-19}\\ \\text{C}$ và $E = 120\\ \\text{V/m}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 1{,}6\\cdot 10^{-19} \\cdot 120 = 1{,}92\\cdot 10^{-17}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 192\\cdot 10^{-19}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì ion mang điện âm nên lực điện ngược chiều với véc-tơ cường độ điện trường, tức hướng thẳng đứng từ dưới lên trên.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $192\\cdot 10^{-19}\\ \\text{N}$, hướng thẳng đứng lên trên.</p>","difficultySource":"ai"}}]},{"id":683748,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":1,"options":["322 N","6440 N","3220 N","644 N"],"question":"Một quả bóng golf có khối lượng 46 g đang nằm yên, sau một cú đánh quả bóng bay lên với tốc độ 70 m/s. Biết thời gian tác dụng lực vào quả bóng là 0,5.10<sup>−3</sup> s. Độ lớn trung bình của lực tác dụng vào quả bóng là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đề hiểu là thời gian tác dụng lực $\\Delta t=0{,}5\\cdot10^{-3}\\ \\text{s}$ (mất dấu mũ).</p><p class=\"text-base leading-relaxed my-2\">Quả bóng ban đầu đứng yên, lực tác dụng trong thời gian rất ngắn nên dùng định lí động lượng $F\\Delta t=\\Delta p=mv-0$, với $F$ là lực trung bình.</p><p class=\"text-base leading-relaxed my-2\">$\\Delta p=0{,}046\\cdot70=3{,}22\\ \\text{kg.m/s}$.</p><p class=\"text-base leading-relaxed my-2\">$F=\\dfrac{\\Delta p}{\\Delta t}=\\dfrac{3{,}22}{0{,}5\\cdot10^{-3}}=6440\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Không đúng vì: kiểm lại $322\\cdot0{,}5\\cdot10^{-3}=0{,}161\\neq3{,}22$; $3220\\cdot0{,}5\\cdot10^{-3}=1{,}61\\neq3{,}22$; $644\\cdot0{,}5\\cdot10^{-3}=0{,}322\\neq3{,}22$. Chỉ $6440\\cdot0{,}5\\cdot10^{-3}=3{,}22$ khớp với $\\Delta p$.</p><p class=\"text-base leading-relaxed my-2\">Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":644,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":1,"options":["322 N","6440 N","3220 N","644 N"],"question":"Một quả bóng golf có khối lượng 46 g đang nằm yên, sau một cú đánh quả bóng bay lên với tốc độ 70 m/s. Biết thời gian tác dụng lực vào quả bóng là 0,5.10<sup>−3</sup> s. Độ lớn trung bình của lực tác dụng vào quả bóng là","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":683789,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực hướng tâm và gia tốc hướng tâm","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/116/1791100677613-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Vinasat-1 là vệ tinh viễn thông đầu tiên của Việt Nam chuyển động trong mặt phẳng xích đạo của Trái Đất với chu kì 24 h. Biết vệ tinh cách tâm Trái Đất 42 000 km, khối lượng của vệ tinh là m = 2,7 tấn và coi vệ tinh chuyển động tròn đều.","difficulty":"kho","statements":[{"text":"Lực hướng tâm là lực hấp dẫn do Trái Đất tác dụng lên vệ tinh.","answer":true},{"text":"Vectơ vận tốc của vệ tinh hướng vào tâm quỹ đạo.","answer":false},{"text":"Tốc độ góc của vệ tinh là 7,27.10<sup>−5</sup> rad/s.","answer":true},{"text":"Lực hướng tâm tác dụng lên vệ tinh có độ lớn là 599 N.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Trái Đất với $T=24$ h $=86400$ s, bán kính quỹ đạo $r=4{,}2\\cdot10^7$ m, $m=2700$ kg.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng: lực hấp dẫn của Trái Đất đóng vai trò lực hướng tâm.</p><p class=\"text-base leading-relaxed my-2\">b) Sai: vectơ vận tốc có phương tiếp tuyến với quỹ đạo, vuông góc với bán kính chứ không hướng vào tâm.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng: $\\omega=\\dfrac{2\\pi}{T}=\\dfrac{2\\pi}{86400}\\approx7{,}27\\cdot10^{-5}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng: $F_{ht}=m\\omega^2r=2700\\cdot(7{,}27\\cdot10^{-5})^2\\cdot4{,}2\\cdot10^7\\approx599$ N.</p>","difficultySource":"ai"},"ex":[{"exam":646,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Lực hướng tâm và gia tốc hướng tâm","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/116/1791100677613-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Vinasat-1 là vệ tinh viễn thông đầu tiên của Việt Nam chuyển động trong mặt phẳng xích đạo của Trái Đất với chu kì 24 h. Biết vệ tinh cách tâm Trái Đất 42 000 km, khối lượng của vệ tinh là m = 2,7 tấn và coi vệ tinh chuyển động tròn đều.","difficulty":"kho","statements":[{"text":"Lực hướng tâm là lực hấp dẫn do Trái Đất tác dụng lên vệ tinh.","answer":true},{"text":"Vectơ vận tốc của vệ tinh hướng vào tâm quỹ đạo.","answer":false},{"text":"Tốc độ góc của vệ tinh là 7,27.10<sup>−5</sup> rad/s.","answer":true},{"text":"Lực hướng tâm tác dụng lên vệ tinh có độ lớn là 599 N.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":683990,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Lực hướng tâm trong các tình huống thực tế","answer":1,"options":["1,0.10<sup>3</sup> s","6,5.10<sup>3</sup> s","5,0.10<sup>6</sup> s","7,1.10<sup>12</sup> s"],"question":"Gia tốc rơi tự do trên bề mặt của Mặt Trăng là g = 1,6 $m/s^2$. Bán kính của Mặt Trăng là 1,7.10<sup>6</sup> m. Chu kì của vệ tinh trên quỹ đạo gần Mặt Trăng gần đúng bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Mặt Trăng ở độ cao rất nhỏ (gần bề mặt), lực hấp dẫn đóng vai trò lực hướng tâm. Khi đó gia tốc rơi tự do tại bề mặt đóng vai trò gia tốc hướng tâm: $g = \\dfrac{v^2}{R}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tốc độ vệ tinh: $v = \\sqrt{gR}$.</p><p class=\"text-base leading-relaxed my-2\">Chu kì quay: $T = \\dfrac{2\\pi R}{v} = 2\\pi\\sqrt{\\dfrac{R}{g}}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $R = 1{,}7\\cdot 10^6$ m, $g = 1{,}6$ m/s$^2$:</p><p class=\"text-base leading-relaxed my-2\">$T = 2\\pi\\sqrt{\\dfrac{1{,}7\\cdot 10^6}{1{,}6}} = 2\\pi\\sqrt{1{,}0625\\cdot 10^6} \\approx 2\\pi \\cdot 1030{,}8 \\approx 6{,}5\\cdot 10^3$ s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chu kì của vệ tinh xấp xỉ $6{,}5\\cdot 10^3$ s, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":655,"idx":19,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Lực hướng tâm trong các tình huống thực tế","answer":1,"options":["1,0.10<sup>3</sup> s","6,5.10<sup>3</sup> s","5,0.10<sup>6</sup> s","7,1.10<sup>12</sup> s"],"question":"Gia tốc rơi tự do trên bề mặt của Mặt Trăng là g = 1,6 m/s2. Bán kính của Mặt Trăng là 1,7.10<sup>6</sup> m. Chu kì của vệ tinh trên quỹ đạo gần Mặt Trăng gần đúng bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Mặt Trăng ở độ cao rất nhỏ (gần bề mặt), lực hấp dẫn đóng vai trò lực hướng tâm. Khi đó gia tốc rơi tự do tại bề mặt đóng vai trò gia tốc hướng tâm: $g = \\dfrac{v^2}{R}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tốc độ vệ tinh: $v = \\sqrt{gR}$.</p><p class=\"text-base leading-relaxed my-2\">Chu kì quay: $T = \\dfrac{2\\pi R}{v} = 2\\pi\\sqrt{\\dfrac{R}{g}}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $R = 1{,}7\\cdot 10^6$ m, $g = 1{,}6$ m/s$^2$:</p><p class=\"text-base leading-relaxed my-2\">$T = 2\\pi\\sqrt{\\dfrac{1{,}7\\cdot 10^6}{1{,}6}} = 2\\pi\\sqrt{1{,}0625\\cdot 10^6} \\approx 2\\pi \\cdot 1030{,}8 \\approx 6{,}5\\cdot 10^3$ s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chu kì của vệ tinh xấp xỉ $6{,}5\\cdot 10^3$ s, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":685025,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":1,"options":["1,25.10<sup>−3</sup> $m/s^2$.","1,25 $m/s^2$.","800 $m/s^2$.","0,80 $m/s^2$."],"question":"Vật nặng 400 g chỉ chịu tác dụng của lực 0,5 N thì gia tốc của vật là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Niu-tơn: gia tốc của vật tỉ lệ thuận với lực tổng hợp tác dụng lên vật và tỉ lệ nghịch với khối lượng của vật.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $a = \\dfrac{F}{m}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 400\\ \\text{g} = 0{,}4\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $a = \\dfrac{0{,}5}{0{,}4} = 1{,}25\\ \\text{m/s}^2$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc của vật là $1{,}25\\ \\text{m/s}^2$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":698,"idx":27,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":1,"options":["1,25.10<sup>−3</sup> m/s2.","1,25 m/s2.","800 m/s2.","0,80 m/s2."],"question":"Vật nặng 400 g chỉ chịu tác dụng của lực 0,5 N thì gia tốc của vật là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Niu-tơn: gia tốc của vật tỉ lệ thuận với lực tổng hợp tác dụng lên vật và tỉ lệ nghịch với khối lượng của vật.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $a = \\dfrac{F}{m}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khối lượng: $m = 400\\ \\text{g} = 0{,}4\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $a = \\dfrac{0{,}5}{0{,}4} = 1{,}25\\ \\text{m/s}^2$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc của vật là $1{,}25\\ \\text{m/s}^2$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":685618,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính công suất trung bình và công suất tức thời","answer":0,"options":["4,5.10<sup>5</sup> W","2,25.10<sup>6</sup> W","2.10<sup>5</sup> W","11,25.10<sup>6</sup> W"],"question":"Một ôtô khối lượng 20 tấn chuyển động chậm dần đều trên đường nằm ngang dưới tác dụng của lực ma sát, với hệ số ma sát μ = 0,3. Vận tốc đầu của ô tô là 54 km/h, sau một khoảng thì ôtô dừng. Tính công và công suất trung bình của lực ma sát trong thời gian đó.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 20\\ \\text{tấn} = 2.10^4\\ \\text{kg}$; $v_0 = 54\\ \\text{km/h} = 15\\ \\text{m/s}$; lấy $g = 10\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều chuyển động của ô tô. Trên đường nằm ngang, lực ma sát trượt có độ lớn $F_{ms} = \\mu mg$ và ngược chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn lực ma sát: $F_{ms} = \\mu mg = 0,3 \\cdot 2.10^4 \\cdot 10 = 6.10^4\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc (chậm dần đều): theo định luật II Newton, $a = \\dfrac{F_{ms}}{m} = \\mu g = 3\\ \\text{m/s}^2$ (độ lớn).</p><p class=\"text-base leading-relaxed my-2\">Quãng đường đến khi dừng: $v^2 - v_0^2 = -2as$, với $v = 0$ nên $s = \\dfrac{v_0^2}{2a} = \\dfrac{15^2}{2 \\cdot 3} = 37,5\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực ma sát: $A = F_{ms} \\cdot s \\cdot \\cos 180^\\circ = -F_{ms}\\cdot s = -6.10^4 \\cdot 37,5 = -2,25.10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Thời gian chuyển động đến khi dừng: $t = \\dfrac{v_0}{a} = \\dfrac{15}{3} = 5\\ \\text{s}$.</p><p class=\"text-base leading-relaxed my-2\">Công suất trung bình của lực ma sát: $\\mathscr{P}_{tb} = \\dfrac{|A|}{t} = \\dfrac{2,25.10^6}{5} = 4,5.10^5\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực ma sát là $-2,25.10^6\\ \\text{J}$ (âm vì lực cản), công suất trung bình là $4,5.10^5\\ \\text{W}$. Chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":722,"idx":21,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính công suất trung bình và công suất tức thời","answer":0,"options":["4,5.10<sup>5</sup> W","2,25.10<sup>6</sup> W","2.10<sup>5</sup> W","11,25.10<sup>6</sup> W"],"question":"Một ôtô khối lượng 20 tấn chuyển động chậm dần đều trên đường nằm ngang dưới tác dụng của lực ma sát, với hệ số ma sát μ = 0,3. Vận tốc đầu của ô tô là 54 km/h, sau một khoảng thì ôtô dừng. Tính công và công suất trung bình của lực ma sát trong thời gian đó.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":685831,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Công suất của động cơ, máy kéo","answer":2,"options":["khi máy bơm hoạt động bình thường, nó thực hiện được công 3,6.10<sup>6</sup> J trong thời gian 1 phút.","khi máy bơm hoạt động bình thường, nó thực hiện được công 106 J trong thời gian 1 giờ.","khi máy bơm hoạt động bình thường, nó thực hiện được công 3,6.10<sup>6</sup> J trong thời gian 1 giờ.","khi máy bơm hoạt động bình thường, nó thực hiện được công  106 J trong thời gian 1 ngày."],"question":"Một máy bơm nước trên nhãn mác có ghi 1kWh. Ý nghĩa của thông số đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đơn vị kWh là đơn vị đo công (điện năng), với $1\\,\\text{kWh} = 1\\,\\text{kW} \\cdot \\text{h}$.</p><p class=\"text-base leading-relaxed my-2\">Công thực hiện bởi máy: $A = P \\cdot t$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\,\\text{kW} = 1000\\,\\text{W}$ và $1\\,\\text{h} = 3600\\,\\text{s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 1000 \\cdot 3600 = 3{,}6 \\cdot 10^{6}\\,\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy ý nghĩa của thông số 1 kWh là: khi hoạt động bình thường, máy thực hiện được công $3{,}6 \\cdot 10^{6}\\,\\text{J}$ trong thời gian 1 giờ.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án: A sai vì trong 1 phút (thời gian khác) công không bằng $3{,}6 \\cdot 10^{6}\\,\\text{J}$; B và D sai vì $10^{6}\\,\\text{J}$ không tương ứng với 1 kWh.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>C</b>.</p>","difficultySource":"ai"},"ex":[{"exam":732,"idx":4,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Công suất của động cơ, máy kéo","answer":2,"options":["khi máy bơm hoạt động bình thường, nó thực hiện được công 3,6.10<sup>6</sup> J trong thời gian 1 phút.","khi máy bơm hoạt động bình thường, nó thực hiện được công 106 J trong thời gian 1 giờ.","khi máy bơm hoạt động bình thường, nó thực hiện được công 3,6.10<sup>6</sup> J trong thời gian 1 giờ.","khi máy bơm hoạt động bình thường, nó thực hiện được công  106 J trong thời gian 1 ngày."],"question":"Một máy bơm nước trên nhãn mác có ghi 1kWh. Ý nghĩa của thông số đó là","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":685917,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Bảo toàn cơ năng khi chỉ có trọng lực","answer":3,"options":["1,43m/s.","3,76m/s.","4,14m/s.","2,04m/s."],"question":"Một con lắc đơn có chiều dài 1m.Kéo cho dây hợp với phương thẳng đứng một góc 600 rồi thả nhẹ. Lấy g = 10$m/s^2$. Bỏ qua sức cản không khí. Vận tốc của con lắc khi dây treo hợp với phương thẳng đứng một góc 450 là<br>II – TỰ LUẬN (4đ)<br>Bài 1(2đ): <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/115/1791123445413-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Trong mùa sinh sản vào tháng 3-4 (âm lịch), cá mòi bơi dọc theo con sông Hiếu (Quảng Trị) dài 78 km trong 5 ngày để đến thượng nguồn của con sông. Trong suốt qua trình này, trung bình mỗi con cá mòi phải sinh công 9,5.10<sup>4</sup> J.<br>a) Tính công suất trung bình của cá mòi?<br>b) Tính lực trung bình của cá mòi khi bơi?<br>Bài 2(2đ): Một vật có khối lượng 200g được ném thẳng đứng lên cao với vận tốc 4m/s từ độ cao 1,6m so với mặt đất. Lấy g = 10$m/s^2$. Bỏ qua sức cản của không khí. Chọn gốc thế năng tại mặt đất.<br>a) Tính động năng, thế năng và cơ năng của hòn bi tại lúc ném vật?<br>b) Tìm độ cao cực đại mà bi đạt được? Tìm vị trí mà động năng gấp 3 lần thế năng?<br>…………………….  HẾT ……………………","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Bỏ qua sức cản nên cơ năng bảo toàn: $v = \\sqrt{2 g \\ell(\\cos\\alpha - \\cos\\alpha_0)}$ với $\\alpha_0 = 60^\\circ$, $\\alpha = 45^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$v = \\sqrt{2\\cdot10\\cdot1\\cdot(\\cos45^\\circ - \\cos60^\\circ)} = \\sqrt{20\\cdot0{,}2071}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v \\approx 2{,}04$ m/s. Chọn D.</p>","difficultySource":"ai"},"ex":[{"exam":735,"idx":20,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Bảo toàn cơ năng khi chỉ có trọng lực","answer":3,"options":["1,43m/s.","3,76m/s.","4,14m/s.","2,04m/s."],"question":"Một con lắc đơn có chiều dài 1m.Kéo cho dây hợp với phương thẳng đứng một góc 600 rồi thả nhẹ. Lấy g = 10m/s2. Bỏ qua sức cản không khí. Vận tốc của con lắc khi dây treo hợp với phương thẳng đứng một góc 450 là<br>II – TỰ LUẬN (4đ)<br>Bài 1(2đ): <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/115/1791123445413-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Trong mùa sinh sản vào tháng 3-4 (âm lịch), cá mòi bơi dọc theo con sông Hiếu (Quảng Trị) dài 78 km trong 5 ngày để đến thượng nguồn của con sông. Trong suốt qua trình này, trung bình mỗi con cá mòi phải sinh công 9,5.10<sup>4</sup> J.<br>a) Tính công suất trung bình của cá mòi?<br>b) Tính lực trung bình của cá mòi khi bơi?<br>Bài 2(2đ): Một vật có khối lượng 200g được ném thẳng đứng lên cao với vận tốc 4m/s từ độ cao 1,6m so với mặt đất. Lấy g = 10m/s2. Bỏ qua sức cản của không khí. Chọn gốc thế năng tại mặt đất.<br>a) Tính động năng, thế năng và cơ năng của hòn bi tại lúc ném vật?<br>b) Tìm độ cao cực đại mà bi đạt được? Tìm vị trí mà động năng gấp 3 lần thế năng?<br>…………………….  HẾT ……………………","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":686001,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công suất của động cơ, máy kéo","answer":0,"options":["64920W","54000W.","55560W.","32460W"],"question":"Một thang máy khối lượng 1 tấn có thế chịu tải tối đa là 800kg. Khi chuyển động thang máy còn chịu lực cản không đổi là 4. 10<sup>3</sup>N. Hỏi để đưa thang máy lên cao có tải trọng tối đa với vận tốc không đổi 3m/s thì công suất của động cơ phải bằng bao nhiêu? Lấy g = 9,8$m/s^2$","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng thang máy: $m_1 = 1\\text{ tấn} = 1000\\text{ kg}$. Tải trọng tối đa: $m_2 = 800\\text{ kg}$. Tổng khối lượng khi thang máy chở đầy tải: $m = m_1 + m_2 = 1800\\text{ kg}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng lên. Thang máy chuyển động thẳng đều nên theo định luật II Newton, hợp lực bằng 0. Lực kéo của động cơ cân bằng với trọng lực và lực cản:</p><p class=\"text-base leading-relaxed my-2\">$F = P + F_c$</p><p class=\"text-base leading-relaxed my-2\">Trọng lực: $P = mg = 1800 \\cdot 9{,}8 = 17640\\text{ N}$.</p><p class=\"text-base leading-relaxed my-2\">Lực kéo: $F = 17640 + 4\\cdot 10^3 = 21640\\text{ N}$.</p><p class=\"text-base leading-relaxed my-2\">Công suất của động cơ khi vận tốc không đổi:</p><p class=\"text-base leading-relaxed my-2\">$P_{\\text{cs}} = F \\cdot v = 21640 \\cdot 3 = 64920\\text{ W}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công suất của động cơ phải bằng $64920\\text{ W}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":738,"idx":28,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công suất của động cơ, máy kéo","answer":0,"options":["64920W","54000W.","55560W.","32460W"],"question":"Một thang máy khối lượng 1 tấn có thế chịu tải tối đa là 800kg. Khi chuyển động thang máy còn chịu lực cản không đổi là 4. 10<sup>3</sup>N. Hỏi để đưa thang máy lên cao có tải trọng tối đa với vận tốc không đổi 3m/s thì công suất của động cơ phải bằng bao nhiêu? Lấy g = 9,8m/s2","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1153502,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Dao động cưỡng bức và hiện tượng cộng hưởng","answer":3,"options":["0,28 (Hz).","F = 22,36 (Hz).","7,12.10<sup>−3</sup> (Hz).","3,56 (Hz)."],"question":"Một con lắc lò xo nằm ngang, lò xo có khối lượng không đáng kể và có độ cứng k = 100 (N/m). Vật nhỏ m có khối lượng 0,20 (kg). Tác dụng vào vật m một ngoại lực F = F0cos(2πft) với F0 không đổi còn f thay đổi được và có phương trùng với trục của lò xo. Bỏ qua sức cản tác dụng lên vật. Để biên độ dao động của vật m lớn nhất thì tần số của ngoại lực phải có giá trị gần bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Biên độ dao động cưỡng bức đạt cực đại khi xảy ra cộng hưởng, tức tần số của ngoại lực bằng tần số dao động riêng của hệ: $f = f_0$.</p><p class=\"text-base leading-relaxed my-2\">Tần số dao động riêng của con lắc lò xo: $f_0 = \\dfrac{1}{2\\pi}\\sqrt{\\dfrac{k}{m}}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $k = 100\\ \\text{N/m}$ và $m = 0{,}20\\ \\text{kg}$:</p><p class=\"text-base leading-relaxed my-2\">$f_0 = \\dfrac{1}{2\\pi}\\sqrt{\\dfrac{100}{0{,}20}} = \\dfrac{\\sqrt{500}}{2\\pi} \\approx \\dfrac{22{,}36}{6{,}283} \\approx 3{,}56\\ \\text{Hz}$</p><p class=\"text-base leading-relaxed my-2\">Vậy để biên độ dao động của vật lớn nhất, tần số của ngoại lực gần bằng $3{,}56\\ \\text{Hz}$. Đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":775,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Dao động cưỡng bức và hiện tượng cộng hưởng","answer":3,"options":["0,28 (Hz).","F = 22,36 (Hz).","7,12.10<sup>−3</sup> (Hz).","3,56 (Hz)."],"question":"Một con lắc lò xo nằm ngang, lò xo có khối lượng không đáng kể và có độ cứng k = 100 (N/m). Vật nhỏ m có khối lượng 0,20 (kg). Tác dụng vào vật m một ngoại lực F = F0cos(2πft) với F0 không đổi còn f thay đổi được và có phương trùng với trục của lò xo. Bỏ qua sức cản tác dụng lên vật. Để biên độ dao động của vật m lớn nhất thì tần số của ngoại lực phải có giá trị gần bằng","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1154032,"nq":{"form":"bai_tap","type":"true_false","topic":"Năng lượng trong dao động điều hoà","question":"Một vật nặng có khối lượng 0,4 kg, dao động điều hoà. Đồ thị vận tốc v theo thời gian t như hình dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/117/1791215854575-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Động năng cực đại của vật bằng 3,6.10<sup>−6</sup> J","answer":false},{"text":"Tại vị trí bất kì, cơ năng bằng tổng động năng và thế năng.","answer":true},{"text":"Thế năng cực đại của con lắc bằng 1,8.10<sup>−6</sup> J","answer":true},{"text":"Cứ mỗi chu kì dao động của vật, có bốn thời điểm thế năng bằng động năng.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Đồ thị: $v_{max}=0,3$ cm/s $=3\\cdot10^{-3}$ m/s.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. $W_{d,max}=\\dfrac{1}{2}mv_{max}^2=\\dfrac{1}{2}\\cdot0,4\\cdot(3\\cdot10^{-3})^2=1,8\\cdot10^{-6}$ J, không phải $3,6\\cdot10^{-6}$ J.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Cơ năng bằng tổng động năng và thế năng tại mọi thời điểm (bỏ qua ma sát).</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $W_{t,max}=W=W_{d,max}=1,8\\cdot10^{-6}$ J.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Trong một chu kì có 4 thời điểm $|x|=\\dfrac{A}{\\sqrt2}$ nên $W_t=W_d$.</p>","difficultySource":"ai"},"ex":[{"exam":777,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Năng lượng trong dao động điều hoà","question":"Một vật nặng có khối lượng 0,4 kg, dao động điều hoà. Đồ thị vận tốc v theo thời gian t như hình dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/117/1791215854575-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Động năng cực đại của vật bằng 3,6.10<sup>−6</sup> J","answer":false},{"text":"Tại vị trí bất kì, cơ năng bằng tổng động năng và thế năng.","answer":true},{"text":"Thế năng cực đại của con lắc bằng 1,8.10<sup>−6</sup> J","answer":true},{"text":"Cứ mỗi chu kì dao động của vật, có bốn thời điểm thế năng bằng động năng.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1161643,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["7,2 J.","3,6.10<sup>−4</sup> J.","3,6 J.","7,2.10<sup>−4</sup> J."],"question":"Một vật có khối lượng 50 g, dao động điều hoà với biên độ 4 cm và tần số góc 3 rad/s. Động năng cực đại của vật là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng cực đại của vật dao động điều hoà bằng cơ năng của vật: $W_{d,max} = W = \\dfrac{1}{2}m\\omega^2A^2$, trong đó $m$ là khối lượng, $\\omega$ là tần số góc và $A$ là biên độ. Khi tính theo đơn vị SI, cần đổi $m = 50\\ \\text{g} = 0{,}05\\ \\text{kg}$ và $A = 4\\ \\text{cm} = 0{,}04\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$W_{d,max} = \\dfrac{1}{2}\\cdot 0{,}05\\cdot 3^2\\cdot 0{,}04^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{d,max} = 0{,}025\\cdot 9\\cdot 0{,}0016 = 3{,}6\\cdot 10^{-4}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy động năng cực đại của vật là $3{,}6\\cdot 10^{-4}\\ \\text{J}$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":786,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["7,2 J.","3,6.10<sup>−4</sup> J.","3,6 J.","7,2.10<sup>−4</sup> J."],"question":"Một vật có khối lượng 50 g, dao động điều hoà với biên độ 4 cm và tần số góc 3 rad/s. Động năng cực đại của vật là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng cực đại của vật dao động điều hoà bằng cơ năng của vật: $W_{d,max} = W = \\dfrac{1}{2}m\\omega^2A^2$, trong đó $m$ là khối lượng, $\\omega$ là tần số góc và $A$ là biên độ. Khi tính theo đơn vị SI, cần đổi $m = 50\\ \\text{g} = 0{,}05\\ \\text{kg}$ và $A = 4\\ \\text{cm} = 0{,}04\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$W_{d,max} = \\dfrac{1}{2}\\cdot 0{,}05\\cdot 3^2\\cdot 0{,}04^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{d,max} = 0{,}025\\cdot 9\\cdot 0{,}0016 = 3{,}6\\cdot 10^{-4}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy động năng cực đại của vật là $3{,}6\\cdot 10^{-4}\\ \\text{J}$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1166991,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["5.10<sup>−3</sup> J.","2,5.10<sup>−3</sup> J.","25 J.","0,01 J."],"question":"Một vật có khối lượng m = 500 g dao động điều hoà với phương trình dao động x = 2cos10t(cm). Khi vật có li độ x = 1 cm thì thế năng của vật bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của con lắc lò xo dao động điều hoà: $W_t = \\dfrac{1}{2}m\\omega^2 x^2$, với $x$ là li độ tại thời điểm xét.</p><p class=\"text-base leading-relaxed my-2\">Từ phương trình $x = 2\\cos 10t$ (cm), suy ra biên độ $A = 2$ cm $= 0{,}02$ m và tần số góc $\\omega = 10$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng: $m = 500$ g $= 0{,}5$ kg. Li độ: $x = 1$ cm $= 0{,}01$ m.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W_t = \\dfrac{1}{2}\\cdot 0{,}5\\cdot 10^2\\cdot (0{,}01)^2 = 0{,}0025$ J $= 2{,}5\\cdot 10^{-3}$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng của vật bằng $2{,}5\\cdot 10^{-3}$ J, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":797,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["5.10<sup>−3</sup> J.","2,5.10<sup>−3</sup> J.","25 J.","0,01 J."],"question":"Một vật có khối lượng m = 500 g dao động điều hoà với phương trình dao động x = 2cos10t(cm). Khi vật có li độ x = 1 cm thì thế năng của vật bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của con lắc lò xo dao động điều hoà: $W_t = \\dfrac{1}{2}m\\omega^2 x^2$, với $x$ là li độ tại thời điểm xét.</p><p class=\"text-base leading-relaxed my-2\">Từ phương trình $x = 2\\cos 10t$ (cm), suy ra biên độ $A = 2$ cm $= 0{,}02$ m và tần số góc $\\omega = 10$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng: $m = 500$ g $= 0{,}5$ kg. Li độ: $x = 1$ cm $= 0{,}01$ m.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W_t = \\dfrac{1}{2}\\cdot 0{,}5\\cdot 10^2\\cdot (0{,}01)^2 = 0{,}0025$ J $= 2{,}5\\cdot 10^{-3}$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng của vật bằng $2{,}5\\cdot 10^{-3}$ J, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1173876,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Cân bằng của điện tích chịu nhiều lực","answer":0,"options":["104.10<sup>−5</sup> N.","74.10<sup>−5</sup> N.","52.10<sup>−5</sup> N.","26.10<sup>−5</sup> N."],"question":"Người ta treo hai quả cầu nhỏ khối lượng bằng nhau m = 0,1g bằng hai sợi dây nhẹ có độ dài ℓ như nhau trong không khí. Cho chúng nhiễm điện bằng nhau chúng đẩy nhau và cân bằng khi mỗi dây treo hợp với phương thẳng đứng một góc 150. Lấy g = 10 $m/s^2$. Tính sức căng của dây treo.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 0{,}1\\ \\text{g} = 1{,}0\\cdot10^{-4}\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Xét một quả cầu ở trạng thái cân bằng. Chịu ba lực: trọng lực $\\vec{P}$ (thẳng đứng, hướng xuống), lực điện $\\vec{F}$ (nằm ngang, do hai quả cầu đẩy nhau) và lực căng dây $\\vec{T}$ (dọc theo dây). Chọn trục Oy thẳng đứng hướng lên, Ox nằm ngang.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng: $\\vec{P} + \\vec{F} + \\vec{T} = \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Chiếu lên phương thẳng đứng: $T\\cos\\alpha = mg$, với $\\alpha = 15^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $T = \\dfrac{mg}{\\cos\\alpha}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $mg = 1{,}0\\cdot10^{-4}\\cdot10 = 1{,}0\\cdot10^{-3}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{1{,}0\\cdot10^{-3}}{\\cos15^\\circ} = \\dfrac{1{,}0\\cdot10^{-3}}{0{,}9659} \\approx 1{,}04\\cdot10^{-3}\\ \\text{N} = 104\\cdot10^{-5}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: sức căng của dây treo là $104\\cdot10^{-5}\\ \\text{N}$, chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":806,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Cân bằng của điện tích chịu nhiều lực","answer":0,"options":["104.10<sup>−5</sup> N.","74.10<sup>−5</sup> N.","52.10<sup>−5</sup> N.","26.10<sup>−5</sup> N."],"question":"Người ta treo hai quả cầu nhỏ khối lượng bằng nhau m = 0,1g bằng hai sợi dây nhẹ có độ dài ℓ như nhau trong không khí. Cho chúng nhiễm điện bằng nhau chúng đẩy nhau và cân bằng khi mỗi dây treo hợp với phương thẳng đứng một góc 150. Lấy g = 10 m/s2. Tính sức căng của dây treo.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 0{,}1\\ \\text{g} = 1{,}0\\cdot10^{-4}\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Xét một quả cầu ở trạng thái cân bằng. Chịu ba lực: trọng lực $\\vec{P}$ (thẳng đứng, hướng xuống), lực điện $\\vec{F}$ (nằm ngang, do hai quả cầu đẩy nhau) và lực căng dây $\\vec{T}$ (dọc theo dây). Chọn trục Oy thẳng đứng hướng lên, Ox nằm ngang.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng: $\\vec{P} + \\vec{F} + \\vec{T} = \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Chiếu lên phương thẳng đứng: $T\\cos\\alpha = mg$, với $\\alpha = 15^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $T = \\dfrac{mg}{\\cos\\alpha}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $mg = 1{,}0\\cdot10^{-4}\\cdot10 = 1{,}0\\cdot10^{-3}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{1{,}0\\cdot10^{-3}}{\\cos15^\\circ} = \\dfrac{1{,}0\\cdot10^{-3}}{0{,}9659} \\approx 1{,}04\\cdot10^{-3}\\ \\text{N} = 104\\cdot10^{-5}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: sức căng của dây treo là $104\\cdot10^{-5}\\ \\text{N}$, chọn đáp án A.</p>","difficultySource":"ai"}}]},{"id":1173896,"nq":{"form":"bai_tap","type":"true_false","topic":"Cân bằng của điện tích chịu nhiều lực","question":"Một quả cầu thủy tinh nhỏ có khối lượng 15 g và điện tích 10 nC được đặt cách điện trên mặt bàn (trong không khí). Theo phương thẳng đứng và ở phía trên so với quả cầu thủy tinh có treo một quả cầu sắt nhỏ tích điện –10 nC. Hai quả cầu cách nhau 1 cm. Lấy g = 10 $m/s^2$.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác điện giữa hai quả cầu là lực hút.","answer":true},{"text":"Khi hệ hai quả cầu cân bằng thì sợi dây có phương thẳng đứng.","answer":true},{"text":"Quả cầu thủy tinh thiếu 6,25.10<sup>10</sup> electron, quả cầu sắt dư 6,25.10<sup>10</sup> electron.","answer":true},{"text":"Phản lực của bàn tác dụng lên quả cầu thủy tinh có độ lớn là 0,15 N.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Dữ kiện:</strong> quả cầu thủy tinh $q_1 = +10\\ \\text{nC} = 10^{-8}\\ \\text{C}$, $m_1 = 15\\ \\text{g} = 0{,}015\\ \\text{kg}$; quả cầu sắt $q_2 = -10\\ \\text{nC}$; khoảng cách $r = 1\\ \\text{cm} = 0{,}01\\ \\text{m}$; $g = 10\\ \\text{m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\"><strong>a)</strong> Hai điện tích trái dấu nên lực tương tác điện là lực hút. Ý a) <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>b)</strong> Lực điện giữa hai quả cầu có phương nằm trên đường nối tâm, tức là phương thẳng đứng. Quả cầu sắt cân bằng dưới tác dụng của trọng lực, lực căng dây và lực điện, các lực này cùng nằm trên đường thẳng đứng nên dây phải thẳng đứng. Ý b) <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>c)</strong> Số electron tương ứng với điện tích $|q|$ là $N = \\dfrac{|q|}{e} = \\dfrac{10^{-8}}{1{,}6.10^{-19}} = 6{,}25.10^{10}$ electron. Quả cầu thủy tinh tích điện dương nên thiếu $6{,}25.10^{10}$ electron. Quả cầu sắt tích điện âm nên dư $6{,}25.10^{10}$ electron. Ý c) <strong>Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>d)</strong> Lực hút điện có độ lớn:</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2} = 9.10^9\\cdot\\dfrac{10^{-8}\\cdot 10^{-8}}{(0{,}01)^2} = 9.10^{-3}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng của quả cầu thủy tinh: $P = m_1 g = 0{,}015\\cdot 10 = 0{,}15\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Quả cầu thủy tinh nằm trên bàn, lực hút của quả cầu sắt ở phía trên hướng lên, nên phản lực của bàn:</p><p class=\"text-base leading-relaxed my-2\">$N = P - F = 0{,}15 - 0{,}009 = 0{,}141\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Ý d) nêu $0{,}15$ N là <strong>Sai</strong> (giá trị đúng là $0{,}141$ N).</p>","difficultySource":"ai"},"ex":[{"exam":806,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Cân bằng của điện tích chịu nhiều lực","question":"Một quả cầu thủy tinh nhỏ có khối lượng 15 g và điện tích 10 nC được đặt cách điện trên mặt bàn (trong không khí). Theo phương thẳng đứng và ở phía trên so với quả cầu thủy tinh có treo một quả cầu sắt nhỏ tích điện –10 nC. Hai quả cầu cách nhau 1 cm. Lấy g = 10 m/s2.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác điện giữa hai quả cầu là lực hút.","answer":true},{"text":"Khi hệ hai quả cầu cân bằng thì sợi dây có phương thẳng đứng.","answer":true},{"text":"Quả cầu thủy tinh thiếu 6,25.10<sup>10</sup> electron, quả cầu sắt dư 6,25.10<sup>10</sup> electron.","answer":true},{"text":"Phản lực của bàn tác dụng lên quả cầu thủy tinh có độ lớn là 0,15 N.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1173897,"nq":{"form":"bai_tap","type":"true_false","topic":"Nguyên lí chồng chất điện trường","question":"Trong chân không có hai điện tích điểm q1 = 16q2 = 12.10<sup>−9</sup> C đặt lần lượt tại hai điểm A và B cách nhau 24 cm. Gọi M là trung điểm của AB.","difficulty":"kho","statements":[{"text":"Vectơ cường độ điện trường do q1 gây ra tại điểm M và điểm B ngược hướng nhau.","answer":false},{"text":"Vectơ cường độ điện trường do q1 và do q2 gây ra tại điểm M ngược hướng nhau.","answer":true},{"text":"Cường độ điện trường tổng hợp tại M có độ lớn bằng 7031,25 V/m.","answer":true},{"text":"Gọi N là điểm mà tại đó cường độ điện trường tổng hợp bằng 0, thì ta có NA = 19,2 cm;<br>NB = 4,8 cm","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Từ đề: $q_1 = 16q_2 = 12\\cdot10^{-9}$ C, suy ra $q_1 = 12\\cdot10^{-9}$ C và $q_2 = 0{,}75\\cdot10^{-9}$ C. Cả hai điện tích cùng dấu (dương). $AB = 24$ cm, $M$ là trung điểm nên $AM = MB = 12$ cm.</p><p class=\"text-base leading-relaxed my-2\">Cường độ điện trường của điện tích điểm: $E = k\\dfrac{|q|}{r^2}$, với $k = 9\\cdot10^9$ N.m²/C².</p><p class=\"text-base leading-relaxed my-2\"><b>Ý a)</b> Chọn trục Ax hướng từ A đến B. Điện tích $q_1 \\gt  0$ đẩy điện trường hướng ra xa $A$, nên $\\vec{E_1}$ tại $M$ và tại $B$ đều hướng theo $+x$. Hai vectơ cùng hướng, không ngược hướng.<br>Kết luận: <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b)</b> $\\vec{E_1}$ tại $M$ hướng theo $+x$ (ra xa $A$). $\\vec{E_2}$ tại $M$ hướng theo $-x$ (ra xa $B$, vì $q_2\\gt 0$ và $M$ nằm về phía $A$ so với $B$). Hai vectơ ngược hướng.<br>Kết luận: <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c)</b> Độ lớn:</p><p class=\"text-base leading-relaxed my-2\">$E_1 = 9\\cdot10^9\\dfrac{12\\cdot10^{-9}}{(0{,}12)^2} = 7500$ V/m</p><p class=\"text-base leading-relaxed my-2\">$E_2 = 9\\cdot10^9\\dfrac{0{,}75\\cdot10^{-9}}{(0{,}12)^2} = 468{,}75$ V/m</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E_M = E_1 - E_2 = 7500 - 468{,}75 = 7031{,}25$ V/m (hướng theo $+x$).<br>Kết luận: <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d)</b> Điểm $N$ có $E = 0$ phải nằm trên đoạn $AB$ (giữa hai điện tích cùng dấu, hai vectơ cường độ ngược hướng). Đặt $NA = x$ (cm), $NB = 24 - x$. Điều kiện $E_1 = E_2$:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{q_1}{x^2} = \\dfrac{q_2}{(24-x)^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{24-x}{x} = \\sqrt{\\dfrac{q_2}{q_1}} = \\sqrt{\\dfrac{0{,}75}{12}} = 0{,}25$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 24 - x = 0{,}25x$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x = 19{,}2$ cm.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $NA = 19{,}2$ cm, $NB = 4{,}8$ cm.<br>Kết luận: <b>Đúng</b>.</p>","difficultySource":"ai"},"ex":[{"exam":806,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Nguyên lí chồng chất điện trường","question":"Trong chân không có hai điện tích điểm q1 = 16q2 = 12.10<sup>−9</sup> C đặt lần lượt tại hai điểm A và B cách nhau 24 cm. Gọi M là trung điểm của AB.","difficulty":"kho","statements":[{"text":"Vectơ cường độ điện trường do q1 gây ra tại điểm M và điểm B ngược hướng nhau.","answer":false},{"text":"Vectơ cường độ điện trường do q1 và do q2 gây ra tại điểm M ngược hướng nhau.","answer":true},{"text":"Cường độ điện trường tổng hợp tại M có độ lớn bằng 7031,25 V/m.","answer":true},{"text":"Gọi N là điểm mà tại đó cường độ điện trường tổng hợp bằng 0, thì ta có NA = 19,2 cm;<br>NB = 4,8 cm","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1173900,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"100","question":"Cho hiệu điện thế giữa hai điểm M, N trong điện trường là UMN = 50 V. Công mà lực điện tác dụng lên một điện tích q = 2.10<sup>−6</sup> C sinh ra khi nó chuyển động từ điểm M đến điểm N bằng bao nhiêu μJ ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến N được tính theo hiệu điện thế giữa hai điểm: $A_{MN} = q\\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 2\\cdot10^{-6}\\ \\text{C}$ và $U_{MN} = 50\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$A_{MN} = 2\\cdot10^{-6}\\cdot 50 = 1\\cdot10^{-4}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\cdot10^{-4}\\ \\text{J} = 100\\ \\mu\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực điện là $100\\ \\mu\\text{J}$.</p>","difficultySource":"ai"},"ex":[{"exam":806,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"100","question":"Cho hiệu điện thế giữa hai điểm M, N trong điện trường là UMN = 50 V. Công mà lực điện tác dụng lên một điện tích q = 2.10<sup>−6</sup> C sinh ra khi nó chuyển động từ điểm M đến điểm N bằng bao nhiêu μJ ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến N được tính theo hiệu điện thế giữa hai điểm: $A_{MN} = q\\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 2\\cdot10^{-6}\\ \\text{C}$ và $U_{MN} = 50\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$A_{MN} = 2\\cdot10^{-6}\\cdot 50 = 1\\cdot10^{-4}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\cdot10^{-4}\\ \\text{J} = 100\\ \\mu\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực điện là $100\\ \\mu\\text{J}$.</p>","difficultySource":"ai"}}]},{"id":1173904,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"0,06","question":"Hai điện tích điểm q1 = 2.10<sup>−7</sup> C và q2 = –2.10<sup>−7</sup> C lần lượt đặt tại A và B cách nhau 10 cm trong không khí. Giả sử q1 đặt cố định tại A, còn q2 ở B sẽ di chuyển lần lượt trên các cạnh BC và CD của hình vuông ABCD, thì lực tương tác tĩnh điện giữa hai điện tích có độ lớn nhỏ nhất là Fmin và lớn nhất là Fmax, đồng thời ta thấy có hai vị trí của q2 (tại điểm M và N) mà tại đó độ lớn lực tương tác tĩnh điện đều bằng  $\\frac{F_{min}+F_{max}}{2}$ . Tính khoảng cách MN (tính bằng mét). (Kết quả lấy đến 1 chữ số có nghĩa).<br>Tài liệu được chia sẻ bởi Website VnTeach.Com<br>https://www.vnteach.com","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Đặt $A$ tại gốc tọa độ, $AB = a = 0{,}1$ m. Lực tĩnh điện giữa hai điện tích trong không khí có độ lớn $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $r$ là khoảng cách từ $A$ đến $q_2$.</p><p class=\"text-base leading-relaxed my-2\">Khi $q_2$ di chuyển trên $BC$ và $CD$, khoảng cách $r$ nằm trong khoảng: nhỏ nhất $r_{min} = a$ (tại $B$ hoặc $D$), lớn nhất $r_{max} = a\\sqrt{2}$ (tại $C$).</p><p class=\"text-base leading-relaxed my-2\">Suy ra $F_{max} = k\\dfrac{|q_1 q_2|}{a^2}$ và $F_{min} = k\\dfrac{|q_1 q_2|}{2a^2}$.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện đề bài: $F = \\dfrac{F_{min}+F_{max}}{2}$. Vì $F \\propto 1/r^2$ nên</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{1}{r^2} = \\dfrac{1}{2}\\left(\\dfrac{1}{a^2} + \\dfrac{1}{2a^2}\\right) = \\dfrac{3}{4a^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = \\dfrac{2a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Xác định vị trí $M$ trên $BC$: $M = (a, y)$ với $a^2 + y^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y = \\dfrac{a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Xác định vị trí $N$ trên $CD$: $N = (x, a)$ với $x^2 + a^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x = \\dfrac{a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Khoảng cách $MN$:</p><p class=\"text-base leading-relaxed my-2\">$MN = \\sqrt{\\left(a - \\dfrac{a}{\\sqrt{3}}\\right)^2 + \\left(\\dfrac{a}{\\sqrt{3}} - a\\right)^2} = \\sqrt{2}\\,a\\left(1 - \\dfrac{1}{\\sqrt{3}}\\right)$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow MN = \\sqrt{2}\\cdot 0{,}1\\cdot(1 - 0{,}57735) \\approx 0{,}0598$ m.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến 1 chữ số có nghĩa: $MN \\approx 0{,}06$ m.</p>","difficultySource":"ai"},"ex":[{"exam":806,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"0,06","question":"Hai điện tích điểm q1 = 2.10<sup>−7</sup> C và q2 = –2.10<sup>−7</sup> C lần lượt đặt tại A và B cách nhau 10 cm trong không khí. Giả sử q1 đặt cố định tại A, còn q2 ở B sẽ di chuyển lần lượt trên các cạnh BC và CD của hình vuông ABCD, thì lực tương tác tĩnh điện giữa hai điện tích có độ lớn nhỏ nhất là Fmin và lớn nhất là Fmax, đồng thời ta thấy có hai vị trí của q2 (tại điểm M và N) mà tại đó độ lớn lực tương tác tĩnh điện đều bằng  $\\frac{F_{min}+F_{max}}{2}$ . Tính khoảng cách MN (tính bằng mét). (Kết quả lấy đến 1 chữ số có nghĩa).<br>Tài liệu được chia sẻ bởi Website VnTeach.Com<br>https://www.vnteach.com","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Đặt $A$ tại gốc tọa độ, $AB = a = 0{,}1$ m. Lực tĩnh điện giữa hai điện tích trong không khí có độ lớn $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $r$ là khoảng cách từ $A$ đến $q_2$.</p><p class=\"text-base leading-relaxed my-2\">Khi $q_2$ di chuyển trên $BC$ và $CD$, khoảng cách $r$ nằm trong khoảng: nhỏ nhất $r_{min} = a$ (tại $B$ hoặc $D$), lớn nhất $r_{max} = a\\sqrt{2}$ (tại $C$).</p><p class=\"text-base leading-relaxed my-2\">Suy ra $F_{max} = k\\dfrac{|q_1 q_2|}{a^2}$ và $F_{min} = k\\dfrac{|q_1 q_2|}{2a^2}$.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện đề bài: $F = \\dfrac{F_{min}+F_{max}}{2}$. Vì $F \\propto 1/r^2$ nên</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{1}{r^2} = \\dfrac{1}{2}\\left(\\dfrac{1}{a^2} + \\dfrac{1}{2a^2}\\right) = \\dfrac{3}{4a^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = \\dfrac{2a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Xác định vị trí $M$ trên $BC$: $M = (a, y)$ với $a^2 + y^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow y = \\dfrac{a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Xác định vị trí $N$ trên $CD$: $N = (x, a)$ với $x^2 + a^2 = \\dfrac{4a^2}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x = \\dfrac{a}{\\sqrt{3}}$.</p><p class=\"text-base leading-relaxed my-2\">Khoảng cách $MN$:</p><p class=\"text-base leading-relaxed my-2\">$MN = \\sqrt{\\left(a - \\dfrac{a}{\\sqrt{3}}\\right)^2 + \\left(\\dfrac{a}{\\sqrt{3}} - a\\right)^2} = \\sqrt{2}\\,a\\left(1 - \\dfrac{1}{\\sqrt{3}}\\right)$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow MN = \\sqrt{2}\\cdot 0{,}1\\cdot(1 - 0{,}57735) \\approx 0{,}0598$ m.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến 1 chữ số có nghĩa: $MN \\approx 0{,}06$ m.</p>","difficultySource":"ai"}}]},{"id":1176189,"nq":{"form":"bai_tap","type":"true_false","topic":"Điện trường đều","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216478171-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />A, B, C là ba điểm tạo thành tam giác vuông tại A đặt trong điện trường đều của một tụ phẳng không khí. Biết hiệu điện thế giữa hai bản tụ là U = 300V và khoảng cách giữa hai bản là d = 15cm. Cho  $\\alpha =60^{\\circ}$ ;  $BC=12cm$ .","difficulty":"kho","statements":[{"text":"Độ lớn cường độ điện trường là E= 2000 V/m","answer":true},{"text":"Công thực hiện để dịch chuyển điện tích  $q=10^{−9}C$ từ B đến C là 1,2.10<sup>−5</sup> J","answer":false},{"text":"Điện trường bên trong tụ điện là điện trường đều và đường sức điện hướng từ bản âm sang bản dương","answer":false},{"text":"Đặt một điện tích dương tại điểm B thì nó sẽ di chuyển sang bản âm","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Điện trường đều giữa hai bản: $E=\\dfrac{U}{d}=\\dfrac{300}{0{,}15}=2000$ V/m: Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Công lực điện $A=qEd$ với $d$ là hình chiếu của $BC$ lên phương đường sức: $d=BC\\cos 60^\\circ=12\\cdot 0{,}5=6$ cm $=0{,}06$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$A=10^{-9}\\cdot 2000\\cdot 0{,}06=1{,}2\\cdot 10^{-7}$ J, không phải $1{,}2\\cdot 10^{-5}$ J: Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Đường sức trong tụ hướng từ bản dương (trái) sang bản âm (phải), không phải từ âm sang dương: Sai.</p><p class=\"text-base leading-relaxed my-2\">d) Điện tích dương chịu lực cùng chiều $\\vec E$ nên dịch chuyển về phía bản âm: Đúng.</p>","difficultySource":"ai"},"ex":[{"exam":807,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Điện trường đều","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216478171-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />A, B, C là ba điểm tạo thành tam giác vuông tại A đặt trong điện trường đều của một tụ phẳng không khí. Biết hiệu điện thế giữa hai bản tụ là U = 300V và khoảng cách giữa hai bản là d = 15cm. Cho  $\\alpha =60^{\\circ}$ ;  $BC=12cm$ .","difficulty":"kho","statements":[{"text":"Độ lớn cường độ điện trường là E= 2000 V/m","answer":true},{"text":"Công thực hiện để dịch chuyển điện tích  $q=10^{−9}C$ từ B đến C là 1,2.10<sup>−5</sup> J","answer":false},{"text":"Điện trường bên trong tụ điện là điện trường đều và đường sức điện hướng từ bản âm sang bản dương","answer":false},{"text":"Đặt một điện tích dương tại điểm B thì nó sẽ di chuyển sang bản âm","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Điện trường đều giữa hai bản: $E=\\dfrac{U}{d}=\\dfrac{300}{0{,}15}=2000$ V/m: Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Công lực điện $A=qEd$ với $d$ là hình chiếu của $BC$ lên phương đường sức: $d=BC\\cos 60^\\circ=12\\cdot 0{,}5=6$ cm $=0{,}06$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$A=10^{-9}\\cdot 2000\\cdot 0{,}06=1{,}2\\cdot 10^{-7}$ J, không phải $1{,}2\\cdot 10^{-5}$ J: Sai.</p><p class=\"text-base leading-relaxed my-2\">c) Đường sức trong tụ hướng từ bản dương (trái) sang bản âm (phải), không phải từ âm sang dương: Sai.</p><p class=\"text-base leading-relaxed my-2\">d) Điện tích dương chịu lực cùng chiều $\\vec E$ nên dịch chuyển về phía bản âm: Đúng.</p>","difficultySource":"ai"}}]},{"id":1178258,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":2,"options":["q = 5.10<sup>4</sup>  $\\mu C.$","q = 5.10<sup>4</sup> (nC).","q = 5.10-2  $\\mu C.$","q = 5.10<sup>−4</sup> (C)."],"question":"Một tụ điện có điện dung 500 (pF) được mắc vào hiệu điện thế 100 (V). Điện tích của tụ điện là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện được tính theo công thức $q = C\\cdot U$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị điện dung: $C = 500\\ \\text{pF} = 500\\cdot 10^{-12}\\ \\text{F} = 5\\cdot 10^{-10}\\ \\text{F}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 5\\cdot 10^{-10}\\cdot 100 = 5\\cdot 10^{-8}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang đơn vị $\\mu$C: $5\\cdot 10^{-8}\\ \\text{C} = 5\\cdot 10^{-2}\\ \\mu\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $q = 5\\cdot 10^{-2}\\ \\mu\\text{C}$, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":808,"idx":24,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":2,"options":["q = 5.10<sup>4</sup>  $\\mu C.$","q = 5.10<sup>4</sup> (nC).","q = 5.10-2  $\\mu C.$","q = 5.10<sup>−4</sup> (C)."],"question":"Một tụ điện có điện dung 500 (pF) được mắc vào hiệu điện thế 100 (V). Điện tích của tụ điện là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện được tính theo công thức $q = C\\cdot U$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị điện dung: $C = 500\\ \\text{pF} = 500\\cdot 10^{-12}\\ \\text{F} = 5\\cdot 10^{-10}\\ \\text{F}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 5\\cdot 10^{-10}\\cdot 100 = 5\\cdot 10^{-8}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang đơn vị $\\mu$C: $5\\cdot 10^{-8}\\ \\text{C} = 5\\cdot 10^{-2}\\ \\mu\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $q = 5\\cdot 10^{-2}\\ \\mu\\text{C}$, đáp án C.</p>","difficultySource":"ai"}}]},{"id":1178259,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng của tụ điện","answer":1,"options":["2,5.10<sup>−2</sup>J.","10−2 J.","0,4 J.","2,5 J."],"question":"Nối hai bản của một tụ điện có điện dung 50 μF vào hai điểm có hiệu điện thế 20 V. Năng lượng điện trường mà tụ tích được","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng điện trường tích trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 50\\ \\mu F = 50.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W = \\dfrac{1}{2}\\cdot 50.10^{-6}\\cdot 20^2 = \\dfrac{1}{2}\\cdot 50.10^{-6}\\cdot 400 = 10^{-2}\\ J$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng điện trường tụ tích được là $10^{-2}\\ J$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":808,"idx":25,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng của tụ điện","answer":1,"options":["2,5.10<sup>−2</sup>J.","10−2 J.","0,4 J.","2,5 J."],"question":"Nối hai bản của một tụ điện có điện dung 50 μF vào hai điểm có hiệu điện thế 20 V. Năng lượng điện trường mà tụ tích được","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng điện trường tích trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 50\\ \\mu F = 50.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W = \\dfrac{1}{2}\\cdot 50.10^{-6}\\cdot 20^2 = \\dfrac{1}{2}\\cdot 50.10^{-6}\\cdot 400 = 10^{-2}\\ J$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng điện trường tụ tích được là $10^{-2}\\ J$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1180470,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":3,"options":["55 cm/s","88cm/s","100 cm/s","73cm/s"],"question":"Một con lắc lò xo đặt nằm ngang gồm một lò xo có độ cứng k = 10 N/m gắn với vật nhỏ có khối lượng m =100 g và mang tích điện q = 5.10<sup>−5</sup> C . Khi vật nhỏ đang ở vi trí cân bằng người ta thiết lập một điện trường đều theo phương nằm ngang dọc theo trục lò xo và có cường độ E = 104 V/m trong khoảng thời gian Δt = 0,05π s rồi ngắt điện trường. Bỏ qua ma sát. Vận tốc cực đại của vật sau khi ngắt điện trường có giá trị gần giá trị nào nhất?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Bỏ qua ma sát, vật dao động điều hòa trên trục lò xo. Tần số góc của con lắc khi chưa có điện trường: $\\omega=\\sqrt{\\dfrac{k}{m}}=\\sqrt{\\dfrac{10}{0{,}1}}=10\\ \\text{rad/s}$, chu kỳ $T=\\dfrac{2\\pi}{\\omega}=0{,}2\\pi\\ \\text{s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Lực điện không đổi có độ lớn: $F=qE=5\\cdot10^{-5}\\cdot10^{4}=0{,}5\\ \\text{N}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Vị trí cân bằng mới (khi có điện trường) lệch khỏi vị trí cân bằng cũ một đoạn: $x_0=\\dfrac{F}{k}=\\dfrac{0{,}5}{10}=0{,}05\\ \\text{m}=5\\ \\text{cm}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Thời gian đặt điện trường: $\\Delta t=0{,}05\\pi=\\dfrac{\\pi}{20}\\ \\text{s}=\\dfrac{T}{4}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Khi có điện trường, vật dao động quanh vị trí cân bằng mới $O'$ với biên độ $x_0$, bắt đầu từ vị trí cân bằng cũ $O$ với vận tốc bằng 0. Chọn gốc tọa độ tại $O$, chiều dương cùng chiều lực điện:</p>\n<p class=\"text-base leading-relaxed my-2\">$x-x_0=-x_0\\cos\\omega t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=x_0\\omega\\sin\\omega t$.</p>\n<p class=\"text-base leading-relaxed my-2\">Tại $t=\\Delta t=\\dfrac{T}{4}$, $\\omega t=\\dfrac{\\pi}{2}$: $x=x_0=0{,}05\\ \\text{m}$ và $v=x_0\\omega=0{,}05\\cdot10=0{,}5\\ \\text{m/s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Sau khi ngắt điện trường, vị trí cân bằng trở về $O$, tần số góc vẫn là $\\omega=10\\ \\text{rad/s}$. Biên độ dao động mới:</p>\n<p class=\"text-base leading-relaxed my-2\">$A=\\sqrt{x^2+\\dfrac{v^2}{\\omega^2}}=\\sqrt{0{,}05^2+\\left(\\dfrac{0{,}5}{10}\\right)^2}=\\sqrt{0{,}005}\\approx0{,}0707\\ \\text{m}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Vận tốc cực đại sau khi ngắt điện trường: $v_{max}=\\omega A=10\\cdot0{,}0707\\approx0{,}707\\ \\text{m/s}=70{,}7\\ \\text{cm/s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Giá trị gần nhất trong các phương án là $73\\ \\text{cm/s}$.</p>","difficultySource":"ai"},"ex":[{"exam":810,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":3,"options":["55 cm/s","88cm/s","100 cm/s","73cm/s"],"question":"Một con lắc lò xo đặt nằm ngang gồm một lò xo có độ cứng k = 10 N/m gắn với vật nhỏ có khối lượng m =100 g và mang tích điện q = 5.10<sup>−5</sup> C . Khi vật nhỏ đang ở vi trí cân bằng người ta thiết lập một điện trường đều theo phương nằm ngang dọc theo trục lò xo và có cường độ E = 104 V/m trong khoảng thời gian Δt = 0,05π s rồi ngắt điện trường. Bỏ qua ma sát. Vận tốc cực đại của vật sau khi ngắt điện trường có giá trị gần giá trị nào nhất?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Bỏ qua ma sát, vật dao động điều hòa trên trục lò xo. Tần số góc của con lắc khi chưa có điện trường: $\\omega=\\sqrt{\\dfrac{k}{m}}=\\sqrt{\\dfrac{10}{0{,}1}}=10\\ \\text{rad/s}$, chu kỳ $T=\\dfrac{2\\pi}{\\omega}=0{,}2\\pi\\ \\text{s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Lực điện không đổi có độ lớn: $F=qE=5\\cdot10^{-5}\\cdot10^{4}=0{,}5\\ \\text{N}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Vị trí cân bằng mới (khi có điện trường) lệch khỏi vị trí cân bằng cũ một đoạn: $x_0=\\dfrac{F}{k}=\\dfrac{0{,}5}{10}=0{,}05\\ \\text{m}=5\\ \\text{cm}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Thời gian đặt điện trường: $\\Delta t=0{,}05\\pi=\\dfrac{\\pi}{20}\\ \\text{s}=\\dfrac{T}{4}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Khi có điện trường, vật dao động quanh vị trí cân bằng mới $O'$ với biên độ $x_0$, bắt đầu từ vị trí cân bằng cũ $O$ với vận tốc bằng 0. Chọn gốc tọa độ tại $O$, chiều dương cùng chiều lực điện:</p>\n<p class=\"text-base leading-relaxed my-2\">$x-x_0=-x_0\\cos\\omega t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=x_0\\omega\\sin\\omega t$.</p>\n<p class=\"text-base leading-relaxed my-2\">Tại $t=\\Delta t=\\dfrac{T}{4}$, $\\omega t=\\dfrac{\\pi}{2}$: $x=x_0=0{,}05\\ \\text{m}$ và $v=x_0\\omega=0{,}05\\cdot10=0{,}5\\ \\text{m/s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Sau khi ngắt điện trường, vị trí cân bằng trở về $O$, tần số góc vẫn là $\\omega=10\\ \\text{rad/s}$. Biên độ dao động mới:</p>\n<p class=\"text-base leading-relaxed my-2\">$A=\\sqrt{x^2+\\dfrac{v^2}{\\omega^2}}=\\sqrt{0{,}05^2+\\left(\\dfrac{0{,}5}{10}\\right)^2}=\\sqrt{0{,}005}\\approx0{,}0707\\ \\text{m}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Vận tốc cực đại sau khi ngắt điện trường: $v_{max}=\\omega A=10\\cdot0{,}0707\\approx0{,}707\\ \\text{m/s}=70{,}7\\ \\text{cm/s}$.</p>\n<p class=\"text-base leading-relaxed my-2\">Giá trị gần nhất trong các phương án là $73\\ \\text{cm/s}$.</p>","difficultySource":"ai"}}]},{"id":1180479,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Hai quả cầu nhiễm điện và điện tích của mỗi quả lần lượt là: q1 = 10-7 C và q2 = 4.10<sup>−7</sup> C, đặt cách nhau một khoảng 6 cm trong chân không.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác điện giữa hai quả cầu có độ lớn bằng 0,1 N.","answer":true},{"text":"Hai quả cầu nhiễm điện cùng dấu.","answer":true},{"text":"Lực tương tác điện giữa hai quả cầu là lực hút.","answer":false},{"text":"Khi tăng khoảng cách giữa hai quả cầu thì độ lớn lực tương tác điện giữa chúng sẽ tăng lên.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật Coulomb: lực tương tác giữa hai điện tích điểm trong chân không có độ lớn $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 6\\ \\text{cm} = 0{,}06\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Ý a): Thay số $F = 9.10^9 \\cdot \\dfrac{10^{-7}\\cdot 4.10^{-7}}{(0{,}06)^2} = 9.10^9 \\cdot \\dfrac{4.10^{-14}}{3{,}6.10^{-3}} = 0{,}1\\ \\text{N}$. Vậy a) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">Ý b): Hai điện tích $q_1 = 10^{-7}\\ \\text{C} \\gt  0$ và $q_2 = 4.10^{-7}\\ \\text{C} \\gt  0$ cùng dấu dương. Vậy b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">Ý c): Hai điện tích cùng dấu thì đẩy nhau, lực tương tác là lực đẩy (không phải lực hút). Vậy c) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">Ý d): Từ công thức $F = k\\dfrac{|q_1 q_2|}{r^2}$, lực tỉ lệ nghịch với bình phương khoảng cách $r$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Khi tăng $r$ thì $F$ giảm, không tăng. Vậy d) <b>Sai</b>.</p>","difficultySource":"ai"},"ex":[{"exam":810,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Hai quả cầu nhiễm điện và điện tích của mỗi quả lần lượt là: q1 = 10-7 C và q2 = 4.10<sup>−7</sup> C, đặt cách nhau một khoảng 6 cm trong chân không.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác điện giữa hai quả cầu có độ lớn bằng 0,1 N.","answer":true},{"text":"Hai quả cầu nhiễm điện cùng dấu.","answer":true},{"text":"Lực tương tác điện giữa hai quả cầu là lực hút.","answer":false},{"text":"Khi tăng khoảng cách giữa hai quả cầu thì độ lớn lực tương tác điện giữa chúng sẽ tăng lên.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1180482,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"0,25","question":"Công của lực điện dịch chuyển điện tích 5.10<sup>−3</sup> C đoạn 0,1 m trong một điện trường đều có cường độ điện trường 1000 V/m theo hướng hợp với hướng của đường sức một góc 600 có giá trị bằng bao nhiêu J?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trong điện trường đều khi điện tích di chuyển một đoạn $d$ theo phương hợp với đường sức một góc $\\alpha$:</p><p class=\"text-base leading-relaxed my-2\">$A = qEd\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $q$ là điện tích, $E$ là cường độ điện trường, $d$ là độ dài đoạn dịch chuyển theo phương đường sức (hình chiếu lên đường sức), $\\alpha$ là góc giữa lực điện (hướng của đường sức) và độ dịch chuyển.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 5\\cdot10^{-3}\\ \\text{C}$, $E = 1000\\ \\text{V/m}$, $d = 0{,}1\\ \\text{m}$, $\\alpha = 60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$A = 5\\cdot10^{-3}\\cdot 1000\\cdot 0{,}1\\cdot\\cos 60^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 5\\cdot10^{-3}\\cdot 1000\\cdot 0{,}1\\cdot 0{,}5 = 0{,}25\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công của lực điện là $A = 0{,}25\\ \\text{J}$.</p>","difficultySource":"ai"},"ex":[{"exam":810,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"0,25","question":"Công của lực điện dịch chuyển điện tích 5.10<sup>−3</sup> C đoạn 0,1 m trong một điện trường đều có cường độ điện trường 1000 V/m theo hướng hợp với hướng của đường sức một góc 600 có giá trị bằng bao nhiêu J?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trong điện trường đều khi điện tích di chuyển một đoạn $d$ theo phương hợp với đường sức một góc $\\alpha$:</p><p class=\"text-base leading-relaxed my-2\">$A = qEd\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $q$ là điện tích, $E$ là cường độ điện trường, $d$ là độ dài đoạn dịch chuyển theo phương đường sức (hình chiếu lên đường sức), $\\alpha$ là góc giữa lực điện (hướng của đường sức) và độ dịch chuyển.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 5\\cdot10^{-3}\\ \\text{C}$, $E = 1000\\ \\text{V/m}$, $d = 0{,}1\\ \\text{m}$, $\\alpha = 60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$A = 5\\cdot10^{-3}\\cdot 1000\\cdot 0{,}1\\cdot\\cos 60^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = 5\\cdot10^{-3}\\cdot 1000\\cdot 0{,}1\\cdot 0{,}5 = 0{,}25\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy công của lực điện là $A = 0{,}25\\ \\text{J}$.</p>","difficultySource":"ai"}}]},{"id":1181311,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"10","question":"Trong chân không khi hai điện tích điểm đặt cách nhau lần lượt là r và r + 10(cm) thì lực tương tác tĩnh điện giữa chúng có độ lớn tương ứng là 2.10<sup>−6</sup> N và 5.10<sup>−7</sup> N. Giá trị của r là bao nhiêu cm?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm trong chân không là $F = k\\dfrac{|q_1 q_2|}{r^2}$, tỉ lệ nghịch với bình phương khoảng cách $r$ (điện tích $q_1, q_2$ không đổi).</p><p class=\"text-base leading-relaxed my-2\">Lập tỉ số lực ứng với hai khoảng cách $r$ và $r + 10$ (cm):</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{F_1}{F_2} = \\dfrac{(r+10)^2}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{2.10^{-6}}{5.10^{-7}} = \\left(\\dfrac{r+10}{r}\\right)^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 4 = \\left(\\dfrac{r+10}{r}\\right)^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{r+10}{r} = 2$ (vì khoảng cách dương)</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r + 10 = 2r$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = 10 \\text{ cm}$</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: ở $r = 10$ cm lực là $2.10^{-6}$ N; ở $20$ cm lực giảm 4 lần, còn $5.10^{-7}$ N. Đúng.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> $r = 10$ cm.</p>","difficultySource":"ai"},"ex":[{"exam":811,"idx":12,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"10","question":"Trong chân không khi hai điện tích điểm đặt cách nhau lần lượt là r và r + 10(cm) thì lực tương tác tĩnh điện giữa chúng có độ lớn tương ứng là 2.10<sup>−6</sup> N và 5.10<sup>−7</sup> N. Giá trị của r là bao nhiêu cm?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm trong chân không là $F = k\\dfrac{|q_1 q_2|}{r^2}$, tỉ lệ nghịch với bình phương khoảng cách $r$ (điện tích $q_1, q_2$ không đổi).</p><p class=\"text-base leading-relaxed my-2\">Lập tỉ số lực ứng với hai khoảng cách $r$ và $r + 10$ (cm):</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{F_1}{F_2} = \\dfrac{(r+10)^2}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{2.10^{-6}}{5.10^{-7}} = \\left(\\dfrac{r+10}{r}\\right)^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 4 = \\left(\\dfrac{r+10}{r}\\right)^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{r+10}{r} = 2$ (vì khoảng cách dương)</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r + 10 = 2r$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = 10 \\text{ cm}$</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: ở $r = 10$ cm lực là $2.10^{-6}$ N; ở $20$ cm lực giảm 4 lần, còn $5.10^{-7}$ N. Đúng.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> $r = 10$ cm.</p>","difficultySource":"ai"}}]},{"id":1181315,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"0,5","question":"Ta cần thực hiện một công 8.10<sup>−5</sup> J để dịch chuyển điện tích 1,6.10<sup>−4</sup> C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Điện thế tại M bằng bao nhiêu Vôn (V)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trường khi dịch chuyển điện tích $q$ từ vô cực đến điểm $M$ là $A_{\\infty M} = q(V_\\infty - V_M)$. Chọn gốc điện thế tại vô cực nên $V_\\infty = 0$, suy ra $A_{\\infty M} = -qV_M$.</p><p class=\"text-base leading-relaxed my-2\">Công do lực ngoài thực hiện bằng và ngược dấu với công của lực điện: $A_{\\text{ngoài}} = -A_{\\infty M} = qV_M$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra điện thế tại $M$: $V_M = \\dfrac{A_{\\text{ngoài}}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{8\\cdot 10^{-5}}{1{,}6\\cdot 10^{-4}} = 0{,}5\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại $M$ bằng $0{,}5$ V.</p>","difficultySource":"ai"},"ex":[{"exam":811,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"0,5","question":"Ta cần thực hiện một công 8.10<sup>−5</sup> J để dịch chuyển điện tích 1,6.10<sup>−4</sup> C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Điện thế tại M bằng bao nhiêu Vôn (V)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trường khi dịch chuyển điện tích $q$ từ vô cực đến điểm $M$ là $A_{\\infty M} = q(V_\\infty - V_M)$. Chọn gốc điện thế tại vô cực nên $V_\\infty = 0$, suy ra $A_{\\infty M} = -qV_M$.</p><p class=\"text-base leading-relaxed my-2\">Công do lực ngoài thực hiện bằng và ngược dấu với công của lực điện: $A_{\\text{ngoài}} = -A_{\\infty M} = qV_M$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra điện thế tại $M$: $V_M = \\dfrac{A_{\\text{ngoài}}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{8\\cdot 10^{-5}}{1{,}6\\cdot 10^{-4}} = 0{,}5\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại $M$ bằng $0{,}5$ V.</p>","difficultySource":"ai"}}]},{"id":1181552,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":1,"options":["$E=\\frac{\\left|Q\\right|}{r^2}$","$E=k\\frac{\\left|Q\\right|}{r^2}$","$E=k^2\\frac{\\left|Q\\right|}{r}$","$E=k\\frac{\\left|2Q\\right|}{r^2}$"],"question":"Công thức nào sau đây xác định độ lớn cường độ điện trường do một điện tích điểm Q gây ra tại một điểm M cách điện tích một đoạn r trong chân không, với k = 9.10<sup>9</sup>(Nm2/C2)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm Q gây ra tại điểm M cách điện tích một khoảng r trong chân không được xác định bởi công thức:</p><p class=\"text-base leading-relaxed my-2\">$E=k\\frac{|Q|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">trong đó $k=9\\cdot10^9\\ \\text{N}\\cdot\\text{m}^2/\\text{C}^2$, $Q$ là điện tích nguồn (C), $r$ là khoảng cách từ điện tích đến điểm M (m), và $E$ có đơn vị V/m.</p><p class=\"text-base leading-relaxed my-2\">Phương án A thiếu hằng số $k$; phương án C có $k^2$ và $r$ ở mẫu sai bậc; phương án D nhân đôi điện tích nên sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <strong>B</strong>.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":2,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":1,"options":["$E=\\frac{\\left|Q\\right|}{r^2}$","$E=k\\frac{\\left|Q\\right|}{r^2}$","$E=k^2\\frac{\\left|Q\\right|}{r}$","$E=k\\frac{\\left|2Q\\right|}{r^2}$"],"question":"Công thức nào sau đây xác định độ lớn cường độ điện trường do một điện tích điểm Q gây ra tại một điểm M cách điện tích một đoạn r trong chân không, với k = 9.10<sup>9</sup>(Nm2/C2)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm Q gây ra tại điểm M cách điện tích một khoảng r trong chân không được xác định bởi công thức:</p><p class=\"text-base leading-relaxed my-2\">$E=k\\frac{|Q|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">trong đó $k=9\\cdot10^9\\ \\text{N}\\cdot\\text{m}^2/\\text{C}^2$, $Q$ là điện tích nguồn (C), $r$ là khoảng cách từ điện tích đến điểm M (m), và $E$ có đơn vị V/m.</p><p class=\"text-base leading-relaxed my-2\">Phương án A thiếu hằng số $k$; phương án C có $k^2$ và $r$ ở mẫu sai bậc; phương án D nhân đôi điện tích nên sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <strong>B</strong>.</p>","difficultySource":"ai"}}]},{"id":1181560,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":1,"options":["Độ lớn 6.10<sup>−2</sup>N và chiều từ dưới lên trên.","Độ lớn 6.10<sup>−2</sup>N và chiều từ trên xuống dưới.","Độ lớn 6.10<sup>−12</sup> N và chiều từ dưới lên trên.","Độ lớn 6.10<sup>12</sup>N và chiều từ trên xuống dưới."],"question":"Một điện tích q = -2,5.10<sup>−7</sup>C đặt tại điểm M. Cường độ điện trường tại M có độ lớn 2,4.10<sup>5</sup>V/m và chiều từ dưới lên trên. Lực điện tác dụng lên điện tích q có","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm trong điện trường đều (hoặc tại một điểm có cường độ điện trường $\\vec{E}$) được xác định bởi $\\vec{F} = q\\vec{E}$, nên độ lớn $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2{,}5.10^{-7} \\cdot 2{,}4.10^{5} = 6.10^{-2}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Vì $q \\lt 0$ nên $\\vec{F}$ ngược chiều với $\\vec{E}$. Đề cho $\\vec{E}$ hướng từ dưới lên trên, do đó lực $\\vec{F}$ hướng từ trên xuống dưới.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $6.10^{-2}\\ \\text{N}$ và chiều từ trên xuống dưới. Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":1,"options":["Độ lớn 6.10<sup>−2</sup>N và chiều từ dưới lên trên.","Độ lớn 6.10<sup>−2</sup>N và chiều từ trên xuống dưới.","Độ lớn 6.10<sup>−12</sup> N và chiều từ dưới lên trên.","Độ lớn 6.10<sup>12</sup>N và chiều từ trên xuống dưới."],"question":"Một điện tích q = -2,5.10<sup>−7</sup>C đặt tại điểm M. Cường độ điện trường tại M có độ lớn 2,4.10<sup>5</sup>V/m và chiều từ dưới lên trên. Lực điện tác dụng lên điện tích q có","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm trong điện trường đều (hoặc tại một điểm có cường độ điện trường $\\vec{E}$) được xác định bởi $\\vec{F} = q\\vec{E}$, nên độ lớn $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2{,}5.10^{-7} \\cdot 2{,}4.10^{5} = 6.10^{-2}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Vì $q \\lt 0$ nên $\\vec{F}$ ngược chiều với $\\vec{E}$. Đề cho $\\vec{E}$ hướng từ dưới lên trên, do đó lực $\\vec{F}$ hướng từ trên xuống dưới.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $6.10^{-2}\\ \\text{N}$ và chiều từ trên xuống dưới. Chọn B.</p>","difficultySource":"ai"}}]},{"id":1181564,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"8,10","question":"Hai điện tích điểm có cùng độ lớn được đặt trong một môi trường có hằng số điện môi ε, khi khoảng cách giữa chúng là r1 thì lực tương tác giữa chúng là $F_1$= 2.10<sup>−5</sup> N. Khi khoảng cách giữa chúng là r2 = 0,5r1 thì lực tương tác giữa chúng là bao nhiêu Niutơn (N)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực Cu-lông giữa hai điện tích điểm đặt trong cùng một môi trường: $F=\\dfrac{k|q_1q_2|}{\\varepsilon r^2}$, nên với $q_1,q_2,\\varepsilon$ không đổi thì $F\\sim\\dfrac{1}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{F_2}{F_1}=\\dfrac{r_1^2}{r_2^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{F_2}{F_1}=\\dfrac{1}{0,5^2}=4$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_2=4F_1=4\\cdot 2\\cdot10^{-5}=8\\cdot10^{-5}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $F_2 = 8\\cdot10^{-5}$ N.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"8,10","question":"Hai điện tích điểm có cùng độ lớn được đặt trong một môi trường có hằng số điện môi ε, khi khoảng cách giữa chúng là r1 thì lực tương tác giữa chúng là F1= 2.10<sup>−5</sup> N. Khi khoảng cách giữa chúng là r2 = 0,5r1 thì lực tương tác giữa chúng là bao nhiêu Niutơn (N)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực Cu-lông giữa hai điện tích điểm đặt trong cùng một môi trường: $F=\\dfrac{k|q_1q_2|}{\\varepsilon r^2}$, nên với $q_1,q_2,\\varepsilon$ không đổi thì $F\\sim\\dfrac{1}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{F_2}{F_1}=\\dfrac{r_1^2}{r_2^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{F_2}{F_1}=\\dfrac{1}{0,5^2}=4$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_2=4F_1=4\\cdot 2\\cdot10^{-5}=8\\cdot10^{-5}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $F_2 = 8\\cdot10^{-5}$ N.</p>","difficultySource":"ai"}}]},{"id":1181567,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"0,8","question":"Ta cần thực hiện một công 8.10<sup>−5</sup>J để dịch chuyển điện tích 10-4 C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Tính điện thế tại M (theo đơn vị V).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích $q$ di chuyển từ điểm $P$ đến $Q$ là $A_{PQ} = q(V_P - V_Q)$.</p><p class=\"text-base leading-relaxed my-2\">Công do lực ngoài thực hiện để đưa điện tích từ vô cực đến $M$ bằng công cản của lực điện, nên $A_{\\infty M}^{\\text{ngoài}} = -A_{\\infty M}^{\\text{điện}} = q(V_M - V_\\infty)$.</p><p class=\"text-base leading-relaxed my-2\">Chọn gốc điện thế tại vô cực: $V_\\infty = 0$. Suy ra $A_{\\text{ngoài}} = qV_M$.</p><p class=\"text-base leading-relaxed my-2\">Điện thế tại $M$: $V_M = \\dfrac{A_{\\text{ngoài}}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{8\\cdot 10^{-5}}{10^{-4}} = 0{,}8\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại $M$ là $V_M = 0{,}8\\ \\text{V}$.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":17,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"0,8","question":"Ta cần thực hiện một công 8.10<sup>−5</sup>J để dịch chuyển điện tích 10-4 C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Tính điện thế tại M (theo đơn vị V).","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1181568,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"-9,1","question":"Một điện tích q = −1,5.10<sup>−8</sup> C đặt tại điểm M có điện thế bằng 600 V. Tính thế năng điện của điện tích q tại M (theo đơn vị J).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng điện của điện tích q tại điểm M có điện thế $V_M$ (chọn mốc thế năng tại vô cực hoặc tại đất, ứng với điện thế bằng 0): $W_M = qV_M$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M = (-1{,}5.10^{-8}).600$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M = -9.10^{-6}$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng điện của q tại M là $-9.10^{-6}$ J (tức $-9\\ \\mu$J).</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":18,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"-9,1","question":"Một điện tích q = −1,5.10<sup>−8</sup> C đặt tại điểm M có điện thế bằng 600 V. Tính thế năng điện của điện tích q tại M (theo đơn vị J).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng điện của điện tích q tại điểm M có điện thế $V_M$ (chọn mốc thế năng tại vô cực hoặc tại đất, ứng với điện thế bằng 0): $W_M = qV_M$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M = (-1{,}5.10^{-8}).600$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M = -9.10^{-6}$ J.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng điện của q tại M là $-9.10^{-6}$ J (tức $-9\\ \\mu$J).</p>","difficultySource":"ai"}}]},{"id":1181569,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng của tụ điện","answer":"3,2","question":"Một tụ điện có điện dung C = 4.10<sup>−12</sup> F được tích điện đến điện tích 16.10<sup>−8</sup> C. Tính năng lượng của tụ điện (theo đơn vị J).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng tụ điện tích điện: $W=\\dfrac{Q^2}{2C}$ với $C=4\\cdot10^{-12}\\,\\text{F}$, $Q=16\\cdot10^{-8}\\,\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=\\dfrac{(16\\cdot10^{-8})^2}{2\\cdot4\\cdot10^{-12}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=\\dfrac{256\\cdot10^{-16}}{8\\cdot10^{-12}}=32\\cdot10^{-4}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=3{,}2\\cdot10^{-3}\\,\\text{J}$.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng của tụ điện","answer":"3,2","question":"Một tụ điện có điện dung C = 4.10<sup>−12</sup> F được tích điện đến điện tích 16.10<sup>−8</sup> C. Tính năng lượng của tụ điện (theo đơn vị J).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng tụ điện tích điện: $W=\\dfrac{Q^2}{2C}$ với $C=4\\cdot10^{-12}\\,\\text{F}$, $Q=16\\cdot10^{-8}\\,\\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=\\dfrac{(16\\cdot10^{-8})^2}{2\\cdot4\\cdot10^{-12}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=\\dfrac{256\\cdot10^{-16}}{8\\cdot10^{-12}}=32\\cdot10^{-4}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W=3{,}2\\cdot10^{-3}\\,\\text{J}$.</p>","difficultySource":"ai"}}]},{"id":1181570,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tụ điện và điện dung","answer":"4,10","question":"Xét một đám mây tích điện −36 C. Xem đám mây và bề mặt Trái Đất như một tụ điện phẳng, biết điện dung của tụ điện này khoảng 9.10<sup>−9</sup> F. Hiệu điện thế giữa hai bản của tụ điện này có độ lớn khoảng bao nhiêu Vôn?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đám mây và mặt đất tạo thành tụ điện phẳng, điện tích của tụ có độ lớn $|Q| = 36$ C, điện dung $C = 9.10^{-9}$ F.</p><p class=\"text-base leading-relaxed my-2\">Hiệu điện thế giữa hai bản: $U = \\dfrac{|Q|}{C}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U = \\dfrac{36}{9.10^{-9}} = 4.10^{9}$ V</p><p class=\"text-base leading-relaxed my-2\">Vậy hiệu điện thế có độ lớn khoảng $4.10^{9}$ V.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Tụ điện và điện dung","answer":"4,10","question":"Xét một đám mây tích điện −36 C. Xem đám mây và bề mặt Trái Đất như một tụ điện phẳng, biết điện dung của tụ điện này khoảng 9.10<sup>−9</sup> F. Hiệu điện thế giữa hai bản của tụ điện này có độ lớn khoảng bao nhiêu Vôn?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đám mây và mặt đất tạo thành tụ điện phẳng, điện tích của tụ có độ lớn $|Q| = 36$ C, điện dung $C = 9.10^{-9}$ F.</p><p class=\"text-base leading-relaxed my-2\">Hiệu điện thế giữa hai bản: $U = \\dfrac{|Q|}{C}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U = \\dfrac{36}{9.10^{-9}} = 4.10^{9}$ V</p><p class=\"text-base leading-relaxed my-2\">Vậy hiệu điện thế có độ lớn khoảng $4.10^{9}$ V.</p>","difficultySource":"ai"}}]},{"id":1182044,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":0,"options":["+ 25 µC.","- 25 µC.","+ 50 µC.","- 50 µC."],"question":"Tại một điểm trong chân không cách điện tích Q một khoảng 50 cm có cường độ điện trường là 9.10<sup>5</sup> V/m và hướng ra xa điện tích. Hãy xác định dấu và độ lớn của điện tích Q.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường của điện tích điểm $Q$ trong chân không: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9$ N.m²/C².</p><p class=\"text-base leading-relaxed my-2\">Điện trường hướng ra xa điện tích, nên $Q$ là điện tích dương.</p><p class=\"text-base leading-relaxed my-2\">Suy ra độ lớn điện tích: $|Q| = \\dfrac{E r^2}{k}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |Q| = \\dfrac{9.10^5 \\cdot (0{,}5)^2}{9.10^9} = 2{,}5.10^{-5}$ C $= 25$ µC.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $Q = +25$ µC, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":0,"options":["+ 25 µC.","- 25 µC.","+ 50 µC.","- 50 µC."],"question":"Tại một điểm trong chân không cách điện tích Q một khoảng 50 cm có cường độ điện trường là 9.10<sup>5</sup> V/m và hướng ra xa điện tích. Hãy xác định dấu và độ lớn của điện tích Q.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường của điện tích điểm $Q$ trong chân không: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9$ N.m²/C².</p><p class=\"text-base leading-relaxed my-2\">Điện trường hướng ra xa điện tích, nên $Q$ là điện tích dương.</p><p class=\"text-base leading-relaxed my-2\">Suy ra độ lớn điện tích: $|Q| = \\dfrac{E r^2}{k}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |Q| = \\dfrac{9.10^5 \\cdot (0{,}5)^2}{9.10^9} = 2{,}5.10^{-5}$ C $= 25$ µC.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $Q = +25$ µC, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1182045,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Lực tương tác giữa hai điện tích","answer":1,"options":["thừa 0,08.10<sup>−6</sup> electron.","thừa 5.10<sup>11</sup> electron.","thiếu 0,08.10<sup>−6</sup> electron.","thiếu 5.10<sup>11</sup> electron."],"question":"Cho điện tích của electron e = - 1,6.10<sup>−19</sup><br>C. So với trạng thái trung hòa, một vật nhiễm điện có điện tích q = - 0,08 µC (1 µC = 10-6<br>C) thì vật đó","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật nhiễm điện âm nghĩa là vật thừa electron. Số electron thừa được tính bằng $N = \\dfrac{|q|}{|e|}$, với $|e| = 1{,}6.10^{-19}$ C.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $|q| = 0{,}08.10^{-6}$ C $= 8.10^{-8}$ C.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{8.10^{-8}}{1{,}6.10^{-19}} = 5.10^{11}$ electron.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: vật thừa $5.10^{11}$ electron (đáp án B).</p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Lực tương tác giữa hai điện tích","answer":1,"options":["thừa 0,08.10<sup>−6</sup> electron.","thừa 5.10<sup>11</sup> electron.","thiếu 0,08.10<sup>−6</sup> electron.","thiếu 5.10<sup>11</sup> electron."],"question":"Cho điện tích của electron e = - 1,6.10<sup>−19</sup><br>C. So với trạng thái trung hòa, một vật nhiễm điện có điện tích q = - 0,08 µC (1 µC = 10-6<br>C) thì vật đó","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật nhiễm điện âm nghĩa là vật thừa electron. Số electron thừa được tính bằng $N = \\dfrac{|q|}{|e|}$, với $|e| = 1{,}6.10^{-19}$ C.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $|q| = 0{,}08.10^{-6}$ C $= 8.10^{-8}$ C.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{8.10^{-8}}{1{,}6.10^{-19}} = 5.10^{11}$ electron.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: vật thừa $5.10^{11}$ electron (đáp án B).</p>","difficultySource":"ai"}}]},{"id":1182046,"nq":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Đặt các điện tích điểm Q = - 8.10<sup>−6</sup> C và q = 2.10<sup>−6</sup> C lần lượt tại hai điểm O và M trong không khí với OM = 30 cm.","difficulty":"kho","statements":[{"text":"Cường độ điện trường do điện tích Q gây ra tại điểm M là 2.10<sup>5</sup> V/m.","answer":false},{"text":"Cường độ điện trường do Q gây ra tại điểm M không phụ thuộc vào điện tích q.","answer":true},{"text":"Cường độ điện trường do Q gây ra tại các điểm khác nhau trên đoạn OM có độ lớn khác nhau.","answer":true},{"text":"Cường điện trường tổng hợp do điện tích Q và q gây ra tại trung điểm của OM là 24.105 V/m.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do một điện tích điểm gây ra trong không khí: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9$ N.m²/C², $r$ là khoảng cách từ điện tích đến điểm xét. Véc-tơ cường độ điện trường hướng ra xa điện tích dương và hướng về điện tích âm.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Khoảng cách từ Q đến M: $r_M = OM = 0,3$ m.</p><p class=\"text-base leading-relaxed my-2\">$E_{Q,M} = 9.10^9 \\cdot \\dfrac{8.10^{-6}}{0,3^2} = 8.10^5$ V/m</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Giá trị $2.10^5$ V/m là sai. <b>Sai.</b></p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Công thức $E_{Q} = k\\dfrac{|Q|}{r^2}$ chỉ chứa Q và r, không chứa q. Điện tích q không ảnh hưởng đến điện trường do Q gây ra (nguyên lí chồng chất chỉ cộng các véc-tơ, không làm thay đổi điện trường của từng nguồn). <b>Đúng.</b></p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Với $E_Q = k\\dfrac{|Q|}{r^2}$, khi r thay đổi trên đoạn OM thì độ lớn $E_Q$ thay đổi (tỉ lệ nghịch với $r^2$). Các điểm khác nhau có khoảng cách tới O khác nhau nên độ lớn khác nhau. <b>Đúng.</b></p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Gọi I là trung điểm OM: $r_I = 0,15$ m.</p><p class=\"text-base leading-relaxed my-2\">Do Q < 0 nên $\\vec{E}_Q$ tại I hướng về O: $E_{Q,I} = 9.10^9 \\cdot \\dfrac{8.10^{-6}}{0,15^2} = 3,2.10^6$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Do q > 0 nằm tại M nên $\\vec{E}_q$ tại I hướng ra xa M, tức hướng về O: $E_{q,I} = 9.10^9 \\cdot \\dfrac{2.10^{-6}}{0,15^2} = 8.10^5$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Hai véc-tơ cùng chiều nên: $E_I = E_{Q,I} + E_{q,I} = 3,2.10^6 + 8.10^5 = 4.10^6$ V/m $= 40.10^5$ V/m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Giá trị $24.10^5$ V/m là sai. <b>Sai.</b></p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":14,"el":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Đặt các điện tích điểm Q = - 8.10<sup>−6</sup> C và q = 2.10<sup>−6</sup> C lần lượt tại hai điểm O và M trong không khí với OM = 30 cm.","difficulty":"kho","statements":[{"text":"Cường độ điện trường do điện tích Q gây ra tại điểm M là 2.10<sup>5</sup> V/m.","answer":false},{"text":"Cường độ điện trường do Q gây ra tại điểm M không phụ thuộc vào điện tích q.","answer":true},{"text":"Cường độ điện trường do Q gây ra tại các điểm khác nhau trên đoạn OM có độ lớn khác nhau.","answer":true},{"text":"Cường điện trường tổng hợp do điện tích Q và q gây ra tại trung điểm của OM là 24.105 V/m.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do một điện tích điểm gây ra trong không khí: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9$ N.m²/C², $r$ là khoảng cách từ điện tích đến điểm xét. Véc-tơ cường độ điện trường hướng ra xa điện tích dương và hướng về điện tích âm.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Khoảng cách từ Q đến M: $r_M = OM = 0,3$ m.</p><p class=\"text-base leading-relaxed my-2\">$E_{Q,M} = 9.10^9 \\cdot \\dfrac{8.10^{-6}}{0,3^2} = 8.10^5$ V/m</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Giá trị $2.10^5$ V/m là sai. <b>Sai.</b></p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Công thức $E_{Q} = k\\dfrac{|Q|}{r^2}$ chỉ chứa Q và r, không chứa q. Điện tích q không ảnh hưởng đến điện trường do Q gây ra (nguyên lí chồng chất chỉ cộng các véc-tơ, không làm thay đổi điện trường của từng nguồn). <b>Đúng.</b></p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Với $E_Q = k\\dfrac{|Q|}{r^2}$, khi r thay đổi trên đoạn OM thì độ lớn $E_Q$ thay đổi (tỉ lệ nghịch với $r^2$). Các điểm khác nhau có khoảng cách tới O khác nhau nên độ lớn khác nhau. <b>Đúng.</b></p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Gọi I là trung điểm OM: $r_I = 0,15$ m.</p><p class=\"text-base leading-relaxed my-2\">Do Q < 0 nên $\\vec{E}_Q$ tại I hướng về O: $E_{Q,I} = 9.10^9 \\cdot \\dfrac{8.10^{-6}}{0,15^2} = 3,2.10^6$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Do q > 0 nằm tại M nên $\\vec{E}_q$ tại I hướng ra xa M, tức hướng về O: $E_{q,I} = 9.10^9 \\cdot \\dfrac{2.10^{-6}}{0,15^2} = 8.10^5$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Hai véc-tơ cùng chiều nên: $E_I = E_{Q,I} + E_{q,I} = 3,2.10^6 + 8.10^5 = 4.10^6$ V/m $= 40.10^5$ V/m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Giá trị $24.10^5$ V/m là sai. <b>Sai.</b></p>","difficultySource":"ai"}}]},{"id":1182048,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Hai bản kim loại phẳng rộng, tích điện trái dấu cùng độ lớn, đặt song song đối diện nhau, cách nhau 4 cm trong chân không. Hiệu điện thế giữa hai bản là 400 V. Một electron được thả không vận tốc đầu ở sát bản âm. Bỏ qua tác dụng của trọng lực. Biết điện tích và khối lượng của electron là - 1,6.10<sup>−19</sup> C và 9,1.10<sup>−31</sup> kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216647980-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Cường độ điện trường giữa hai bản có giá trị 104 V/m.","answer":true},{"text":"Tốc độ electron khi đập vào bản dương có giá trị làm tròn là 11,9.10<sup>6</sup> m/s.","answer":true},{"text":"Electron chuyển động chậm dần đều về phía bản dương.","answer":false},{"text":"Tại điểm giữa hai bản, vectơ cường độ điện trường hướng từ bản âm sang bản dương.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Hai bản cách nhau $d=4$ cm $=0{,}04$ m, $U=400$ V; điện trường giữa hai bản là điện trường đều, hướng từ bản dương sang bản âm.</p><p class=\"text-base leading-relaxed my-2\">a) $E=\\dfrac{U}{d}=\\dfrac{400}{0{,}04}=10^4$ V/m: Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Định lí động năng: $|e|U=\\dfrac{1}{2}mv^2$ nên $v=\\sqrt{\\dfrac{2|e|U}{m}}=\\sqrt{\\dfrac{2\\cdot 1{,}6\\cdot 10^{-19}\\cdot 400}{9{,}1\\cdot 10^{-31}}}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v\\approx 11{,}9\\cdot 10^6$ m/s: Đúng.</p><p class=\"text-base leading-relaxed my-2\">c) Lực điện không đổi, cùng chiều chuyển động nên electron chuyển động nhanh dần đều, không phải chậm dần: Sai.</p><p class=\"text-base leading-relaxed my-2\">d) $\\vec E$ hướng từ bản dương sang bản âm, không phải từ âm sang dương: Sai.</p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":16,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Hai bản kim loại phẳng rộng, tích điện trái dấu cùng độ lớn, đặt song song đối diện nhau, cách nhau 4 cm trong chân không. Hiệu điện thế giữa hai bản là 400 V. Một electron được thả không vận tốc đầu ở sát bản âm. Bỏ qua tác dụng của trọng lực. Biết điện tích và khối lượng của electron là - 1,6.10<sup>−19</sup> C và 9,1.10<sup>−31</sup> kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216647980-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Cường độ điện trường giữa hai bản có giá trị 104 V/m.","answer":true},{"text":"Tốc độ electron khi đập vào bản dương có giá trị làm tròn là 11,9.10<sup>6</sup> m/s.","answer":true},{"text":"Electron chuyển động chậm dần đều về phía bản dương.","answer":false},{"text":"Tại điểm giữa hai bản, vectơ cường độ điện trường hướng từ bản âm sang bản dương.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1182050,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"-0,9","question":"Một điện tích q = 9.10<sup>−8</sup> C di chuyển từ điểm M điến điểm N trong một điện trường. Biết rằng điện thế tại M là 5 V và điện thế tại N là 15 V. Công của lực điện trong sự dịch chuyển này là bao nhiêu μJ (micrô Jun, 1 μJ = 10-6 J)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến N được tính theo công thức $A_{MN} = q\\,(V_M - V_N)$, với $V_M$, $V_N$ là điện thế tại M và N.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 9.10^{-8}\\ \\text{C}$, $V_M = 5\\ \\text{V}$, $V_N = 15\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$A_{MN} = 9.10^{-8}\\,(5 - 15) = 9.10^{-8}\\cdot(-10) = -9.10^{-7}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Đổi sang micrô jun: $-9.10^{-7}\\ \\text{J} = -0{,}9\\ \\mu\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực điện là $-0{,}9\\ \\mu\\text{J}$ (âm nghĩa là lực điện cản trở sự dịch chuyển, điện tích dương chuyển từ nơi điện thế thấp sang nơi điện thế cao hơn nên công âm).</p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":18,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"-0,9","question":"Một điện tích q = 9.10<sup>−8</sup> C di chuyển từ điểm M điến điểm N trong một điện trường. Biết rằng điện thế tại M là 5 V và điện thế tại N là 15 V. Công của lực điện trong sự dịch chuyển này là bao nhiêu μJ (micrô Jun, 1 μJ = 10-6 J)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến N được tính theo công thức $A_{MN} = q\\,(V_M - V_N)$, với $V_M$, $V_N$ là điện thế tại M và N.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 9.10^{-8}\\ \\text{C}$, $V_M = 5\\ \\text{V}$, $V_N = 15\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$A_{MN} = 9.10^{-8}\\,(5 - 15) = 9.10^{-8}\\cdot(-10) = -9.10^{-7}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Đổi sang micrô jun: $-9.10^{-7}\\ \\text{J} = -0{,}9\\ \\mu\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: công của lực điện là $-0{,}9\\ \\mu\\text{J}$ (âm nghĩa là lực điện cản trở sự dịch chuyển, điện tích dương chuyển từ nơi điện thế thấp sang nơi điện thế cao hơn nên công âm).</p>","difficultySource":"ai"}}]},{"id":1182051,"nq":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"400","question":"Đặt một điện tích thử q = 1,25.10<sup>−6</sup> C tại điểm N trong điện trường thì q chịu tác dụng của lực điện có độ lớn 0,5 mN. Độ lớn của cường độ điện trường tại N có giá trị là bao nhiêu vôn/mét?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tại một điểm được xác định bằng lực điện tác dụng lên điện tích thử đặt tại điểm đó chia cho độ lớn điện tích thử:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{F}{|q|}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $F = 0{,}5\\ \\text{mN} = 0{,}5.10^{-3}\\ \\text{N}$, $q = 1{,}25.10^{-6}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{0{,}5.10^{-3}}{1{,}25.10^{-6}} = 400\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy cường độ điện trường tại N có độ lớn $400$ V/m.</p>","difficultySource":"ai"},"ex":[{"exam":814,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"400","question":"Đặt một điện tích thử q = 1,25.10<sup>−6</sup> C tại điểm N trong điện trường thì q chịu tác dụng của lực điện có độ lớn 0,5 mN. Độ lớn của cường độ điện trường tại N có giá trị là bao nhiêu vôn/mét?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tại một điểm được xác định bằng lực điện tác dụng lên điện tích thử đặt tại điểm đó chia cho độ lớn điện tích thử:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{F}{|q|}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $F = 0{,}5\\ \\text{mN} = 0{,}5.10^{-3}\\ \\text{N}$, $q = 1{,}25.10^{-6}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{0{,}5.10^{-3}}{1{,}25.10^{-6}} = 400\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy cường độ điện trường tại N có độ lớn $400$ V/m.</p>","difficultySource":"ai"}}]},{"id":1182344,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"4,5","question":"Trong các hệ thống điện tích điểm, lực tương tác giữa các điện tích tuân theo định luật Coulomb. Hiện tượng này có ý nghĩa quan trọng trong các lĩnh vực như tĩnh điện học, hoạt động của các phân tử sinh học và ứng dụng trong công nghệ nano. Hai điện tích điểm q1 = −2×10<sup>−8</sup> C, q2 = −10−8 C được đặt cách nhau 20 cm trong không khí. Biết hằng số Coulomb k = 9×10<sup>9</sup> N⋅m2/C2. Lực tương tác giữa chúng bằng X.10<sup>−5</sup> N. Xác định giá trị X (làm tròn một chữ số thập phân sau dấu phẩy). (0,5 điểm)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác giữa hai điện tích điểm đặt trong không khí có độ lớn: $F = k\\dfrac{|q_1 q_2|}{r^2}$, trong đó $r$ là khoảng cách giữa hai điện tích.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 20\\ \\text{cm} = 0{,}2\\ \\text{m}$, $r^2 = 0{,}04\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q_1| = 2\\times10^{-8}\\ \\text{C}$, $|q_2| = 10^{-8}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 9\\times10^{9}\\cdot\\dfrac{2\\times10^{-8}\\cdot 10^{-8}}{0{,}04} = 9\\times10^{9}\\cdot\\dfrac{2\\times10^{-16}}{0{,}04}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9\\times10^{9}\\cdot 5\\times10^{-15} = 4{,}5\\times10^{-5}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì hai điện tích cùng dấu nên lực là lực đẩy. Độ lớn lực tương tác là $4{,}5\\times10^{-5}\\ \\text{N}$, suy ra $X = 4{,}5$.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":11,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"4,5","question":"Trong các hệ thống điện tích điểm, lực tương tác giữa các điện tích tuân theo định luật Coulomb. Hiện tượng này có ý nghĩa quan trọng trong các lĩnh vực như tĩnh điện học, hoạt động của các phân tử sinh học và ứng dụng trong công nghệ nano. Hai điện tích điểm q1 = −2×10<sup>−8</sup> C, q2 = −10−8 C được đặt cách nhau 20 cm trong không khí. Biết hằng số Coulomb k = 9×10<sup>9</sup> N⋅m2/C2. Lực tương tác giữa chúng bằng X.10<sup>−5</sup> N. Xác định giá trị X (làm tròn một chữ số thập phân sau dấu phẩy). (0,5 điểm)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác giữa hai điện tích điểm đặt trong không khí có độ lớn: $F = k\\dfrac{|q_1 q_2|}{r^2}$, trong đó $r$ là khoảng cách giữa hai điện tích.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 20\\ \\text{cm} = 0{,}2\\ \\text{m}$, $r^2 = 0{,}04\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q_1| = 2\\times10^{-8}\\ \\text{C}$, $|q_2| = 10^{-8}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 9\\times10^{9}\\cdot\\dfrac{2\\times10^{-8}\\cdot 10^{-8}}{0{,}04} = 9\\times10^{9}\\cdot\\dfrac{2\\times10^{-16}}{0{,}04}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9\\times10^{9}\\cdot 5\\times10^{-15} = 4{,}5\\times10^{-5}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì hai điện tích cùng dấu nên lực là lực đẩy. Độ lớn lực tương tác là $4{,}5\\times10^{-5}\\ \\text{N}$, suy ra $X = 4{,}5$.</p>","difficultySource":"ai"}}]},{"id":1182346,"nq":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"1,2","question":"Cho hai bản kim loại phẳng đặt nằm ngang mang điện tích trái dấu có cường độ điện trường là 4000 V/m. Biết hạt bụi có điện tích là q=3.10<sup>−10</sup> C đang nằm giữa 2 bản kim loại đó. Để hạt bụi nằm cân bằng giữa 2 bản kim loại thì khối lượng của hạt bụi bằng Z.10<sup>−7</sup> kg? Cho g=10$m/s^2$. Xác định giá trị Z (Làm tròn một số thập phân sau dấu phẩy). (0,5 điểm)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt bụi nằm cân bằng lơ lửng giữa hai bản nên chịu hai lực: trọng lực $P = mg$ hướng xuống và lực điện $F = qE$ hướng lên. Điều kiện cân bằng là hai lực này cân bằng nhau về độ lớn.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng: $qE = mg$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = \\dfrac{qE}{g}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $m = \\dfrac{3.10^{-10} \\cdot 4000}{10} = 1,2.10^{-7}\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">So sánh với $Z.10^{-7}\\ \\text{kg}$ ta được $Z = 1,2$.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":13,"el":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"1,2","question":"Cho hai bản kim loại phẳng đặt nằm ngang mang điện tích trái dấu có cường độ điện trường là 4000 V/m. Biết hạt bụi có điện tích là q=3.10<sup>−10</sup> C đang nằm giữa 2 bản kim loại đó. Để hạt bụi nằm cân bằng giữa 2 bản kim loại thì khối lượng của hạt bụi bằng Z.10<sup>−7</sup> kg? Cho g=10m/s2. Xác định giá trị Z (Làm tròn một số thập phân sau dấu phẩy). (0,5 điểm)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt bụi nằm cân bằng lơ lửng giữa hai bản nên chịu hai lực: trọng lực $P = mg$ hướng xuống và lực điện $F = qE$ hướng lên. Điều kiện cân bằng là hai lực này cân bằng nhau về độ lớn.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng: $qE = mg$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m = \\dfrac{qE}{g}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $m = \\dfrac{3.10^{-10} \\cdot 4000}{10} = 1,2.10^{-7}\\ \\text{kg}$</p><p class=\"text-base leading-relaxed my-2\">So sánh với $Z.10^{-7}\\ \\text{kg}$ ta được $Z = 1,2$.</p>","difficultySource":"ai"}}]},{"id":1182347,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"20","question":"Trong vật lý, thế năng tĩnh điện của một hạt mang điện trong điện trường phụ thuộc vào vị trí của nó. Điều này có ý nghĩa quan trọng trong các hiện tượng như phóng điện trong khí quyển và hoạt động của linh kiện bán dẫn. Một electron có thế năng tĩnh điện tại một điểm trong điện trường của một điện tích điểm Q tạo ra bằng −32×10<sup>−19</sup>J. Biết rằng mốc để tính thế năng tĩnh điện được chọn ở vô cực. Nếu điện tích của electron là −1,6×10<sup>−19</sup>C, thì điện thế tại điểm đó bằng bao nhiêu V? (0,5 điểm)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện thế tại một điểm trong điện trường được xác định bởi công thức $V = \\dfrac{W_M}{q}$, trong đó $W_M$ là thế năng tĩnh điện của điện tích $q$ đặt tại điểm đó (mốc thế năng tại vô cực).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $W_M = -32\\times10^{-19}\\ \\text{J}$ và $q = -1,6\\times10^{-19}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$V = \\dfrac{-32\\times10^{-19}}{-1,6\\times10^{-19}} = 20\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại điểm đó bằng $20\\ \\text{V}$.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"20","question":"Trong vật lý, thế năng tĩnh điện của một hạt mang điện trong điện trường phụ thuộc vào vị trí của nó. Điều này có ý nghĩa quan trọng trong các hiện tượng như phóng điện trong khí quyển và hoạt động của linh kiện bán dẫn. Một electron có thế năng tĩnh điện tại một điểm trong điện trường của một điện tích điểm Q tạo ra bằng −32×10<sup>−19</sup>J. Biết rằng mốc để tính thế năng tĩnh điện được chọn ở vô cực. Nếu điện tích của electron là −1,6×10<sup>−19</sup>C, thì điện thế tại điểm đó bằng bao nhiêu V? (0,5 điểm)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện thế tại một điểm trong điện trường được xác định bởi công thức $V = \\dfrac{W_M}{q}$, trong đó $W_M$ là thế năng tĩnh điện của điện tích $q$ đặt tại điểm đó (mốc thế năng tại vô cực).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $W_M = -32\\times10^{-19}\\ \\text{J}$ và $q = -1,6\\times10^{-19}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$V = \\dfrac{-32\\times10^{-19}}{-1,6\\times10^{-19}} = 20\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại điểm đó bằng $20\\ \\text{V}$.</p>","difficultySource":"ai"}}]},{"id":1182693,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":0,"options":["-4,5 V.","0,018 V.","45 V.","-18 V."],"question":"Công của lực điện trong dịch chuyển điện tích q = 2 mC từ điểm M đến điểm N trong điện trường đều có giá trị là -9.10<sup>−3</sup> J. Hiệu điện thế UMN có giá trị là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi dịch chuyển điện tích $q$ từ $M$ đến $N$ trong điện trường được tính theo công thức: $A_{MN} = q\\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra hiệu điện thế: $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $q = 2\\ \\text{mC} = 2\\cdot 10^{-3}\\ \\text{C}$; $A_{MN} = -9\\cdot 10^{-3}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U_{MN} = \\dfrac{-9\\cdot 10^{-3}}{2\\cdot 10^{-3}} = -4{,}5\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $U_{MN} = -4{,}5\\ \\text{V}$, chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":816,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":0,"options":["-4,5 V.","0,018 V.","45 V.","-18 V."],"question":"Công của lực điện trong dịch chuyển điện tích q = 2 mC từ điểm M đến điểm N trong điện trường đều có giá trị là -9.10<sup>−3</sup> J. Hiệu điện thế UMN có giá trị là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi dịch chuyển điện tích $q$ từ $M$ đến $N$ trong điện trường được tính theo công thức: $A_{MN} = q\\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra hiệu điện thế: $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $q = 2\\ \\text{mC} = 2\\cdot 10^{-3}\\ \\text{C}$; $A_{MN} = -9\\cdot 10^{-3}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U_{MN} = \\dfrac{-9\\cdot 10^{-3}}{2\\cdot 10^{-3}} = -4{,}5\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $U_{MN} = -4{,}5\\ \\text{V}$, chọn đáp án A.</p>","difficultySource":"ai"}}]},{"id":1182694,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":1,"options":["2.10<sup>−6</sup><br>C.","8.10<sup>−5</sup><br>C.","8.10<sup>−6</sup><br>C.","125.10<sup>−3</sup><br>C."],"question":"Một tụ có điện dung 8 μF. Khi đặt một hiệu điện thế 10 V vào 2 bản của tụ điện thì tụ tích được một điện lượng là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích tụ tích được khi đặt hiệu điện thế $U$ vào hai bản tụ có điện dung $C$ được xác định bởi công thức: $Q = C.U$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 8\\ \\mu F = 8.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 8.10^{-6} \\cdot 10 = 8.10^{-5}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Vậy tụ tích được điện lượng $8.10^{-5}\\ C$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":816,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":1,"options":["2.10<sup>−6</sup><br>C.","8.10<sup>−5</sup><br>C.","8.10<sup>−6</sup><br>C.","125.10<sup>−3</sup><br>C."],"question":"Một tụ có điện dung 8 μF. Khi đặt một hiệu điện thế 10 V vào 2 bản của tụ điện thì tụ tích được một điện lượng là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích tụ tích được khi đặt hiệu điện thế $U$ vào hai bản tụ có điện dung $C$ được xác định bởi công thức: $Q = C.U$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 8\\ \\mu F = 8.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 8.10^{-6} \\cdot 10 = 8.10^{-5}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Vậy tụ tích được điện lượng $8.10^{-5}\\ C$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1182698,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một hạt bụi có khối lượng m = 10-6 g nằm cân bằng trong khoảng giữa hai bản kim loại phẳng đặt nằm ngang, song song với nhau và tích điện trái dấu, khoảng cách giữa hai bản là 12cm. Điện trường giữa hai bản là điện trường đều có vectơ cường độ điện trường hướng thẳng đứng lên trên và có độ lớn là E = 2000 V/m. Lấy g = 10 $m/s^2$.","difficulty":"trung-binh","statements":[{"text":"Hạt bụi nhiễm điện âm.","answer":false},{"text":"Bản kim loại nhiễm điện âm ở phía trên, bản kim loại nhiễm điện dương ở phía dưới.","answer":true},{"text":"Hiệu điện thế giữa hai bản này là 240 V.","answer":true},{"text":"Điện tích của hạt bụi có độ lớn là 5.10<sup>−9</sup> C.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 10^{-6}$ g $= 10^{-9}$ kg; $d = 12$ cm $= 0{,}12$ m.</p><p class=\"text-base leading-relaxed my-2\">Hạt bụi cân bằng nên lực điện cân bằng với trọng lực. Trọng lực hướng xuống nên lực điện phải hướng lên, cùng chiều với $\\vec{E}$ (hướng thẳng đứng lên trên).</p><p class=\"text-base leading-relaxed my-2\">a) Vì lực điện $\\vec{F}$ cùng chiều $\\vec{E}$ nên hạt bụi mang điện <b>dương</b>. Ý a) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) Đường sức điện đi từ bản dương sang bản âm và hướng thẳng đứng lên trên, nên bản dưới tích điện dương, bản trên tích điện âm. Ý b) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">c) Hiệu điện thế giữa hai bản:</p><p class=\"text-base leading-relaxed my-2\">$U = E\\cdot d = 2000 \\cdot 0{,}12 = 240$ V. Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Điều kiện cân bằng: $|q|E = mg$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |q| = \\dfrac{mg}{E} = \\dfrac{10^{-9}\\cdot 10}{2000} = 5\\cdot 10^{-12}$ C.</p><p class=\"text-base leading-relaxed my-2\">Đề ghi $5\\cdot 10^{-9}$ C là sai. Ý d) <b>Sai</b>.</p>","difficultySource":"ai"},"ex":[{"exam":816,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một hạt bụi có khối lượng m = 10-6 g nằm cân bằng trong khoảng giữa hai bản kim loại phẳng đặt nằm ngang, song song với nhau và tích điện trái dấu, khoảng cách giữa hai bản là 12cm. Điện trường giữa hai bản là điện trường đều có vectơ cường độ điện trường hướng thẳng đứng lên trên và có độ lớn là E = 2000 V/m. Lấy g = 10 m/s2.","difficulty":"trung-binh","statements":[{"text":"Hạt bụi nhiễm điện âm.","answer":false},{"text":"Bản kim loại nhiễm điện âm ở phía trên, bản kim loại nhiễm điện dương ở phía dưới.","answer":true},{"text":"Hiệu điện thế giữa hai bản này là 240 V.","answer":true},{"text":"Điện tích của hạt bụi có độ lớn là 5.10<sup>−9</sup> C.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1182699,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho hai điện tích điểm q1 = 4.10<sup>−8</sup> C, q2 = -10-8 C được đặt cách nhau 10 cm trong không khí.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác giữa hai điện tích điểm này là lực hút.","answer":true},{"text":"Các đường sức điện của điện trường xung quanh hai điện tích q1 và q2 xuất phát ở q2 và kết thúc ở q1.","answer":false},{"text":"Độ lớn lực tương tác điện là F = 36.10<sup>−5</sup> N.","answer":true},{"text":"Giữ nguyên độ lớn hai điện tích và môi trường đặt hai điện tích, muốn tăng độ lớn lực tương tác lên 4 lần thì phải giảm khoảng cách giữa hai điện tích còn 5 cm.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Dữ kiện: $q_1 = 4.10^{-8}$ C, $q_2 = -10^{-8}$ C, $r = 10$ cm $= 0{,}1$ m, đặt trong không khí ($\\varepsilon = 1$).</p><p class=\"text-base leading-relaxed my-2\"><b>a) Đúng.</b> Hai điện tích trái dấu ($q_1 \\gt 0$, $q_2 \\lt 0$) nên lực tương tác giữa chúng là lực hút.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Sai.</b> Đường sức điện xuất phát từ điện tích dương và kết thúc ở điện tích âm. Vì vậy các đường sức xuất phát từ $q_1$ (dương) và kết thúc ở $q_2$ (âm), không phải ngược lại.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Đúng.</b> Áp dụng định luật Culông, với $k = 9.10^9$ N.m²/C²:</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot \\dfrac{4.10^{-8}\\cdot 10^{-8}}{0{,}1^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot \\dfrac{4.10^{-16}}{10^{-2}} = 36.10^{-5}$ N $\\approx 3{,}6.10^{-4}$ N.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Khi độ lớn điện tích và môi trường không đổi, $F \\propto \\dfrac{1}{r^2}$. Để $F' = 4F$ thì:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{r'^2}{r^2} = \\dfrac{F}{F'} = \\dfrac{1}{4}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r' = \\dfrac{r}{2} = 5$ cm.</p>","difficultySource":"ai"},"ex":[{"exam":816,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho hai điện tích điểm q1 = 4.10<sup>−8</sup> C, q2 = -10-8 C được đặt cách nhau 10 cm trong không khí.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác giữa hai điện tích điểm này là lực hút.","answer":true},{"text":"Các đường sức điện của điện trường xung quanh hai điện tích q1 và q2 xuất phát ở q2 và kết thúc ở q1.","answer":false},{"text":"Độ lớn lực tương tác điện là F = 36.10<sup>−5</sup> N.","answer":true},{"text":"Giữ nguyên độ lớn hai điện tích và môi trường đặt hai điện tích, muốn tăng độ lớn lực tương tác lên 4 lần thì phải giảm khoảng cách giữa hai điện tích còn 5 cm.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1182701,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"4","question":"Một hạt bụi mang điện tích q đặt tại điểm N nằm giữa hai bản kim loại phẳng song song, tích điện trái dấu và cách bản âm 1,2 cm. Chọn mốc điện thế tại bản âm, người ta đo được thế năng điện tại điểm N là WN = 0,024 J. Biết cường độ điện trường giữa hai bản kim loại có độ lớn là 5.10<sup>4</sup> V/m. Điện tích q có độ lớn là X.10<sup>−5</sup> C. Tìm giá trị của X.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện thế tại điểm N so với bản âm (mốc điện thế bằng 0): trong điện trường đều giữa hai bản phẳng, $V_N = E\\cdot d_N$, với $d_N$ là khoảng cách từ N đến bản âm.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d_N = 1{,}2\\ \\text{cm} = 0{,}012\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Điện thế tại N: $V_N = E\\cdot d_N = 5\\cdot 10^4 \\cdot 0{,}012 = 600\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Thế năng điện của điện tích q tại N: $W_N = q\\cdot V_N$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |q| = \\dfrac{|W_N|}{V_N} = \\dfrac{0{,}024}{600} = 4\\cdot 10^{-5}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 4$.</p>","difficultySource":"ai"},"ex":[{"exam":816,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"4","question":"Một hạt bụi mang điện tích q đặt tại điểm N nằm giữa hai bản kim loại phẳng song song, tích điện trái dấu và cách bản âm 1,2 cm. Chọn mốc điện thế tại bản âm, người ta đo được thế năng điện tại điểm N là WN = 0,024 J. Biết cường độ điện trường giữa hai bản kim loại có độ lớn là 5.10<sup>4</sup> V/m. Điện tích q có độ lớn là X.10<sup>−5</sup> C. Tìm giá trị của X.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1183455,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"-9","question":"Khi một điện tích q = 2.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì công của lực điện -18.10<sup>−6</sup> J . Hiệu điện thế giữa M và N là bao nhiêu V?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích q di chuyển từ M đến N được tính theo hiệu điện thế: $A_{MN} = q\\cdot U_{MN}$, suy ra $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $A_{MN} = -18\\cdot 10^{-6}\\ \\text{J}$ và $q = 2\\cdot 10^{-6}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$U_{MN} = \\dfrac{-18\\cdot 10^{-6}}{2\\cdot 10^{-6}} = -9\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế giữa M và N là $U_{MN} = -9\\ \\text{V}$. Dấu âm cho thấy điện thế tại M thấp hơn điện thế tại N.</p>","difficultySource":"ai"},"ex":[{"exam":818,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"-9","question":"Khi một điện tích q = 2.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì công của lực điện -18.10<sup>−6</sup> J . Hiệu điện thế giữa M và N là bao nhiêu V?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích q di chuyển từ M đến N được tính theo hiệu điện thế: $A_{MN} = q\\cdot U_{MN}$, suy ra $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $A_{MN} = -18\\cdot 10^{-6}\\ \\text{J}$ và $q = 2\\cdot 10^{-6}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$U_{MN} = \\dfrac{-18\\cdot 10^{-6}}{2\\cdot 10^{-6}} = -9\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế giữa M và N là $U_{MN} = -9\\ \\text{V}$. Dấu âm cho thấy điện thế tại M thấp hơn điện thế tại N.</p>","difficultySource":"ai"}}]},{"id":1183458,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"8","question":"Độ lớn lực tương tác tĩnh điện giữa electron và proton khi đặt trong chân không và cách nhau là 5,3.10<sup>−11</sup> m là x.10<sup>−8</sup> N. Biết electron và proton lần lượt tích điện âm và dương với cùng độ lớn của điện tích nguyên tố 1,6.10<sup>−19</sup> C. Giá trị x là bao nhiêu? (Kết quả làm tròn đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không là:</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $|q_1| = |q_2| = 1{,}6.10^{-19}\\ \\text{C}$ (điện tích electron và proton có cùng độ lớn), $r = 5{,}3.10^{-11}\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$F = 9.10^9 \\cdot \\dfrac{(1{,}6.10^{-19})^2}{(5{,}3.10^{-11})^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot \\dfrac{2{,}56.10^{-38}}{2{,}809.10^{-21}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F \\approx 8{,}20.10^{-8}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x \\approx 8{,}20$, làm tròn đến chữ số hàng đơn vị được $x = 8$.</p>","difficultySource":"ai"},"ex":[{"exam":818,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"8","question":"Độ lớn lực tương tác tĩnh điện giữa electron và proton khi đặt trong chân không và cách nhau là 5,3.10<sup>−11</sup> m là x.10<sup>−8</sup> N. Biết electron và proton lần lượt tích điện âm và dương với cùng độ lớn của điện tích nguyên tố 1,6.10<sup>−19</sup> C. Giá trị x là bao nhiêu? (Kết quả làm tròn đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không là:</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $|q_1| = |q_2| = 1{,}6.10^{-19}\\ \\text{C}$ (điện tích electron và proton có cùng độ lớn), $r = 5{,}3.10^{-11}\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$F = 9.10^9 \\cdot \\dfrac{(1{,}6.10^{-19})^2}{(5{,}3.10^{-11})^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot \\dfrac{2{,}56.10^{-38}}{2{,}809.10^{-21}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F \\approx 8{,}20.10^{-8}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x \\approx 8{,}20$, làm tròn đến chữ số hàng đơn vị được $x = 8$.</p>","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
